# Frontends send the company PAN card under either key.
PAN_CARD_FILE_KEYS = ('file_selfCertifiedCompanyPANCard', 'file_pan')


def save_pan_card_file(request):
    """Save the PAN card upload if one was sent. Returns (path, error);
    both are None when no PAN card was uploaded."""
    for key in PAN_CARD_FILE_KEYS:
        if request.FILES.get(key):
            path = save_file(request, key, 'fileuploads/man')
            if not path:
                return None, f"Invalid file for 'PAN Card' ({key}). Allowed types: PDF, PNG, JPG, XLS, XLSX. Max size: 1 MB."
            return path, None
    return None, None


def save_file(request, tag, path):
    uploaded_file = request.FILES.get(tag)
    if not uploaded_file:
        return None 
        return Response({'error': f"File not found"}, status=400)
    #Response({'error': f"Invalid file type. Allowed types are:"}, status=400)

    # Validate file size (should be less than 1 MB)
    max_file_size = 1 * 1024 * 1024  # 1 MB in bytes
    if uploaded_file.size > max_file_size:
        return None 
        return Response({'error': f"File size should be less than 1 MB. Current size: {uploaded_file.size / (1024 * 1024):.2f} MB"}, status=400)

    # Validate file type using magic numbers
    valid_mime_types = {
        'image/png': 'png',
        'image/jpeg': 'jpg',
        'application/pdf': 'pdf',
        'application/vnd.ms-excel': 'xls',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    }

    # Use python-magic to detect the MIME type
    try:
        mime = magic.Magic(mime=True)
        mime_type = mime.from_buffer(uploaded_file.read(2048) or b'')  # Read the first 2 KB of the file
    except Exception:
        return None
    finally:
        try:
            uploaded_file.seek(0)
        except Exception:
            pass

    if mime_type not in valid_mime_types:
        return None 
        return Response({'error': f"Invalid file type. Allowed types are: {', '.join(valid_mime_types.keys())}"}, status=400)

    # Additional validation to prevent executable files
    uploaded_file.seek(0)  # Reset file pointer to the beginning
    file_content = uploaded_file.read(2048)  # Read the first 2 KB of the file
    data = file_content
    if data.startswith(b"MZ") or data.startswith(b"\x7FELF") or data.startswith(b"\xcf\xfa\xed\xfe") or \
        data.startswith(b"\xce\xfa\xed\xfe") or \
        data.startswith(b"\xca\xfe\xba\xbe") or data.startswith(b"#!"):
        return None
    
    file_extension = valid_mime_types[mime_type]
    file_name = ''.join(secrets.choice('0123456789') for _ in range(40)) + "." + file_extension

    clean_path = path.lstrip('./')
    # Build the MinIO object key, always rooted under fileuploads/
    if not clean_path.startswith('fileuploads/') and clean_path != 'fileuploads':
        object_key = 'fileuploads/' + clean_path.rstrip('/') + '/' + file_name
    else:
        object_key = clean_path.rstrip('/') + '/' + file_name

    uploaded_file.seek(0)
    file_bytes = uploaded_file.read()
    try:
        from . import minio_storage
        minio_storage.upload_bytes(object_key, file_bytes, mime_type)
    except Exception:
        return None

    # Return the relative path stored in the database (same shape as before)
    return clean_path.rstrip('/') + '/' + file_name



def find_file_in_folders(filename, folders):
    """Locate *filename* in the MinIO bucket and return its object key, or None."""
    from . import minio_storage

    filename_clean = filename.replace("%20", " ").lstrip('/')

    # Build candidate object keys that mirror the key structure used in save_file
    candidates = []
    if not filename_clean.startswith('fileuploads/'):
        candidates.append('fileuploads/' + filename_clean)
    candidates.append(filename_clean)

    for key in candidates:
        if minio_storage.object_exists(key):
            return key
    return None
# The folders list is kept for backward-compatible function signatures;
# actual storage is now in MinIO (local disk is no longer used).
