@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])  # Apply throttling here
@require_http_methods(['GET', 'POST'])
@require_permission('gps_history', 'view')
def downloadfile(request): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    if request.method == 'POST': 
        file_path =   request.data.get('file_path') 
        #print(request.content_type )
        #print(request.data)
        #print(request.user )

        if not file_path:
            return JsonResponse({'error': 'file_path is required'}, status=400) 
        try:
            # Extract just the filename for the response header
            filename = os.path.basename(file_path)
            
            # Try to find the file first with the full path
            full_path = find_file_in_folders(file_path, folders)
            
            # If that fails, try with just the filename
            if not full_path:
                filename_only = os.path.basename(file_path)
                full_path = find_file_in_folders(filename_only, folders)
                
            if not full_path:
                return JsonResponse({'error': f'file not found: {file_path}'}, status=400) 
                
            try:
                from . import minio_storage
                file_bytes = minio_storage.download_bytes(full_path)
                response = HttpResponse(file_bytes, content_type='application/octet-stream')
                response['Content-Disposition'] = f'attachment; filename="{filename}"'
                return response
            except Exception:
                return HttpResponse("File not found.", status=404) 
        except DeviceTag.DoesNotExist:
            return JsonResponse({'error': 'Error in reading file.'}, status=404)
    return JsonResponse({'error': 'Only POST requests are allowed.'}, status=405)



def apply_low_pass_filter(queryset, columns):
    # Get the values of the specified columns from the queryset
    column_values = {col: list(queryset.values_list(col, flat=True)) for col in columns}

    # Apply low-pass filter and median filter to each column
    for col, values in column_values.items():
        normalized_values,meanv,std_value = normalize(values)
        median_filtered_values = median_filter(normalized_values)
        low_pass_filtered_values = moving_average_filter(median_filtered_values, window_size=10) #low_pass_filter(median_filtered_values)
        column_values[col] = unnormalize(low_pass_filtered_values,meanv,std_value)
         

    # Update the queryset with the filtered values
    for i, entry in enumerate(queryset):
        for col, values in column_values.items():
            setattr(entry, col, values[i])

    return queryset

def low_pass_filter(data, cutoff_freq=0.4, sampling_rate=1.0, order=16):


    # Design a Butterworth low-pass filter
    nyquist = 0.5 * sampling_rate
    normal_cutoff = cutoff_freq / nyquist
    b, a = butter(order, normal_cutoff, btype='low', analog=False)

    # Initialize filtered data with the first value
    filtered_data = [data[0]]

    # Initialize the state for the filter
    zi = [0] * (max(len(a), len(b)) - 1)
    
    # Apply the filter to the remaining data
    for value in data[1:]:
        filtered_value, zi = lfilter(b, a, [value], zi=zi)
        filtered_data.append(filtered_value[0])

    return filtered_data
def moving_average_filter(data, window_size=5):
    # Apply a simple moving average filter to the data
    filtered_data = np.convolve(data, np.ones(window_size) / window_size, mode='same')
    return filtered_data.tolist()
def normalize(data):
    # Normalize the data to have zero mean and unit variance
    mean_value = np.mean(data)
    std_value = np.std(data)
    normalized_data = [(x - mean_value) / std_value for x in data]

    return [normalized_data,mean_value,std_value]
def unnormalize(data,mean_value,std_value):
    # Normalize the data to have zero mean and unit variance
    
    normalized_data = [ mean_value+ (x*std_value) for x in data]

    return normalized_data

def median_filter(data, kernel_size=3):
    # Apply a median filter to the data
    filtered_data = np.convolve(data, np.ones(kernel_size) / kernel_size, mode='same')

    return filtered_data.tolist()
 

  

from itertools import chain

# Remove the custom model_to_dict function and use Django's built-in version
# which is already imported from django.forms.models


def _gps_scope_by_role(request, queryset, module='gps_tracking'):
    """Apply role-based scoping to a GPSData queryset via the RBAC engine.

    Returns (scoped_queryset, None) on success, or
            (None, JsonResponse)  on error/no-access.

    The optional *module* parameter lets callers declare which permission
    module to look up (defaults to 'gps_tracking' so all existing call
    sites remain unchanged without modification).
    """
    if not (request.user and request.user.is_authenticated):
        return None, JsonResponse({'error': 'User not authenticated.'}, status=401)

    from .rbac import apply_gps_scope
    qs, err = apply_gps_scope(request.user, module, queryset)
    if err:
        return None, JsonResponse(err, status=400)
    return qs, None


@csrf_exempt   
@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@require_permission('gps_tracking', 'view')
def gps_track_data_api(request ):  
    
    if request.method == 'GET':
        imei = request.GET.get('imei', None)
        regno = request.GET.get('regno', None)
        # Filters
        manufacturer_id = request.GET.get('manufacturer_id', None)
        make_text = request.GET.get('make', None)  # DeviceTag.vehicle_make (partial text)
        category_param = request.GET.get('category', None)  # DeviceTag.category (id or text)

        district_id = request.GET.get('district_id', None)
        district_text = request.GET.get('district', None)  # Settings_District.district (partial text)

        # Geofence filter params
        route_id = request.GET.get('route_id', None)
        roads_param = request.GET.get('roads', None)  # legacy/alias for route_id

        poi_id = request.GET.get('poi_id', None)
        poi_param = request.GET.get('poi', None)  # legacy/alias for poi_id

        polygon_param = request.GET.get('polygon', None)  # Expects JSON string: [[lat,lon],[lat,lon],...]

        # Speed filter (live vehicle speed >= speed_limit)
        speed_limit_param = request.GET.get('speed_limit', None)

        # Normalize geofence params: treat '', 'None', 'null', 'undefined' as absent
        import json
        def _norm(v):
            if v is None:
                return None
            if isinstance(v, str) and v.strip().lower() in ('', 'none', 'null', 'undefined'):
                return None
            return v
        # Apply legacy aliases when modern param not present
        if route_id is None:
            route_id = roads_param
        if poi_id is None:
            poi_id = poi_param

        route_id = _norm(route_id)
        poi_id = _norm(poi_id)
        polygon_param = _norm(polygon_param)
        manufacturer_id = _norm(manufacturer_id)
        make_text = _norm(make_text)
        category_param = _norm(category_param)
        district_id = _norm(district_id)
        district_text = _norm(district_text)
        speed_limit_param = _norm(speed_limit_param)
        # If polygon is a JSON string, treat empty/short polygons as absent
        if isinstance(polygon_param, str):
            try:
                _poly_tmp = json.loads(polygon_param)
                if isinstance(_poly_tmp, list) and len(_poly_tmp) < 3:
                    polygon_param = None
            except Exception:
                # Invalid JSON polygon -> ignore
                polygon_param = None
        # Attempt to coerce IDs to int when present
        try:
            route_id = int(route_id) if route_id is not None else None
        except Exception:
            route_id = None
        try:
            poi_id = int(poi_id) if poi_id is not None else None
        except Exception:
            poi_id = None
        try:
            manufacturer_id = int(manufacturer_id) if manufacturer_id is not None else None
        except Exception:
            manufacturer_id = None
        try:
            district_id = int(district_id) if district_id is not None else None
        except Exception:
            district_id = None

        # Category can be id or text
        category_id = None
        category_text = None
        if category_param is not None:
            try:
                if str(category_param).strip().isdigit():
                    category_id = int(str(category_param).strip())
                else:
                    category_text = str(category_param).strip()
            except Exception:
                category_id = None
                category_text = None

        try:
            speed_limit = int(speed_limit_param) if speed_limit_param is not None else None
        except Exception:
            speed_limit = None
        in_range = True
        in_range_param = request.GET.get('in_range', None)
        if in_range_param is not None:
            in_range = str(in_range_param).lower() == 'true'
        # Optional historical snapshot: last packet per device before this datetime
        history_dt = _parse_dt_param(_norm(request.GET.get('history_datetime', None)))
        # New owner name substring filter
        owner_name_substr = request.GET.get('owner', None)
        # New road/city substring filter (applies to latest entry per device_tag)
        poi_t = _norm(request.GET.get('poi_t', None))
        poi_t_cf = str(poi_t).casefold() if poi_t is not None else None

        # Get base queryset. Driven from DeviceTag (small table, ~100k rows)
        # rather than GPSData (11M+ rows): the latest packet per device is
        # pulled via a correlated subquery further down, using the
        # (device_tag, id) index for a fast per-device lookup instead of a
        # full-table GROUP BY scan (see gps_track_lite_api for precedent —
        # that scan pattern caused 60s+ timeouts on this endpoint).
        device_tag_qs = DeviceTag.objects.filter(status='Owner_Final_OTP_Verified')

        # Filter by imei if provided (partial match)
        if imei and imei != "None":
            device_tag_qs = device_tag_qs.filter(device__imei__icontains=imei)
        # Filter by regno if provided (partial match)
        if regno and regno != "None":
            device_tag_qs = device_tag_qs.filter(vehicle_reg_no__icontains=regno)
        # Filter by vehicle make (partial match, case-insensitive)
        if make_text is not None:
            device_tag_qs = device_tag_qs.filter(vehicle_make__icontains=str(make_text))
        # Filter by manufacturer id via DeviceTag -> DeviceStock -> Dealer -> Manufacturer
        if manufacturer_id is not None:
            device_tag_qs = device_tag_qs.filter(device__dealer__manufacturer__id=manufacturer_id)
        # Filter by vehicle category (id or text)
        if category_id is not None:
            device_tag_qs = device_tag_qs.filter(category_id=category_id)
        elif category_text is not None:
            device_tag_qs = device_tag_qs.filter(category__category__icontains=category_text)
        # Filter by district id / district name
        if district_id is not None:
            device_tag_qs = device_tag_qs.filter(district__id=district_id)
        if district_text is not None:
            device_tag_qs = device_tag_qs.filter(district__district__icontains=str(district_text))
        # Filter by configured max speed for the vehicle category
        if speed_limit is not None:
            # Settings_VehicleCategory.maxSpeed is stored as text; allow leading zeros
            device_tag_qs = device_tag_qs.filter(category__maxSpeed__regex=rf'^0*{speed_limit}$')
        # Owner name filter (device_tag-level attribute)
        if owner_name_substr:
            device_tag_qs = device_tag_qs.filter(
                vehicle_owner__users__name__icontains=owner_name_substr
            )
        # poi_t (road/city substring) is a packet-level attribute; it's applied
        # inside the latest-packet subquery below, not here.
        poi_t_cf = None

        # Apply role-based filtering
        device_tag_qs, _role_err = _dt_scope_by_role(request, device_tag_qs)
        if _role_err:
            return _role_err

        # --- Geofence filter logic ---
        polygon = None
        geofence_center = None  # (lat, lon) center for POI radius filter
        geofence_message = None
        buffer_distance = 0.1  # 0.1 km = 100m
        from shapely.geometry import Point, Polygon, LineString
        import json
        # Select active geofence with precedence: POI > Route > Polygon
        geofence_count = sum([1 if x is not None else 0 for x in [route_id, poi_id, polygon_param]])
        active_type = 'poi' if poi_id is not None else ('route' if route_id is not None else ('polygon' if polygon_param is not None else None))
        if geofence_count > 1 and active_type:
            geofence_message = f"Multiple geofence params provided; using {active_type}."
        if active_type == 'route':
            try:
                route = Route.objects.get(id=route_id)
                points = []
                if hasattr(route, 'routepoints'):
                    if isinstance(route.routepoints, str):
                        points = json.loads(route.routepoints)
                    else:
                        points = route.routepoints
                coords = []
                for pt in points:
                    if isinstance(pt, dict):
                        coords.append((float(pt['lon']), float(pt['lat'])))
                    elif isinstance(pt, (list, tuple)) and len(pt) >= 2:
                        coords.append((float(pt[1]), float(pt[0])))
                if coords:
                    line = LineString(coords)
                    polygon = line.buffer(buffer_distance)
                else:
                    geofence_message = "Route has no valid points. Geofence filter not applied."
            except Exception as e:
                geofence_message = f"Route geofence error: {e}. Geofence filter not applied."
        elif active_type == 'poi':
            # POI geofence: prefer polygon from POI.location when available or requested; otherwise fall back to 100m radius
            try:
                poi = pointofinterests.objects.get(id=poi_id)
                poi_location = getattr(poi, 'location', None)
                poi_as_polygon_param = request.GET.get('poi_as_polygon', None)
                use_polygon = False
                if poi_as_polygon_param is not None:
                    use_polygon = str(poi_as_polygon_param).strip().lower() == 'true'

                built_polygon = False
                if poi_location and (use_polygon or (getattr(poi, 'lat', None) is None or getattr(poi, 'lon', None) is None)):
                    try:
                        loc_coords = json.loads(poi_location) if isinstance(poi_location, str) else poi_location
                        poly_coords = []
                        if isinstance(loc_coords, list):
                            for item in loc_coords:
                                if isinstance(item, (list, tuple)) and len(item) >= 2:
                                    # Expect [lat, lon]
                                    lat_i = float(item[0])
                                    lon_i = float(item[1])
                                    poly_coords.append((lon_i, lat_i))
                                elif isinstance(item, dict) and 'lat' in item and 'lon' in item:
                                    poly_coords.append((float(item['lon']), float(item['lat'])))
                        if len(poly_coords) >= 3:
                            polygon = Polygon(poly_coords)
                            built_polygon = True
                            geofence_message = 'Using POI location polygon geofence.'
                        else:
                            geofence_message = 'POI location polygon invalid or too few points; falling back to radius.'
                    except Exception as e:
                        geofence_message = f'POI polygon parse error: {e}; falling back to radius.'

                if not built_polygon:
                    poi_lat = getattr(poi, 'lat', None)
                    poi_lon = getattr(poi, 'lon', None)
                    if poi_lat is not None and poi_lon is not None:
                        geofence_center = (float(poi_lat), float(poi_lon))
                    else:
                        # Neither valid polygon nor lat/lon available -> return blank per request
                        return JsonResponse({'data': [], 'geofence_message': 'POI has neither lat/lon nor valid polygon. Returning blank.'})
            except Exception as e:
                # POI lookup failed -> return blank
                return JsonResponse({'data': [], 'geofence_message': f'POI lookup error: {e}. Returning blank.'})
        elif active_type == 'polygon':
            try:
                coords = json.loads(polygon_param)
                poly_coords = [(float(lon), float(lat)) for lon, lat in coords]
                if poly_coords:
                    polygon = Polygon(poly_coords)
                else:
                    geofence_message = "Custom polygon has no valid points. Geofence filter not applied."
            except Exception as e:
                geofence_message = f"Custom polygon geofence error: {e}. Geofence filter not applied."
        # --- End geofence logic ---

        include_proximity = str(request.GET.get('include_proximity', 'false')).strip().lower() == 'true'

        # --- Helper utilities for nearest POI / Route proximity ---
        import time as _time
        _t0 = _time.perf_counter()

        # Haversine distance in kilometers
        def haversine_km(lat1, lon1, lat2, lon2):
            R = 6371.0
            dlat = radians(lat2 - lat1)
            dlon = radians(lon2 - lon1)
            a = sin(dlat / 2) ** 2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlon / 2) ** 2
            return 2 * R * asin(sqrt(a))

        _poi_index = []          # (lat, lon, poi, serialized_data)
        _police_poi_index = []
        _route_index = []        # (list_of_(lat,lon), serialized_route)

        # Build proximity indexes only when explicitly requested.
        if include_proximity:
            try:
                all_pois = list(pointofinterests.objects.all())
            except Exception:
                all_pois = []
            _t1 = _time.perf_counter()
            #print(f"TIMING: poi_fetch={_t1-_t0:.3f}s  count={len(all_pois)}")
        else:
            all_pois = []
            _t1 = _time.perf_counter()
            #print(f"TIMING: proximity_index_skipped={_t1-_t0:.3f}s")

        # Build pre-computed (lat, lon, poi) tuples — parse JSON location once per POI
        def _extract_poi_coord(poi):
            if getattr(poi, 'lat', None) is not None and getattr(poi, 'lon', None) is not None:
                try:
                    return float(poi.lat), float(poi.lon)
                except (TypeError, ValueError):
                    pass
            loc = getattr(poi, 'location', None)
            if not loc:
                return None
            try:
                coords = json.loads(loc) if isinstance(loc, str) else loc
                lats, lons = [], []
                if isinstance(coords, list):
                    for item in coords:
                        if isinstance(item, (list, tuple)) and len(item) >= 2:
                            lats.append(float(item[0]))
                            lons.append(float(item[1]))
                        elif isinstance(item, dict) and 'lat' in item and 'lon' in item:
                            lats.append(float(item['lat']))
                            lons.append(float(item['lon']))
                if lats and lons:
                    return sum(lats) / len(lats), sum(lons) / len(lons)
            except Exception:
                pass
            return None

        # Pre-build coordinate + serialized-data tuples for all POIs (done once)
        for _p in all_pois:
            _c = _extract_poi_coord(_p)
            if _c is None:
                continue
            _sd = PointOfInterestSerializer(_p).data
            _entry = (_c[0], _c[1], _p, _sd)
            _poi_index.append(_entry)
            if getattr(_p, 'use_type', None) == 'police':
                _police_poi_index.append(_entry)
        _t2 = _time.perf_counter()
        #print(f"TIMING: poi_serialize={_t2-_t1:.3f}s  poi_index={len(_poi_index)}")

        # Pre-build route point arrays and serialize once
        if include_proximity:
            try:
                all_routes = list(Route.objects.all())
            except Exception:
                all_routes = []
        else:
            all_routes = []
        _t3 = _time.perf_counter()
        #print(f"TIMING: route_fetch={_t3-_t2:.3f}s  count={len(all_routes)}")

        # _route_index: list of (list_of_(lat,lon)_tuples, serialized_route)
        for _r in all_routes:
            _pts_raw = None
            if hasattr(_r, 'route') and getattr(_r, 'route') is not None:
                _pts_raw = getattr(_r, 'route')
            elif hasattr(_r, 'routepoints') and getattr(_r, 'routepoints') is not None:
                _pts_raw = getattr(_r, 'routepoints')
            if not _pts_raw:
                continue
            try:
                _pts = json.loads(_pts_raw) if isinstance(_pts_raw, str) else _pts_raw
            except Exception:
                continue
            _coords = []
            if isinstance(_pts, list):
                for _pt in _pts:
                    if isinstance(_pt, (list, tuple)) and len(_pt) >= 2:
                        _coords.append((float(_pt[1]), float(_pt[0])))  # (lat, lon)
                    elif isinstance(_pt, dict) and 'lat' in _pt and 'lon' in _pt:
                        _coords.append((float(_pt['lat']), float(_pt['lon'])))
            if _coords:
                _route_index.append((_coords, routeSerializer(_r).data))
        _t4 = _time.perf_counter()
        #print(f"TIMING: route_serialize={_t4-_t3:.3f}s  route_index={len(_route_index)}")

        def nearest_poi_info(lat, lon, poi_index):
            best_dist = None
            best_entry = None
            for (plat, plon, _poi, _sd) in poi_index:
                d = haversine_km(lat, lon, plat, plon)
                if best_dist is None or d < best_dist:
                    best_dist = d
                    best_entry = (_poi, _sd)
            if best_entry is None:
                return None
            return {
                'data': best_entry[1],
                'distance_meters': int(round((best_dist or 0) * 1000)),
            }

        def routes_within_100m(lat, lon):
            results = []
            for (_coords, _rdata) in _route_index:
                min_km = None
                for (lat_r, lon_r) in _coords:
                    d = haversine_km(lat, lon, lat_r, lon_r)
                    if min_km is None or d < min_km:
                        min_km = d
                    if min_km is not None and min_km <= 0.1:
                        break  # early exit: already within 100m
                if min_km is not None and min_km <= 0.1:
                    results.append({
                        'data': _rdata,
                        'min_distance_meters': int(round(min_km * 1000)),
                    })
            return results
        # --- End helper utilities ---

        from .serializers import DeviceTagSerializer, VehicleOwnerSerializer, UserSerializer

        # Pagination first, then process only requested page to avoid O(all vehicles)
        # per-request work that causes upstream 504 timeouts.
        try:
            _page = int(request.GET.get('page', 0))
        except (ValueError, TypeError):
            _page = 0
        try:
            _page_length = int(request.GET.get('page_length', 100))
            if _page_length < 1:
                _page_length = 100
        except (ValueError, TypeError):
            _page_length = 100

        want_count = str(request.GET.get('count', 'true')).lower() != 'false'
        _start = _page * _page_length

        # Latest matching packet per device_tag, found via a correlated
        # subquery keyed by device_tag_id. This lets Postgres use the
        # gpsdata_tag_id_asc_idx (device_tag, id) index for one backward
        # index scan per device instead of a GROUP BY + MAX(id) aggregate
        # over the entire GPSData table (which forced a full sequential
        # scan + hash join and caused 60s+ timeouts on this endpoint).
        latest_gps_filter = Q(device_tag_id=OuterRef('id'), gps_status=1)
        latest_order = ['-id']
        if history_dt is not None:
            # No GPSData rows have a null packet_datetime in production, so
            # the historical snapshot can be expressed as a single equality
            # on packet_datetime — this lets Postgres use
            # gpsdata_tag_packet_dt_idx (device_tag, -packet_datetime, -id)
            # to seek straight to the right position per device. Mixing in
            # an OR'd entry_time fallback (even though it never matches any
            # row today) defeats that index-driven plan and forces a scan
            # of each device's full history.
            latest_gps_filter &= Q(packet_datetime__lte=history_dt)
            latest_order = ['-packet_datetime', '-id']

        latest_gps_id_sq = GPSData.objects.filter(latest_gps_filter).order_by(*latest_order).values('id')[:1]

        device_tag_qs = device_tag_qs.annotate(
            latest_gps_id=Subquery(latest_gps_id_sq)
        ).exclude(latest_gps_id=None)

        # poi_t matches the device's current (latest) packet's road/city.
        # road/city have no supporting index for substring search, so a
        # correlated EXISTS() gets rewritten by Postgres into a hash join
        # against a full sequential scan of GPSData (11M+ rows). Instead,
        # resolve latest_gps_id for every candidate device (cheap, already
        # index-driven above), bulk-fetch just those rows' road/city by
        # primary key (an indexed IN lookup), and filter in Python before
        # paginating — same result, no table scan.
        if poi_t is not None:
            poi_t_cf_local = str(poi_t).casefold()
            id_pairs = list(device_tag_qs.values_list('id', 'latest_gps_id'))
            latest_ids_all = [lid for _, lid in id_pairs if lid]
            matching_gps_ids = {
                gid for gid, road, city in GPSData.objects.filter(
                    id__in=latest_ids_all
                ).values_list('id', 'road', 'city')
                if (road and poi_t_cf_local in road.casefold())
                or (city and poi_t_cf_local in city.casefold())
            }
            matching_dt_ids = [dtid for dtid, lid in id_pairs if lid in matching_gps_ids]
            device_tag_qs = device_tag_qs.filter(id__in=matching_dt_ids)

        device_tag_qs = device_tag_qs.order_by('id')

        _total = device_tag_qs.count() if want_count else None

        page_device_tags = list(
            device_tag_qs.select_related(
                'device',
                'device__dealer',
                'device__dealer__manufacturer',
                'vehicle_owner',
                'category',
                'district',
                'district__state',
            ).prefetch_related('vehicle_owner__users')[_start:_start + _page_length]
        )

        paginated_ids = [dt.latest_gps_id for dt in page_device_tags if dt.latest_gps_id]
        id_to_entry = {g.id: g for g in GPSData.objects.filter(id__in=paginated_ids)}
        latest_entries = [
            id_to_entry[dt.latest_gps_id]
            for dt in page_device_tags
            if dt.latest_gps_id in id_to_entry
        ]
        device_tag_map = {dt.id: dt for dt in page_device_tags}

        _t5 = _time.perf_counter()
        #print(
        #    f"TIMING: db_query={_t5-_t4:.3f}s  page_rows={len(latest_entries)}  "
        #    f"page={_page} page_length={_page_length} total={_total if _total is not None else 'skipped'}"
        #)

        data = []
        for latest_entry in latest_entries:
            if latest_entry:
                # Filter by poi_t in latest GPSData.road or GPSData.city (case-insensitive substring)
                if poi_t_cf:
                    road_value = getattr(latest_entry, 'road', None)
                    city_value = getattr(latest_entry, 'city', None)
                    road_cf = str(road_value).casefold() if road_value is not None else ''
                    city_cf = str(city_value).casefold() if city_value is not None else ''
                    if poi_t_cf not in road_cf and poi_t_cf not in city_cf:
                        continue
                # Geofence filter: check polygon containment OR POI radius
                if polygon is not None:
                    lat = getattr(latest_entry, 'latitude', None)
                    lon = getattr(latest_entry, 'longitude', None)
                    if lat is not None and lon is not None:
                        pt = Point(float(lon), float(lat))
                        inside = polygon.contains(pt)
                        if (in_range and not inside) or (not in_range and inside):
                            continue  # skip this point
                elif geofence_center is not None:
                    lat = getattr(latest_entry, 'latitude', None)
                    lon = getattr(latest_entry, 'longitude', None)
                    if lat is not None and lon is not None:
                        center_lat, center_lon = geofence_center
                        d_km = haversine_km(float(lat), float(lon), center_lat, center_lon)
                        inside = d_km <= 0.1  # within 100 meters
                        if (in_range and not inside) or (not in_range and inside):
                            continue
                serializer = GPSData_Serializer(latest_entry)
                dd = serializer.data.copy()
                dd['packet_datetime'] = latest_entry.packet_datetime.isoformat() if latest_entry.packet_datetime else None
                device_tag_obj = device_tag_map.get(getattr(latest_entry, 'device_tag_id', None))
                if device_tag_obj:
                    dd['vehicle_registration_number'] = device_tag_obj.vehicle_reg_no
                    dd['imei'] = device_tag_obj.device.imei if device_tag_obj.device else None
                    dd['with_trailer'] = device_tag_obj.with_trailer
                    dd['trailer_id'] = device_tag_obj.trailer_id
                    device_tag_data = DeviceTagSerializer(device_tag_obj).data
                    # Attach concise device/manufacturer summary for convenience
                    try:
                        ds = device_tag_obj.device  # DeviceStock
                        dealer_obj = getattr(ds, 'dealer', None)
                        man_obj = getattr(dealer_obj, 'manufacturer', None) if dealer_obj else None
                        device_summary = {
                            'id': ds.id,
                            'imei': ds.imei,
                        }
                        if dealer_obj:
                            device_summary['dealer'] = {
                                'id': dealer_obj.id,
                                'company_name': getattr(dealer_obj, 'company_name', None),
                            }
                        if man_obj:
                            device_summary['manufacturer'] = {
                                'id': man_obj.id,
                                'company_name': getattr(man_obj, 'company_name', None),
                            }
                        device_tag_data['device_info'] = device_summary
                    except Exception:
                        pass
                    if device_tag_obj.vehicle_owner:
                        owner_data = VehicleOwnerSerializer(device_tag_obj.vehicle_owner).data
                        if 'users' not in owner_data:
                            owner_data['users'] = UserSerializer(device_tag_obj.vehicle_owner.users.all(), many=True).data
                        device_tag_data['vehicle_owner'] = owner_data
                    dd['device_tag_info'] = device_tag_data
                else:
                    dd['vehicle_registration_number'] = ""
                    dd['imei'] = ""
                    dd['with_trailer'] = False
                    dd['trailer_id'] = None
                    dd['device_tag_info'] = None

                # Attach nearest POI, nearest Police POI, and nearby Routes (<=100m)
                lat = getattr(latest_entry, 'latitude', None)
                lon = getattr(latest_entry, 'longitude', None)
                if include_proximity and lat is not None and lon is not None:
                    np_info = nearest_poi_info(float(lat), float(lon), _poi_index)
                    npp_info = nearest_poi_info(float(lat), float(lon), _police_poi_index)
                    near_rs = routes_within_100m(float(lat), float(lon))
                else:
                    np_info = None
                    npp_info = None
                    near_rs = []
                dd['nearest_poi'] = np_info
                dd['nearest_police'] = npp_info
                dd['nearby_routes_within_100m'] = near_rs
                data.append(dd)
        _t6 = _time.perf_counter()
        #print(f"TIMING: per_vehicle_loop={_t6-_t5:.3f}s  output={len(data)}  TOTAL={_t6-_t0:.3f}s")
        response = {'data': data}
        if geofence_message:
            response['geofence_message'] = geofence_message
        response['pagination'] = {
            'total': _total,
            'page': _page,
            'page_length': _page_length,
            'total_pages': (math.ceil(_total / _page_length) if (_total is not None and _page_length > 0) else None),
        }
        return JsonResponse(response)
    return JsonResponse({'error':  'Invalid request method. Only GET is allowed.'}, status=400)








@api_view(['GET'])
@permission_classes([AllowAny])
@throttle_classes([AnonRateThrottle])
def gps_by_imei(request):
    """
    Public API: Get the latest GPS data for a device by IMEI.

    GET /api/gps_by_imei/?imei=<15-digit-imei>

    Returns the latest GPS packet for the device along with basic vehicle info.
    No authentication required.
    """
    imei = (request.GET.get('imei') or '').strip()

    if not imei:
        return JsonResponse({'error': 'imei query parameter is required.'}, status=400)

    if not imei.isdigit() or len(imei) != 15:
        return JsonResponse({'error': 'imei must be exactly 15 digits.'}, status=400)

    device_tag = DeviceTag.objects.filter(
        device__imei=imei,
        status='Owner_Final_OTP_Verified',
    ).select_related('device', 'vehicle_owner', 'category', 'district', 'district__state').first()

    if not device_tag:
        return JsonResponse({'error': 'Device not found or not active.'}, status=404)

    gps = (
        GPSData.objects
        .filter(device_tag=device_tag, gps_status='1')
        .order_by('-entry_time', '-id')
        .values(
            'entry_time', 'packet_datetime', 'latitude', 'longitude',
            'speed', 'heading', 'altitude', 'satellites',
            'gps_status', 'ignition_status', 'main_power_status',
            'emergency_status', 'network_operator', 'gsm_signal_strength',
            'odometer', 'city', 'road', 'district', 'state',
        )
        .first()
    )

    owner_name = None
    if device_tag.vehicle_owner:
        u = device_tag.vehicle_owner.users.first()
        if u:
            owner_name = getattr(u, 'name', None) or getattr(u, 'mobile', None)

    return JsonResponse({
        'imei': imei,
        'vehicle_reg_no': device_tag.vehicle_reg_no,
        'vehicle_make': device_tag.vehicle_make,
        'vehicle_model': device_tag.vehicle_model,
        'category': device_tag.category.category if device_tag.category else None,
        'owner_name': owner_name,
        'district': device_tag.district.district if device_tag.district else None,
        'state': device_tag.district.state.state if (device_tag.district and device_tag.district.state) else None,
        'latest_gps': gps,
    })


@csrf_exempt   
@api_view(['GET', 'POST'])
@permission_classes([AllowAny])
def gps_track_data_api_pub(request ):  
    
    if request.method == 'GET':
        imei = request.GET.get('imei', None)
        regno = request.GET.get('regno', None)
        # Filters
        manufacturer_id = request.GET.get('manufacturer_id', None)
        make_text = request.GET.get('make', None)  # DeviceTag.vehicle_make (partial text)
        category_param = request.GET.get('category', None)  # DeviceTag.category (id or text)

        district_id = request.GET.get('district_id', None)
        district_text = request.GET.get('district', None)  # Settings_District.district (partial text)

        # Geofence filter params
        route_id = request.GET.get('route_id', None)
        roads_param = request.GET.get('roads', None)  # legacy/alias for route_id

        poi_id = request.GET.get('poi_id', None)
        poi_param = request.GET.get('poi', None)  # legacy/alias for poi_id

        polygon_param = request.GET.get('polygon', None)  # Expects JSON string: [[lat,lon],[lat,lon],...]

        # Speed filter (live vehicle speed >= speed_limit)
        speed_limit_param = request.GET.get('speed_limit', None)

        # Normalize geofence params: treat '', 'None', 'null', 'undefined' as absent
        import json
        def _norm(v):
            if v is None:
                return None
            if isinstance(v, str) and v.strip().lower() in ('', 'none', 'null', 'undefined'):
                return None
            return v
        # Apply legacy aliases when modern param not present
        if route_id is None:
            route_id = roads_param
        if poi_id is None:
            poi_id = poi_param

        route_id = _norm(route_id)
        poi_id = _norm(poi_id)
        polygon_param = _norm(polygon_param)
        manufacturer_id = _norm(manufacturer_id)
        make_text = _norm(make_text)
        category_param = _norm(category_param)
        district_id = _norm(district_id)
        district_text = _norm(district_text)
        speed_limit_param = _norm(speed_limit_param)
        # If polygon is a JSON string, treat empty/short polygons as absent
        if isinstance(polygon_param, str):
            try:
                _poly_tmp = json.loads(polygon_param)
                if isinstance(_poly_tmp, list) and len(_poly_tmp) < 3:
                    polygon_param = None
            except Exception:
                # Invalid JSON polygon -> ignore
                polygon_param = None
        # Attempt to coerce IDs to int when present
        try:
            route_id = int(route_id) if route_id is not None else None
        except Exception:
            route_id = None
        try:
            poi_id = int(poi_id) if poi_id is not None else None
        except Exception:
            poi_id = None
        try:
            manufacturer_id = int(manufacturer_id) if manufacturer_id is not None else None
        except Exception:
            manufacturer_id = None
        try:
            district_id = int(district_id) if district_id is not None else None
        except Exception:
            district_id = None

        # Category can be id or text
        category_id = None
        category_text = None
        if category_param is not None:
            try:
                if str(category_param).strip().isdigit():
                    category_id = int(str(category_param).strip())
                else:
                    category_text = str(category_param).strip()
            except Exception:
                category_id = None
                category_text = None

        try:
            speed_limit = int(speed_limit_param) if speed_limit_param is not None else None
        except Exception:
            speed_limit = None

        # Public version: full registration number is compulsory
        if not regno or str(regno).strip().lower() in ('', 'none', 'null', 'undefined'):
            return JsonResponse({'error': 'regno (full vehicle registration number) is required.'}, status=400)
        regno = str(regno).strip()

        in_range = True
        in_range_param = request.GET.get('in_range', None)
        if in_range_param is not None:
            in_range = str(in_range_param).lower() == 'true'

        # New road/city substring filter (applies to the latest entry selected)
        poi_t = _norm(request.GET.get('poi_t', None))
        poi_t_cf = str(poi_t).casefold() if poi_t is not None else None

        # Get base queryset
        gps_queryset = GPSData.objects.exclude(device_tag=None).filter(gps_status=1)

        # Filter by imei if provided (partial match)
        if imei and imei != "None":
            gps_queryset = gps_queryset.filter(device_tag__device__imei__icontains=imei)
        # Public version: filter by regno (exact match)
        gps_queryset = gps_queryset.filter(device_tag__vehicle_reg_no__iexact=regno)
        # Filter by vehicle make (partial match, case-insensitive)
        if make_text is not None:
            gps_queryset = gps_queryset.filter(device_tag__vehicle_make__icontains=str(make_text))
        # Filter by manufacturer id via DeviceTag -> DeviceStock -> Dealer -> Manufacturer
        if manufacturer_id is not None:
            gps_queryset = gps_queryset.filter(device_tag__device__dealer__manufacturer__id=manufacturer_id)
        # Filter by vehicle category (id or text)
        if category_id is not None:
            gps_queryset = gps_queryset.filter(device_tag__category_id=category_id)
        elif category_text is not None:
            gps_queryset = gps_queryset.filter(device_tag__category__category__icontains=category_text)
        # Filter by district id / district name
        if district_id is not None:
            gps_queryset = gps_queryset.filter(device_tag__district__id=district_id)
        if district_text is not None:
            gps_queryset = gps_queryset.filter(device_tag__district__district__icontains=str(district_text))
        # Filter by configured max speed for the vehicle category
        if speed_limit is not None:
            gps_queryset = gps_queryset.filter(device_tag__category__maxSpeed__regex=rf'^0*{speed_limit}$')

        # --- Geofence filter logic ---
        polygon = None
        geofence_center = None  # (lat, lon) center for POI radius filter
        geofence_message = None
        buffer_distance = 0.1  # 0.1 km = 100m
        from shapely.geometry import Point, Polygon, LineString
        import json
        # Select active geofence with precedence: POI > Route > Polygon
        geofence_count = sum([1 if x is not None else 0 for x in [route_id, poi_id, polygon_param]])
        active_type = 'poi' if poi_id is not None else ('route' if route_id is not None else ('polygon' if polygon_param is not None else None))
        if geofence_count > 1 and active_type:
            geofence_message = f"Multiple geofence params provided; using {active_type}."
        # Debug: show geofence selection
        #try:
        #    #print(f"DEBUG: geofence active_type={active_type}, poi_id={poi_id}, route_id={route_id}, polygon_present={(polygon_param is not None)}")
        #except Exception:#
        #    pass

        if active_type == 'route':
            try:
                route = Route.objects.get(id=route_id)
                points = []
                if hasattr(route, 'routepoints'):
                    if isinstance(route.routepoints, str):
                        points = json.loads(route.routepoints)
                    else:
                        points = route.routepoints
                coords = []
                for pt in points:
                    if isinstance(pt, dict):
                        coords.append((float(pt['lon']), float(pt['lat'])))
                    elif isinstance(pt, (list, tuple)) and len(pt) >= 2:
                        coords.append((float(pt[1]), float(pt[0])))
                if coords:
                    line = LineString(coords)
                    polygon = line.buffer(buffer_distance)
                else:
                    geofence_message = "Route has no valid points. Geofence filter not applied."
            except Exception as e:
                geofence_message = f"Route geofence error: {e}. Geofence filter not applied."
        elif active_type == 'poi':
            # POI geofence: prefer polygon from POI.location when available or requested; otherwise fall back to 100m radius
            try:
                poi = pointofinterests.objects.get(id=poi_id)
                poi_location = getattr(poi, 'location', None)
                poi_as_polygon_param = request.GET.get('poi_as_polygon', None)
                use_polygon = False
                if poi_as_polygon_param is not None:
                    use_polygon = str(poi_as_polygon_param).strip().lower() == 'true'

                built_polygon = False
                if poi_location and (use_polygon or (getattr(poi, 'lat', None) is None or getattr(poi, 'lon', None) is None)):
                    try:
                        loc_coords = json.loads(poi_location) if isinstance(poi_location, str) else poi_location
                        poly_coords = []
                        if isinstance(loc_coords, list):
                            for item in loc_coords:
                                if isinstance(item, (list, tuple)) and len(item) >= 2:
                                    # Expect [lat, lon]
                                    lat_i = float(item[0])
                                    lon_i = float(item[1])
                                    poly_coords.append((lon_i, lat_i))
                                elif isinstance(item, dict) and 'lat' in item and 'lon' in item:
                                    poly_coords.append((float(item['lon']), float(item['lat'])))
                        if len(poly_coords) >= 3:
                            polygon = Polygon(poly_coords)
                            built_polygon = True
                            geofence_message = 'Using POI location polygon geofence.'
                        else:
                            geofence_message = 'POI location polygon invalid or too few points; falling back to radius.'
                    except Exception as e:
                        geofence_message = f'POI polygon parse error: {e}; falling back to radius.'

                if not built_polygon:
                    poi_lat = getattr(poi, 'lat', None)
                    poi_lon = getattr(poi, 'lon', None)
                    if poi_lat is not None and poi_lon is not None:
                        geofence_center = (float(poi_lat), float(poi_lon))
                    else:
                        # Neither valid polygon nor lat/lon available -> return blank per request
                        return JsonResponse({'data': [], 'geofence_message': 'POI has neither lat/lon nor valid polygon. Returning blank.'})
            except Exception as e:
                # POI lookup failed -> return blank
                return JsonResponse({'data': [], 'geofence_message': f'POI lookup error: {e}. Returning blank.'})
        elif active_type == 'polygon':
            try:
                coords = json.loads(polygon_param)
                poly_coords = [(float(lon), float(lat)) for lon, lat in coords]
                if poly_coords:
                    polygon = Polygon(poly_coords)
                else:
                    geofence_message = "Custom polygon has no valid points. Geofence filter not applied."
            except Exception as e:
                geofence_message = f"Custom polygon geofence error: {e}. Geofence filter not applied."
        # --- End geofence logic ---

        # --- Helper utility for POI radius geofence ---
        # Haversine distance in kilometers
        def haversine_km(lat1, lon1, lat2, lon2):
            R = 6371.0
            dlat = radians(lat2 - lat1)
            dlon = radians(lon2 - lon1)
            a = sin(dlat / 2) ** 2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlon / 2) ** 2
            return 2 * R * asin(sqrt(a))

        data = []
        from .serializers import DeviceTagSerializer, VehicleOwnerSerializer, UserSerializer
        latest_entry = _gps_annotate_effective_datetime(gps_queryset).order_by('-effective_datetime', '-id')
        if imei and str(imei).strip().lower() not in ('', 'none', 'null', 'undefined'):
            latest_entry = latest_entry.filter(device_tag__device__imei__icontains=str(imei).strip())
        latest_entry = latest_entry.first()

        if latest_entry:
            # Geofence filter: check polygon containment OR POI radius
            if polygon is not None:
                lat = getattr(latest_entry, 'latitude', None)
                lon = getattr(latest_entry, 'longitude', None)
                if lat is not None and lon is not None:
                    pt = Point(float(lon), float(lat))
                    inside = polygon.contains(pt)
                    if (in_range and not inside) or (not in_range and inside):
                        latest_entry = None
            elif geofence_center is not None:
                lat = getattr(latest_entry, 'latitude', None)
                lon = getattr(latest_entry, 'longitude', None)
                if lat is not None and lon is not None:
                    center_lat, center_lon = geofence_center
                    d_km = haversine_km(float(lat), float(lon), center_lat, center_lon)
                    inside = d_km <= 0.1  # within 100 meters
                    if (in_range and not inside) or (not in_range and inside):
                        latest_entry = None

        if latest_entry and poi_t_cf:
            road_value = getattr(latest_entry, 'road', None)
            city_value = getattr(latest_entry, 'city', None)
            road_cf = str(road_value).casefold() if road_value is not None else ''
            city_cf = str(city_value).casefold() if city_value is not None else ''
            if poi_t_cf not in road_cf and poi_t_cf not in city_cf:
                latest_entry = None

        if latest_entry:
            serializer = GPSData_Serializer(latest_entry)
            dd = serializer.data.copy()
            dd['packet_datetime'] = latest_entry.packet_datetime.isoformat() if latest_entry.packet_datetime else None
            if latest_entry.device_tag:
                dd['vehicle_registration_number'] = latest_entry.device_tag.vehicle_reg_no
                dd['imei'] = latest_entry.device_tag.device.imei
                device_tag_obj = latest_entry.device_tag
                device_tag_data = DeviceTagSerializer(device_tag_obj).data
                # Attach concise device/manufacturer summary for convenience
                try:
                    ds = device_tag_obj.device  # DeviceStock
                    dealer_obj = getattr(ds, 'dealer', None)
                    man_obj = getattr(dealer_obj, 'manufacturer', None) if dealer_obj else None
                    device_summary = {
                        'id': ds.id,
                        'imei': ds.imei,
                    }
                    if dealer_obj:
                        device_summary['dealer'] = {
                            'id': dealer_obj.id,
                            'company_name': getattr(dealer_obj, 'company_name', None),
                        }
                    if man_obj:
                        device_summary['manufacturer'] = {
                            'id': man_obj.id,
                            'company_name': getattr(man_obj, 'company_name', None),
                        }
                    device_tag_data['device_info'] = device_summary
                except Exception:
                    pass
                if device_tag_obj.vehicle_owner:
                    owner_data = VehicleOwnerSerializer(device_tag_obj.vehicle_owner).data
                    if 'users' not in owner_data:
                        owner_data['users'] = UserSerializer(device_tag_obj.vehicle_owner.users.all(), many=True).data
                    device_tag_data['vehicle_owner'] = owner_data
                dd['device_tag_info'] = device_tag_data
            else:
                dd['vehicle_registration_number'] = ""
                dd['imei'] = ""
                dd['device_tag_info'] = None
            data.append(dd)

        data_list = list(data)
        response = {'data': data_list}
        if geofence_message:
            response['geofence_message'] = geofence_message
        return JsonResponse(response)
    return JsonResponse({'error':  'Invalid request method. Only GET is allowed.'}, status=400)


# ─────────────────────────────────────────────────────────────────────────────
# Lightweight GPS tracking API  – minimal fields, DB-level pagination
# GET /api/gps_track_lite/
# Params: same filter params as gps_track_data_api plus page (default 0) and
#         page_length (default 100).
# Returns: device_tag_id, vehicle_reg_no, device_stock_id, owner_name, owner_id,
#          imei, last_seen, emergency_status, speed, latitude, longitude,
#          gps_status, district, state, city
# ─────────────────────────────────────────────────────────────────────────────

def _dt_scope_by_role(request, dt_queryset, module='gps_tracking'):
    """Apply role-based scoping to a DeviceTag queryset via the RBAC engine.

    Returns (scoped_queryset, None) on success, or
            (None, JsonResponse)  on error/no-access.

    The optional *module* parameter lets callers declare which permission
    module to look up (defaults to 'gps_tracking' so all existing call
    sites remain unchanged without modification).
    """
    if not (request.user and request.user.is_authenticated):
        return None, JsonResponse({'error': 'User not authenticated.'}, status=401)

    from .rbac import apply_dt_scope
    qs, err = apply_dt_scope(request.user, module, dt_queryset)
    if err:
        return None, JsonResponse(err, status=400)
    return qs, None


@csrf_exempt
@api_view(['GET'])
@permission_classes([IsAuthenticated])
@require_permission('gps_tracking', 'view')
def gps_track_lite_api(request):
    """Lightweight GPS tracking API – returns only essential vehicle fields.

    Performance strategy: query DeviceTag first (small table), then use a
    correlated subquery to fetch only the single latest GPS row per device via
    the existing (device_tag_id, entry_time DESC, id DESC) index.  This avoids
    DISTINCT ON over the full 9M-row history table which caused 60-second
    timeouts and disk-sort spills.
    """
    def _norm(v):
        if v is None:
            return None
        if isinstance(v, str) and v.strip().lower() in ('', 'none', 'null', 'undefined'):
            return None
        return v

    imei          = _norm(request.GET.get('imei'))
    regno         = _norm(request.GET.get('regno'))
    district_id   = _norm(request.GET.get('district_id'))
    district_text = _norm(request.GET.get('district'))
    state_text    = _norm(request.GET.get('state'))
    road_text     = _norm(request.GET.get('road'))
    city_text     = _norm(request.GET.get('city'))
    poi_t_text    = _norm(request.GET.get('poi_t'))

    try:
        page = int(request.GET.get('page', 0))
    except (ValueError, TypeError):
        page = 0
    try:
        page_length = int(request.GET.get('page_length', 100))
        if page_length < 1:
            page_length = 100
    except (ValueError, TypeError):
        page_length = 100

    # ── Step 1: DeviceTag queryset with device-tag-level filters ─────────────
    dt_qs = DeviceTag.objects.filter(status='Owner_Final_OTP_Verified').select_related(
        'device',
        'vehicle_owner',
        'district',
        'district__state',
    ).prefetch_related('vehicle_owner__users')

    if imei:
        dt_qs = dt_qs.filter(device__imei__icontains=imei)
    if regno:
        dt_qs = dt_qs.filter(vehicle_reg_no__icontains=regno)
    if district_id:
        try:
            dt_qs = dt_qs.filter(district__id=int(district_id))
        except (ValueError, TypeError):
            pass

    # ── Step 2: Role-based scope on DeviceTag ─────────────────────────────────
    dt_qs, _err = _dt_scope_by_role(request, dt_qs)
    if _err:
        return _err

    # ── Step 3: Annotate with latest GPS record ID per device_tag ─────────────
    # Uses gpsdata_tag_time_id_idx (device_tag_id, entry_time DESC, id DESC)
    # — one fast index seek per device_tag, no full-table sort.
    latest_gps_id_sq = GPSData.objects.filter(
        device_tag_id=OuterRef('id'),
        gps_status=1,
    ).order_by('-entry_time', '-id').values('id')[:1]

    dt_qs = dt_qs.annotate(latest_gps_id=Subquery(latest_gps_id_sq)).exclude(latest_gps_id=None)

    # ── Step 3b: Apply GPS-level location filters BEFORE pagination ───────────
    # district, state, road, city all come from reverse-geocoded GPSData fields.
    # Using Exists() so pagination totals are correct and every matching record
    # appears regardless of which DeviceTag page it falls on.
    if any([district_text, state_text, road_text, city_text, poi_t_text]):
        geo_q = Q(id=OuterRef('latest_gps_id'))
        if district_text:
            geo_q &= Q(district__icontains=district_text)
        if state_text:
            geo_q &= Q(state__icontains=state_text)
        if road_text:
            geo_q &= Q(road__icontains=road_text)
        elif city_text:
            geo_q &= Q(city__icontains=city_text)
        elif poi_t_text:
            geo_q &= Q(Q(road__icontains=poi_t_text) | Q(city__icontains=poi_t_text))
        dt_qs = dt_qs.filter(Exists(GPSData.objects.filter(geo_q)))

    want_count = request.GET.get('count', 'true').lower() != 'false'
    total = dt_qs.count() if want_count else None

    start = page * page_length
    dt_page = list(dt_qs[start: start + page_length])

    gps_ids = [dt.latest_gps_id for dt in dt_page if dt.latest_gps_id]
    if not gps_ids:
        return JsonResponse({
            'data': [],
            'pagination': {
                'total': total,
                'page': page,
                'page_length': page_length,
                'total_pages': math.ceil(total / page_length) if (total is not None and page_length > 0) else None,
            },
        })

    # ── Step 4: Fetch those GPS rows (location filters already applied above) ──
    gps_qs = GPSData.objects.filter(id__in=gps_ids)

    gps_map = {g.device_tag_id: g for g in gps_qs}

    data = []
    for dt in dt_page:
        g = gps_map.get(dt.id)
        if g is None:
            continue  # filtered out by road/city/poi_t
        owner_name = ''
        owner_id = None
        if dt.vehicle_owner:
            owner_id = dt.vehicle_owner.id
            cached_users = getattr(dt.vehicle_owner, '_prefetched_objects_cache', {}).get('users')
            users = list(cached_users) if cached_users is not None else list(dt.vehicle_owner.users.all())
            if users:
                owner_name = getattr(users[0], 'name', '') or getattr(users[0], 'username', '')
        data.append({
            'device_tag_id':    dt.id,
            'vehicle_reg_no':   dt.vehicle_reg_no,
            'device_stock_id':  dt.device_id,
            'imei':             dt.device.imei if dt.device else None,
            'owner_name':       owner_name,
            'owner_id':         owner_id,
            'last_seen':        g.entry_time.isoformat() if g.entry_time else None,
            'packet_datetime':  g.packet_datetime.isoformat() if g.packet_datetime else None,
            'emergency_status': g.emergency_status,
            'speed':            g.speed,
            'latitude':         g.latitude,
            'longitude':        g.longitude,
            'gps_status':       g.gps_status,
            'district':         g.district or (dt.district.district if dt.district else None),
            'state':            g.state or (dt.district.state.state if (dt.district and dt.district.state) else None),
            'city':             g.city,
        })

    return JsonResponse({
        'data': data,
        'pagination': {
            'total':       total,
            'page':        page,
            'page_length': page_length,
            'total_pages': math.ceil(total / page_length) if (total is not None and page_length > 0) else None,
        },
    })


# ─────────────────────────────────────────────────────────────────────────────
# GPS Track Lite filter options API
# GET /api/gps_track_lite_options/
# Returns distinct state / district / city / road values available in the
# latest GPS records visible to the calling user.
# ─────────────────────────────────────────────────────────────────────────────
@csrf_exempt
@api_view(['GET'])
@permission_classes([IsAuthenticated])
@require_permission('gps_tracking', 'view')
def gps_track_lite_options_api(request):
    """Return distinct location values (state, district, city, road) from live GPS data."""
    dt_qs = DeviceTag.objects.filter(status='Owner_Final_OTP_Verified').only('id')
    dt_qs, _err = _dt_scope_by_role(request, dt_qs)
    if _err:
        return _err

    latest_gps_id_sq = GPSData.objects.filter(
        device_tag_id=OuterRef('id'),
        gps_status=1,
    ).order_by('-entry_time', '-id').values('id')[:1]

    gps_ids = list(
        dt_qs.annotate(latest_gps_id=Subquery(latest_gps_id_sq))
             .exclude(latest_gps_id=None)
             .values_list('latest_gps_id', flat=True)
    )

    gps_qs = GPSData.objects.filter(id__in=gps_ids)

    def _distinct_sorted(field):
        return sorted(
            gps_qs.exclude(**{field: None}).exclude(**{field: ''})
                  .values_list(field, flat=True).distinct()
        )

    return JsonResponse({
        'states':    _distinct_sorted('state'),
        'districts': _distinct_sorted('district'),
        'cities':    _distinct_sorted('city'),
        'roads':     _distinct_sorted('road'),
    })


# ─────────────────────────────────────────────────────────────────────────────
# Cluster summary API  – aggregated counts by location level
# GET /api/gps_cluster/
# Params:
#   level = district | state | city | road  (default: district)
#   All the same role/filter params as gps_track_lite_api
# Response per cluster:
#   { cluster_name, total, online, offline, emergency, moving, avg_lat, avg_lon }
# online  = last_seen within 10 minutes
# offline = last_seen older than 10 minutes
# emergency = emergency_status field indicates active SOS ('1', '0001', etc.)
# moving  = speed > 2 km/h
# ─────────────────────────────────────────────────────────────────────────────
@csrf_exempt
@api_view(['GET'])
@permission_classes([IsAuthenticated])
@require_permission('gps_clustering', 'view')
def gps_cluster_api(request):
    """Cluster summary – aggregated vehicle counts by district/state/city/road."""
    from django.db.models import Count, Avg, Case, When, IntegerField, Value, Subquery
    from django.utils import timezone as dj_timezone
    from datetime import timedelta

    VALID_LEVELS = ('district', 'state', 'city', 'road')
    level = request.GET.get('level', 'district').lower().strip()
    if level not in VALID_LEVELS:
        return JsonResponse({'error': f"Invalid level. Choose from: {', '.join(VALID_LEVELS)}"}, status=400)

    # Map level → GPSData field name used for grouping
    level_field = {
        'district': 'district',
        'state':    'state',
        'city':     'city',
        'road':     'road',
    }[level]

    def _norm(v):
        if v is None:
            return None
        if isinstance(v, str) and v.strip().lower() in ('', 'none', 'null', 'undefined'):
            return None
        return v

    # For cluster: include ALL verified devices regardless of current gps_status so
    # that every district/city/state/road that has even one device's last-known
    # position is represented in the response.
    base_qs = GPSData.objects.exclude(device_tag=None).filter(
        device_tag__status='Owner_Final_OTP_Verified'
    )

    # Optional filters (same as lite API)
    imei          = _norm(request.GET.get('imei'))
    regno         = _norm(request.GET.get('regno'))
    district_id   = _norm(request.GET.get('district_id'))
    district_text = _norm(request.GET.get('district'))
    state_text    = _norm(request.GET.get('state'))

    if imei:
        base_qs = base_qs.filter(device_tag__device__imei__icontains=imei)
    if regno:
        base_qs = base_qs.filter(device_tag__vehicle_reg_no__icontains=regno)
    if district_id:
        try:
            base_qs = base_qs.filter(device_tag__district__id=int(district_id))
        except (ValueError, TypeError):
            pass
    if district_text:
        base_qs = base_qs.filter(device_tag__district__district__icontains=district_text)
    if state_text:
        base_qs = base_qs.filter(device_tag__district__state__state__icontains=state_text)

    # Role-based scope
    base_qs, _err = _gps_scope_by_role(request, base_qs)
    if _err:
        return _err

    # Get the most-recent GPS entry per device_tag (DISTINCT ON – PostgreSQL).
    # This guarantees every device appears exactly once, using its last known
    # recorded position — whether it is currently online or offline.
    latest_ids = (
        _gps_annotate_effective_datetime(base_qs)
        .order_by('device_tag', '-effective_datetime', '-id')
        .distinct('device_tag')
        .values('id')
    )

    ONLINE_THRESHOLD = dj_timezone.now() - timedelta(minutes=10)
    EMERGENCY_STATUSES = ('1', '0001', '1111')  # adjust to your protocol values

    clusters = (
        _gps_annotate_effective_datetime(GPSData.objects)
        .filter(id__in=Subquery(latest_ids))
        # Only include rows where the reverse-geocoded level field is populated;
        # devices whose last GPS position hasn't been geocoded to this level yet
        # are excluded from that level's breakdown but counted in coarser levels.
        .exclude(**{level_field: None})
        .exclude(**{level_field: ''})
        .values(level_field)
        .annotate(
            total=Count('id'),
            online=Count(Case(
                When(effective_datetime__gte=ONLINE_THRESHOLD, then=1),
                output_field=IntegerField()
            )),
            offline=Count(Case(
                When(effective_datetime__lt=ONLINE_THRESHOLD, then=1),
                output_field=IntegerField()
            )),
            emergency=Count(Case(
                When(emergency_status__in=EMERGENCY_STATUSES, then=1),
                output_field=IntegerField()
            )),
            moving=Count(Case(
                When(speed__gt=2, then=1),
                output_field=IntegerField()
            )),
            avg_lat=Avg('latitude'),
            avg_lon=Avg('longitude'),
        )
        .order_by('-total')
    )

    data = [
        {
            'cluster_name': row[level_field],
            'level':        level,
            'total':        row['total'],
            'online':       row['online'],
            'offline':      row['offline'],
            'emergency':    row['emergency'],
            'moving':       row['moving'],
            'stationary':   row['total'] - row['moving'],
            'avg_lat':      float(row['avg_lat']) if row['avg_lat'] is not None else None,
            'avg_lon':      float(row['avg_lon']) if row['avg_lon'] is not None else None,
        }
        for row in clusters
    ]

    return JsonResponse({
        'level': level,
        'total_clusters': len(data),
        'data': data,
    })


# ─────────────────────────────────────────────────────────────────────────────
# Grid-based cluster API
# GET /api/gps_grid_cluster/
#
# Divides the Earth into uniform square cells and returns one row per cell
# that contains at least one device's last known GPS position.
#
# Param:  grid = 1 | 25 | 100 | 2500 | 40000 | 1000000  (sq km, default 100)
#   1         → ~1×1 km  cells  (cell_deg ≈ 0.009°)
#   25        → ~5×5 km  cells  (cell_deg ≈ 0.045°)
#   100       → ~10×10 km cells (cell_deg ≈ 0.090°)
#   2500      → ~50×50 km cells (cell_deg ≈ 0.449°)
#   40000     → ~200×200 km cells (cell_deg ≈ 1.796°)
#   1000000   → ~1000×1000 km cells (cell_deg ≈ 8.983°)
#
# All user-role and other filters are applied BEFORE aggregation.
#
# Response per cell:
#   grid_lat, grid_lon   – centre-point of the cell
#   grid_sq_km           – requested grid size
#   cell_deg             – approximate cell side in degrees
#   total, online, offline, emergency, moving, stationary
# ─────────────────────────────────────────────────────────────────────────────
@csrf_exempt
@api_view(['GET'])
@permission_classes([IsAuthenticated])
@require_permission('gps_clustering', 'view')
def gps_grid_cluster_api(request):
    """Grid-based cluster summary – aggregated counts per geographic grid cell."""
    from django.db.models import Count, Avg, Case, When, IntegerField, FloatField, Subquery
    from django.db.models.expressions import RawSQL
    from django.utils import timezone as dj_timezone
    from datetime import timedelta

    # ── Grid size → cell side in degrees (1° latitude ≈ 111.32 km) ──────────
    GRID_SIZES = {
        1:       round(1.0   / 111.32, 7),   # ~0.00898°
        25:      round(5.0   / 111.32, 7),   # ~0.04491°
        100:     round(10.0  / 111.32, 7),   # ~0.08983°
        2500:    round(50.0  / 111.32, 7),   # ~0.44914°
        40000:   round(200.0 / 111.32, 7),   # ~1.79628°
        1000000: round(1000.0/ 111.32, 7),   # ~8.98128°
    }

    try:
        grid_sq_km = int(request.GET.get('grid', 100))
    except (ValueError, TypeError):
        grid_sq_km = 100

    if grid_sq_km not in GRID_SIZES:
        return JsonResponse({
            'error': f"Invalid grid. Allowed values (sq km): {sorted(GRID_SIZES.keys())}"
        }, status=400)

    cell_deg = GRID_SIZES[grid_sq_km]
    half_deg = cell_deg / 2.0

    def _norm(v):
        if v is None:
            return None
        if isinstance(v, str) and v.strip().lower() in ('', 'none', 'null', 'undefined'):
            return None
        return v

    # ── Base queryset: ALL verified devices' GPS history ─────────────────────
    # (No gps_status filter so offline devices' last position is included.)
    base_qs = GPSData.objects.exclude(device_tag=None).filter(
        device_tag__status='Owner_Final_OTP_Verified',
        latitude__isnull=False,
        longitude__isnull=False,
    )

    # ── Optional pre-filters ─────────────────────────────────────────────────
    imei          = _norm(request.GET.get('imei'))
    regno         = _norm(request.GET.get('regno'))
    district_id   = _norm(request.GET.get('district_id'))
    district_text = _norm(request.GET.get('district'))
    state_text    = _norm(request.GET.get('state'))

    if imei:
        base_qs = base_qs.filter(device_tag__device__imei__icontains=imei)
    if regno:
        base_qs = base_qs.filter(device_tag__vehicle_reg_no__icontains=regno)
    if district_id:
        try:
            base_qs = base_qs.filter(device_tag__district__id=int(district_id))
        except (ValueError, TypeError):
            pass
    if district_text:
        base_qs = base_qs.filter(device_tag__district__district__icontains=district_text)
    if state_text:
        base_qs = base_qs.filter(device_tag__district__state__state__icontains=state_text)

    # ── Role-based scope (applied BEFORE aggregation) ────────────────────────
    base_qs, _err = _gps_scope_by_role(request, base_qs)
    if _err:
        return _err

    # ── Latest entry per device_tag (DISTINCT ON – PostgreSQL) ───────────────
    latest_ids = (
        _gps_annotate_effective_datetime(base_qs)
        .order_by('device_tag', '-effective_datetime', '-id')
        .distinct('device_tag')
        .values('id')
    )

    # ── Grid cell centre computed via parameterised SQL ──────────────────────
    # ROUND(...::numeric, 6) prevents floating-point grouping artefacts.
    grid_lat_expr = RawSQL(
        'ROUND((FLOOR(latitude  / %s) * %s + %s)::numeric, 6)',
        [cell_deg, cell_deg, half_deg],
        output_field=FloatField(),
    )
    grid_lon_expr = RawSQL(
        'ROUND((FLOOR(longitude / %s) * %s + %s)::numeric, 6)',
        [cell_deg, cell_deg, half_deg],
        output_field=FloatField(),
    )

    ONLINE_THRESHOLD   = dj_timezone.now() - timedelta(minutes=10)
    EMERGENCY_STATUSES = ('1', '0001', '1111')

    clusters = (
        _gps_annotate_effective_datetime(GPSData.objects)
        .filter(id__in=Subquery(latest_ids))
        .annotate(grid_lat=grid_lat_expr, grid_lon=grid_lon_expr)
        .values('grid_lat', 'grid_lon')
        .annotate(
            total=Count('id'),
            online=Count(Case(
                When(effective_datetime__gte=ONLINE_THRESHOLD, then=1),
                output_field=IntegerField()
            )),
            offline=Count(Case(
                When(effective_datetime__lt=ONLINE_THRESHOLD, then=1),
                output_field=IntegerField()
            )),
            emergency=Count(Case(
                When(emergency_status__in=EMERGENCY_STATUSES, then=1),
                output_field=IntegerField()
            )),
            moving=Count(Case(
                When(speed__gt=2, then=1),
                output_field=IntegerField()
            )),
        )
        .order_by('-total')
    )

    data = [
        {
            'grid_lat':    float(row['grid_lat']),
            'grid_lon':    float(row['grid_lon']),
            'grid_sq_km':  grid_sq_km,
            'cell_deg':    cell_deg,
            'total':       row['total'],
            'online':      row['online'],
            'offline':     row['offline'],
            'emergency':   row['emergency'],
            'moving':      row['moving'],
            'stationary':  row['total'] - row['moving'],
        }
        for row in clusters
    ]

    return JsonResponse({
        'grid_sq_km':    grid_sq_km,
        'cell_deg':      cell_deg,
        'total_cells':   len(data),
        'data':          data,
    })


@api_view(['GET'])
@permission_classes([AllowAny])
def global_counts_summary(request):
    """
    Aggregated global counts for dashboard:
    - totalPanicPress: EMCall count
    - panicActionTaken: EMCall where status != 'pending'
    - alerts: counts for key categories
    - vltStatus: DeviceTag totals by status (active/inactive) and defective devices as maintenance
    
    Returns global counts without user-based filtering.
    """
    try:
        # Panic stats (SOS) - global
        total_panic = EMCall.objects.count()
        action_taken = EMCall.objects.exclude(status='pending').count()

        # Alerts counts (key categories) - global
        alert_type_map = {
            'Overspeed': 'OverSpeed',
            'Harsh Breaking': 'HarshBreak',
            'Route Deviation': 'EmMonitorTripDeviated',
            'Tampering': 'BoxTemp',
            'Geofence Violation': 'Geofence',
        }
        alerts = []
        for label, al_type in alert_type_map.items():
            cnt = AlertsLog.objects.filter(type=al_type).count()
            alerts.append({'category': label, 'count': cnt})

        # VLT status - global
        total_vlt = DeviceTag.objects.count()
        active_vlt = DeviceTag.objects.filter(status='Owner_Final_OTP_Verified').count()
        inactive_vlt = DeviceTag.objects.filter(status='Device_Not_Active').count()
        maintenance_vlt = DeviceStock.objects.filter(stock_status='Device_Defective').count()

        result = {
            'totalPanicPress': total_panic,
            'panicActionTaken': action_taken,
            'alerts': alerts,
            'vltStatus': {
                'total': total_vlt,
                'active': active_vlt,
                'inactive': inactive_vlt,
                'maintenance': maintenance_vlt,
            },
        }
        return JsonResponse(result)
    except Exception as e:
        return JsonResponse({'error': f'Failed to compute summary: {e}'}, status=500)



def get_size(obj, seen=None):
    """Recursively finds size of objects"""
    size = sys.getsizeof(obj)
    if seen is None:
        seen = set()
    obj_id = id(obj)
    if obj_id in seen:
        return 0
    # Important mark as seen *before* entering recursion to gracefully handle
    # self-referential objects
    seen.add(obj_id)
    if isinstance(obj, dict):
        size += sum([get_size(v, seen) for v in obj.values()])
        size += sum([get_size(k, seen) for k in obj.keys()])
    elif hasattr(obj, '__dict__'):
        size += get_size(obj.__dict__, seen)
    elif hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes, bytearray)):
        size += sum([get_size(i, seen) for i in obj])
    return size

 

@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@require_http_methods(['GET', 'POST'])
@require_permission('gps_history', 'view')
def gps_history_map_data(request ): 
    mapdata = []
    try:
        vehicle_registration_number = request.GET.get('vehicle_registration_number')
        start_datetime = request.GET.get('start_datetime')
        end_datetime = request.GET.get('end_datetime')
        owner_name_substr = request.GET.get('owner_name_substr')

        # Optional payload/quality controls for long ranges
        dedupe_enabled = str(request.GET.get('dedupe', '1')).strip().lower() not in ('0', 'false', 'no')
        include_device_info_per_row = str(request.GET.get('embed_device_tag_info', '0')).strip().lower() in ('1', 'true', 'yes')
        max_points_param = request.GET.get('max_points', '12000')

        try:
            max_points = int(max_points_param)
            if max_points < 1000:
                max_points = 1000
            if max_points > 50000:
                max_points = 50000
        except (TypeError, ValueError):
            max_points = 12000

        if not vehicle_registration_number:
            return JsonResponse({'error': "Vehicle registration number is required"}, status=400)

        if not start_datetime or not end_datetime:
            return JsonResponse({'error': "Invalid Search 22"}, status=403)

        start_dt = parse_datetime(start_datetime)
        end_dt = parse_datetime(end_datetime)
        if not start_dt or not end_dt:
            return JsonResponse({'error': "Invalid datetime format for start_datetime/end_datetime"}, status=400)
        if end_dt < start_dt:
            return JsonResponse({'error': "end_datetime must be after start_datetime"}, status=400)
        if (end_dt - start_dt) > timedelta(hours=48):
            return JsonResponse({'error': "Time range cannot exceed 48 hours"}, status=400)

        if not request.user or not request.user.is_authenticated:
            return JsonResponse({'error': "Authentication required"}, status=401)

        user_role = getattr(request.user, 'role', None)
        if not user_role:
            return JsonResponse({'error': "User role not found"}, status=403)

        device_tag = DeviceTag.objects.select_related('district', 'district__state', 'vehicle_owner').filter(
            vehicle_reg_no=vehicle_registration_number,
            status='Owner_Final_OTP_Verified'
        ).first()
        if not device_tag:
            return JsonResponse({'error': "Vehicle registration number not found in system"}, status=404)

        has_access = False
        if user_role == 'superadmin':
            has_access = True
        elif user_role == 'stateadmin' and device_tag.district and device_tag.district.state:
            has_access = StateAdmin.objects.filter(users=request.user, state_id=device_tag.district.state.id).exists()
        elif user_role == 'dtorto' and device_tag.district:
            has_access = dto_rto.objects.filter(users=request.user, district=device_tag.district.district_code).exists()
        elif user_role == 'owner':
            has_access = DeviceTag.objects.filter(
                id=device_tag.id,
                status='Owner_Final_OTP_Verified',
                vehicle_owner__users=request.user
            ).exists()

        if not has_access:
            return JsonResponse({'error': "Unauthorised access to history data"}, status=403)

        base_qs = _gps_annotate_effective_datetime(
            GPSData.objects.filter(
                gps_status='1',
                device_tag_id=device_tag.id,
            )
        ).filter(effective_datetime__range=(start_dt, end_dt))

        if owner_name_substr:
            base_qs = base_qs.filter(device_tag__vehicle_owner__users__name__icontains=owner_name_substr).distinct()

        total_points_before_optimization = base_qs.count()

        # Keep DB -> Python transfer narrow and ordered for deterministic downsampling.
        rows_qs = base_qs.order_by('effective_datetime', 'id').values(
            'effective_datetime', 'entry_time', 'packet_datetime', 'packet_type',
            'latitude', 'longitude', 'speed', 'heading', 'satellites',
            'gps_status', 'altitude', 'network_operator', 'ignition_status',
            'main_power_status', 'main_input_voltage', 'internal_battery_voltage',
            'emergency_status', 'box_tamper_alert', 'gsm_signal_strength',
            'digital_input_status', 'digital_output_status', 'frame_number', 'odometer'
        )

        stride = 1
        if total_points_before_optimization > max_points:
            stride = int(math.ceil(float(total_points_before_optimization) / float(max_points)))

        data_serialized = []
        prev_signature = None
        for idx, row in enumerate(rows_qs.iterator(chunk_size=5000)):
            if stride > 1 and (idx % stride) != 0:
                continue

            signature = (
                row['latitude'],
                row['longitude'],
                row['speed'],
                row['heading'],
                row['ignition_status'],
                row['main_power_status'],
            )
            if dedupe_enabled and signature == prev_signature:
                continue
            prev_signature = signature

            point = {
                'et': row['entry_time'],
                'packet_datetime': row['packet_datetime'],
                'ps': row['packet_type'],
                'lat': row['latitude'],
                'lon': row['longitude'],
                's': row['speed'],
                'h': row['heading'],
                'sat': row['satellites'],
                'gpsS': row['gps_status'],
                'alt': row['altitude'],
                'no': row['network_operator'],
                'igs': row['ignition_status'],
                'mps': row['main_power_status'],
                'miv': row['main_input_voltage'],
                'ibv': row['internal_battery_voltage'],
                'ems': row['emergency_status'],
                'bta': row['box_tamper_alert'],
                'gss': row['gsm_signal_strength'],
                'dis': row['digital_input_status'],
                'dos': row['digital_output_status'],
                'fn': row['frame_number'],
                'om': row['odometer'],
            }
            data_serialized.append(point)

        device_tag_info = None
        if device_tag:
            from .serializers import DeviceTagSerializer
            device_tag_info = DeviceTagSerializer(device_tag).data

        if include_device_info_per_row and device_tag_info is not None:
            for item in data_serialized:
                item['device_tag_info'] = device_tag_info

        datalen = max(len(data_serialized) - 1, 0)
        return JsonResponse({
            'data': data_serialized,
            'device_tag_info': None if include_device_info_per_row else device_tag_info,
            'mapdata': mapdata,
            'mapdata_length': datalen,
            'meta': {
                'total_points_before_optimization': total_points_before_optimization,
                'total_points_returned': len(data_serialized),
                'stride': stride,
                'dedupe_enabled': dedupe_enabled,
                'max_points': max_points,
            }
        })
    except Exception as e:
        return JsonResponse({'error': "Unable to process request."})


 

