# DLT template for the technical-onboarding-approved SMS.
# TODO: dummy template ID and text — replace with the DLT-registered ones.
TECH_ONBOARDING_APPROVED_SMS_TPID = "1007000000000000001"
TECH_ONBOARDING_APPROVED_SMS_TEXT = (
    'Dear Manufacturer, the technical onboarding of your device model {model} '
    'has been successfully integrated on the SkyTron platform. -SkyTron'
)


def send_tech_onboarding_approved_sms(onboarding_request):
    """SMS the manufacturer that technical onboarding was approved. Sent to the
    company phone number, falling back to the manufacturer login's mobile.
    Never raises — an SMS failure must not undo the approval."""
    try:
        manufacturer = onboarding_request.manufacturer
        phone = manufacturer.company_phoneno
        if not phone:
            login_user = manufacturer.users.first()
            phone = login_user.mobile if login_user else None
        if not phone:
            logger.warning('Tech onboarding SMS skipped: no phone for manufacturer %s', manufacturer.id)
            return
        text = TECH_ONBOARDING_APPROVED_SMS_TEXT.format(
            model=onboarding_request.device_model.model_name,
        )
        send_SMS(phone, text, TECH_ONBOARDING_APPROVED_SMS_TPID)
    except Exception:
        logger.exception('Tech onboarding SMS failed for request %s', onboarding_request.id)


def _role_to_account_type(role: str) -> str:
    if not role:
        return "User"
    role_map = {
        "superadmin": "Super Admin",
        "stateadmin": "State Admin",
        "devicemanufacture": "Device Manufacture",
        "dealer": "Dealer",
        "owner": "Vehicle Owner",
        "esimprovider": "EsimProvider",
        "dtorto": "DTO/RTO",
        "sosadmin": "SOS Admin",
        "teamleader": "Team Leader",
        "sosexecutive": "SOS Executive",
        "filment": "Filment",
    }
    return role_map.get(str(role).strip().lower(), str(role))


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([UserRateThrottle])
@require_permission('user_management', 'create')
def resend_usercreation_otp(request):
    """Resend the user creation OTP/link.

    Input: {"user_id": <int>}
    Role/type is derived from the User model.
    """
    errors = {}

    # Only allow superadmin to resend creation OTPs (prevents abuse/spam)
    requester = request.user
    if not get_user_object(requester, "superadmin"):
        return Response({"error": "Request must be from superadmin."}, status=status.HTTP_400_BAD_REQUEST)

    user_id = request.data.get("user_id")
    if user_id in [None, ""]:
        errors["user_id"] = "user_id is required."
    else:
        try:
            user_id = int(user_id)
            if user_id <= 0:
                errors["user_id"] = "user_id must be a positive integer."
        except Exception:
            errors["user_id"] = "user_id must be a valid integer."

    if errors:
        return Response({"errors": errors}, status=status.HTTP_400_BAD_REQUEST)

    target_user = User.objects.filter(id=user_id).last()
    if not target_user:
        return Response({"error": "User not found."}, status=status.HTTP_404_NOT_FOUND)

    # If the user is already active, don't resend creation OTP.
    # (Creation OTP is intended only for pending/unverified onboarding.)
    #if str(getattr(target_user, "status", "")).lower() == "active" and bool(getattr(target_user, "is_active", False)):
    #    return Response({"error": "User already active; creation OTP cannot be resent."}, status=status.HTTP_400_BAD_REQUEST)

    token = getattr(target_user, "password", None)
    if not token:
        return Response({"error": "User activation token not available."}, status=status.HTTP_400_BAD_REQUEST)

    # If stored value is hashed/non-resendable, rotate a fresh onboarding token
    # and persist it so resend can proceed.
    token_str = str(token)
    if token_str.startswith("pbkdf2_") or "$" in token_str:
        token_str = ''.join(secrets.choice('0123456789') for _ in range(30))
        target_user.password = token_str
        target_user.save(update_fields=["password"])

    account_type = _role_to_account_type(getattr(target_user, "role", ""))
    try:
        send_usercreation_otp(target_user, token_str, account_type)
    except Exception as e:
        return Response({"error": "Failed to send OTP.", "sms_error": str(e)}, status=status.HTTP_503_SERVICE_UNAVAILABLE)

    return Response({"message": "User creation OTP sent successfully."}, status=status.HTTP_200_OK)


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([UserRateThrottle])
@require_permission('user_management', 'create')
def resend_parent_activation_otp(request):
    """Resend the account activation link to a parent user.

    Caller must be a schooladmin. The target parent must belong to the
    same school as the requesting schooladmin.

    Input: {"user_id": <int>}
    """
    errors = {}

    requester = request.user
    if requester.role != "schooladmin":
        return Response({"error": "Request must be from a schooladmin."}, status=status.HTTP_400_BAD_REQUEST)

    admin_school = School.objects.filter(users=requester).last()
    if not admin_school:
        return Response({"error": "No school associated with this schooladmin."}, status=status.HTTP_400_BAD_REQUEST)

    user_id = request.data.get("user_id")
    if user_id in [None, ""]:
        errors["user_id"] = "user_id is required."
    else:
        try:
            user_id = int(user_id)
            if user_id <= 0:
                errors["user_id"] = "user_id must be a positive integer."
        except Exception:
            errors["user_id"] = "user_id must be a valid integer."

    if errors:
        return Response({"errors": errors}, status=status.HTTP_400_BAD_REQUEST)

    parent_profile = ParentProfile.objects.filter(id=user_id, school=admin_school).select_related("user").last()
    if not parent_profile:
        return Response({"error": "Parent profile not found in your school."}, status=status.HTTP_404_NOT_FOUND)

    target_user = parent_profile.user

    token = getattr(target_user, "password", None)
    if not token:
        return Response({"error": "User activation token not available."}, status=status.HTTP_400_BAD_REQUEST)

    token_str = str(token)
    if token_str.startswith("pbkdf2_") or "$" in token_str:
        token_str = ''.join(secrets.choice('0123456789') for _ in range(30))
        target_user.password = token_str
        target_user.save(update_fields=["password"])

    try:
        send_usercreation_otp(target_user, token_str, "Parent User")
    except Exception:
        return Response({"error": "Failed to send activation link. Please try again later."}, status=status.HTTP_503_SERVICE_UNAVAILABLE)

    return Response({"message": "Parent activation link sent successfully."}, status=status.HTTP_200_OK)


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
@require_http_methods(['GET', 'POST'])
@require_permission('stateadmin_management', 'create')
def create_StateAdmin(request ):
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

        
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    role="superadmin"
    user=request.user
    uo=get_user_object(user,role)
    if not uo:
        return Response({"error":"Request must be from  "+role+'.'}, status=status.HTTP_400_BAD_REQUEST)
    
    try: 
        idProofno = request.data.get('idProofno' )  # Placeholder for idProofno
        state= request.data.get('state','')  
        
        createdby = request.user 
        date_joined = timezone.localdate()
        created = timezone.localdate()  
        expirydate = date_joined + timezone.timedelta(days=365 * 2)  # 2 years expiry date
        file_idProof = request.data.get('file_idProof')
        file_authorisation_letter = request.data.get('file_authorisation_letter')
        
         
        user,error,new_password=create_user('stateadmin',request)
        if user:         
            try: 
                # Create a savepoint for rollback if needed
                sid = transaction.savepoint()
                
                file_idProof = save_file(request,'file_idProof','fileuploads/man')
                if not file_idProof:
                    transaction.savepoint_rollback(sid)
                    return Response({'error': "Invalid file." }, status=400)
                file_authorisation_letter=save_file(request,'file_authorisation_letter','fileuploads/man')
                if not file_authorisation_letter:
                    transaction.savepoint_rollback(sid)
                    return Response({'error': "Invalid file." }, status=400)
                
                dealer, error = StateAdmin.objects.safe_create( 
                    created=created,
                    state_id=state,
                    expirydate=expirydate, 
                    idProofno=idProofno, 
                    file_idProof=file_idProof,
                    file_authorisation_letter=file_authorisation_letter,
                    createdby=createdby,
                    status="Created",
                ) 
                
                if error:
                    transaction.savepoint_rollback(sid)
                    return error  # Return the Response object from safe_create

                transaction.savepoint_commit(sid)
                
            except Exception as e:
                transaction.savepoint_rollback(sid)
                return Response({'error': "Unable to process request1."}, status=400)
            dealer.users.add(user)
            dealer.save()  # Save the dealer after adding users
            send_usercreation_otp(user,new_password,'State Admin ')
             
            return Response(StateadminSerializer(dealer).data)
        else:
            return Response(error, status=400)

    except Exception as e:
        return Response({'error': "Unable to process request."}, status=400)

