@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('emergency_management', 'view')
def DEx_getPendingCallList(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    role="sosexecutive"
    user=request.user
    uo=get_user_object(user,role)
    role2="stateadmin" 
    uo2=get_user_object(user,role2)
    role3="sosadmin"
    uo3=get_user_object(user,role3)
    if not (uo or uo2 or uo3):
        return Response({"error":"Request must be from  "+role+' or '+role2+' or '+role3+'.'}, status=status.HTTP_400_BAD_REQUEST)
    try:
        # Keep desk_ex assignment distribution fair and prevent missed calls.
        if uo2:
            _auto_reassign_stale_desk_ex_calls(state=uo2.state)
        elif uo3:
            _auto_reassign_stale_desk_ex_calls(state=uo3.state)
        elif uo and uo.user_type == 'desk_ex':
            _auto_reassign_stale_desk_ex_calls(state=uo.state)

        if uo and uo.user_type == 'desk_ex':
            user.login = True
            user.last_activity = timezone.now()
            user.save(update_fields=['login', 'last_activity'])
        if uo:
            _record_em_online_heartbeat(uo)

        # Base queryset: only pending calls, excluding closed assignments.
        # No age cutoff — a call still in status="pending" is by definition
        # unresolved, so it must stay visible no matter how old it is.
        # (An earlier start_time cutoff here caused every currently-open
        # pending call to disappear from this list once older than 30 days.)
        qs_base = (
            EMCallAssignment.objects
            .filter(call__status="pending")
            .exclude(status="closed")
        )

        # Scope selection based on role
        if uo2:
            qs = qs_base.filter(ex__state=uo2.state)
            cache_scope = f"state:{getattr(uo2.state, 'id', uo2.state_id)}"
        elif uo3:
            qs = qs_base.filter(ex__state=uo3.state)
            cache_scope = f"state:{getattr(uo3.state, 'id', uo3.state_id)}"
        else:
            qs = qs_base.filter(ex=uo)
            cache_scope = f"ex:{getattr(uo, 'id', None)}"

        # Short-lived cache to avoid repeated heavy serialization for the same scope
        cache_key = f"DEx_getPendingCallList:pending:{cache_scope}"
        cached = cache.get(cache_key)
        if cached is not None:
            return Response({"calls": cached}, status=200)

        # Eliminate FK N+1 queries across the full serializer tree
        qs = qs.select_related(
            'admin',
            'admin__state',
            'admin__createdby',
            'ex',
            'ex__state',
            'ex__createdby',
            'call',
            'call__team',
            'call__team__state',
            'call__team__teamlead',
            'call__team__teamlead__state',
            'call__team__teamlead__createdby',
            'call__team__created_by',
            'call__team__created_by__state',
            'call__team__created_by__createdby',
            'call__device',
            'call__device__device',
            'call__device__vehicle_owner',
            'call__device__category',
        ).prefetch_related(
            'admin__users',
            'ex__users',
            'call__team__members',
            'call__team__members__users',
            'call__team__teamlead__users',
            'call__team__created_by__users',
            'call__device__drivers',
        )

        # Evaluate the queryset once so we can post-process before serialising
        assignments = list(qs)

        # Batch-fetch GPS data for all devices to eliminate the per-device N+1
        # in DeviceTagSerializer2.get_deviceloc().
        device_tag_ids = list({
            a.call.device_id
            for a in assignments
            if a.call_id and a.call.device_id
        })
        if device_tag_ids:
            # One bounded (LIMIT 10) query per device instead of a single
            # order_by(device_tag_id, -id) query across all of them: some
            # devices have 100k+ historical rows, and a combined ORDER BY
            # across multiple devices can't push the per-device LIMIT down
            # to the (device_tag, id) index — it has to sort every matching
            # row for all devices before Python can bucket the top 10, which
            # hung for minutes. Looping is only as many queries as there are
            # devices with a pending call (a handful), and each is an
            # index-driven backward scan that stops after 10 rows.
            gps_by_device = {}
            for dtid in device_tag_ids:
                gps_by_device[dtid] = list(
                    GPSData.objects
                    .filter(device_tag_id=dtid, gps_status='1')
                    .order_by('-id')
                    .values(
                        'id', 'date', 'time', 'latitude', 'latitude_dir',
                        'longitude', 'longitude_dir', 'altitude', 'speed',
                        'network_operator', 'device_tag_id',
                    )[:10]
                )
            # Attach precomputed GPS vals so the serializer skips its own DB query
            for a in assignments:
                if a.call_id and a.call.device_id:
                    a.call.device._prefetched_gps_vals = gps_by_device.get(a.call.device_id, [])

        data = EMCallAssignmentSerializer(assignments, many=True).data
        cache.set(cache_key, data, timeout=5)

        if data:
            return Response({"calls": data}, status=200)
        return Response({'call': 'Not found'}, status=200)

    except Exception as e:
        return Response({'error': "Unable to process request."}, status=400)



