def _resolve_request_log_time_window(request):
    """Resolve analytics window from range or from/to query params."""
    now = timezone.now()
    range_key = str(request.GET.get('range', '1d')).strip().lower()
    range_to_delta = {
        '1d': timedelta(days=1),
        '24h': timedelta(hours=24),
        '6h': timedelta(hours=6),
        '1h': timedelta(hours=1),
        '30m': timedelta(minutes=30),
        '5m': timedelta(minutes=5),
    }

    start_dt = now - range_to_delta.get(range_key, timedelta(days=1))
    end_dt = now

    from_str = request.GET.get('from')
    to_str = request.GET.get('to')

    if from_str:
        parsed = parse_datetime(from_str)
        if parsed:
            start_dt = parsed if timezone.is_aware(parsed) else timezone.make_aware(parsed)
    if to_str:
        parsed = parse_datetime(to_str)
        if parsed:
            end_dt = parsed if timezone.is_aware(parsed) else timezone.make_aware(parsed)

    if start_dt > end_dt:
        start_dt, end_dt = end_dt, start_dt

    return start_dt, end_dt, range_key


@api_view(['GET'])
@permission_classes([AllowAny])
@throttle_classes([AnonRateThrottle])
def public_api_log_insights(request):
    """Public API to identify APIs with highest latency/failure in a given time window."""
    start_dt, end_dt, range_key = _resolve_request_log_time_window(request)

    try:
        limit = int(request.GET.get('limit', 10))
    except (TypeError, ValueError):
        limit = 10
    limit = max(1, min(limit, 50))

    metric = str(request.GET.get('metric', 'avg_response_time')).strip().lower()
    allowed_metrics = {
        'avg_response_time',
        'max_response_time',
        'failure_count',
        'failure_rate',
        'hits',
    }
    if metric not in allowed_metrics:
        metric = 'avg_response_time'

    logs_qs = RequestLog.objects.filter(timestamp__range=(start_dt, end_dt))

    summary = logs_qs.aggregate(
        total_requests=Count('id'),
        total_failures=Count('id', filter=Q(error_code__isnull=False)),
        overall_avg_response_time_ms=Avg('response_time_ms'),
    )

    total_requests = summary.get('total_requests') or 0
    total_failures = summary.get('total_failures') or 0
    overall_failure_rate = round((total_failures * 100.0 / total_requests), 2) if total_requests else 0.0

    grouped_qs = (
        logs_qs
        .values('request_url', 'request_type')
        .annotate(
            total_hits=Count('id'),
            avg_response_time_ms=Coalesce(
                Avg('response_time_ms'),
                V(0.0),
                output_field=FloatField(),
            ),
            max_response_time_ms=Coalesce(
                Cast(Max('response_time_ms'), FloatField()),
                V(0.0),
                output_field=FloatField(),
            ),
            failure_count=Count('id', filter=Q(error_code__isnull=False)),
        )
    )

    if metric == 'failure_rate':
        candidate_rows = list(grouped_qs.order_by('-failure_count', '-total_hits')[:500])
        for row in candidate_rows:
            hits = row.get('total_hits') or 0
            failures = row.get('failure_count') or 0
            row['failure_rate'] = round((failures * 100.0 / hits), 2) if hits else 0.0
        top_rows = sorted(candidate_rows, key=lambda x: (x.get('failure_rate', 0.0), x.get('failure_count', 0), x.get('total_hits', 0)), reverse=True)[:limit]
    else:
        metric_order_map = {
            'avg_response_time': '-avg_response_time_ms',
            'max_response_time': '-max_response_time_ms',
            'failure_count': '-failure_count',
            'hits': '-total_hits',
        }
        top_rows = list(grouped_qs.order_by(metric_order_map[metric], '-total_hits')[:limit])
        for row in top_rows:
            hits = row.get('total_hits') or 0
            failures = row.get('failure_count') or 0
            row['failure_rate'] = round((failures * 100.0 / hits), 2) if hits else 0.0

    return Response({
        'window': {
            'range': range_key,
            'from': start_dt.isoformat(),
            'to': end_dt.isoformat(),
        },
        'metric': metric,
        'limit': limit,
        'summary': {
            'total_requests': total_requests,
            'total_failures': total_failures,
            'overall_failure_rate': overall_failure_rate,
            'overall_avg_response_time_ms': round(summary.get('overall_avg_response_time_ms') or 0.0, 2),
        },
        'results': top_rows,
    }, status=200)
    
    
    
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_permission('user_management', 'view')
def search_request_logs(request):
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    
    
    role="superadmin"
    user=request.user
    uo=get_user_object(user,role)
    if not uo:
        return Response({"error":"Request must be from  "+role+'.'}, status=status.HTTP_400_BAD_REQUEST) 
    
    # Support both POST body and query params for flexibility
    query = (request.data.get('q') if hasattr(request, 'data') else None) or request.GET.get('q', '')
    # Get the page number from the request
    try:
        page = int(request.GET.get('page', 1))
    except (TypeError, ValueError):
        page = 1
    page = max(1, page)
    # Cap per_page to a sane upper bound to avoid heavy queries
    try:
        per_page = int(request.GET.get('per_page', 25))
    except (TypeError, ValueError):
        per_page = 25
    per_page = max(1, min(per_page, 100))

    # Time window: default to last 1 day; allow override via from/to (ISO string)
    from_str = request.GET.get('from')
    to_str = request.GET.get('to')

    # By default, do NOT return/serialize huge payload fields.
    # They dramatically slow down the endpoint even for a few rows.
    include_payload = str(request.GET.get('include_payload', '0')).lower() in {'1', 'true', 'yes'}

    now = timezone.now()
    start_dt = now - timedelta(days=1)
    end_dt = now
    if from_str:
        parsed = parse_datetime(from_str)
        if parsed:
            start_dt = parsed if timezone.is_aware(parsed) else timezone.make_aware(parsed)
    if to_str:
        parsed = parse_datetime(to_str)
        if parsed:
            end_dt = parsed if timezone.is_aware(parsed) else timezone.make_aware(parsed)

    # Guard against swapped ranges (common UI mistake)
    if start_dt and end_dt and start_dt > end_dt:
        start_dt, end_dt = end_dt, start_dt

    # Build base queryset
    logs_qs = RequestLog.objects.order_by('-id')
    # Apply time window filter (reduces scan + matches returned window metadata)
    # RequestLog uses `timestamp` (auto_now_add)
    if start_dt and end_dt:
        logs_qs = logs_qs.filter(timestamp__range=(start_dt, end_dt))
  
    # Apply text filters
    # Apply text filter only when query is provided and meaningful
    query = (query or '').strip()
    if query:
        # icontains can be expensive on large tables. Restrict to recent records first
        # Strategy: limit to a window of recent IDs to avoid scanning the entire table
        try:
            recent_window = int(request.GET.get('recent_window', 50000))
        except (TypeError, ValueError):
            recent_window = 50000
        recent_window = max(1000, min(recent_window, 200000))

        # Reuse the same queryset so the window filter is respected
        latest_id = logs_qs.values_list('id', flat=True).first()
        if latest_id:
            threshold_id = max(0, latest_id - recent_window)
            logs_qs = logs_qs.filter(id__gt=threshold_id)

        # Now apply the text filter
        logs_qs = logs_qs.filter(Q(request_url__icontains=query))

    # Select only the fields needed for the listing.
    # NOTE: RequestLog contains large TextFields (system_info/headers/incoming_data) that are expensive
    # to read and JSON-serialize; returning them only on demand speeds things up a lot.
    if include_payload:
        logs_qs = logs_qs.values(
             'request_url', 'request_type',
            'response_type', 'response_time_ms', 'error_code',  'incoming_data'
        )
    else:
        logs_qs = logs_qs.values(
             'request_url', 'request_type',
            'response_type', 'response_time_ms', 'error_code'
        )

    # Paginate the results
    paginator = Paginator(logs_qs, per_page)
    paginated_logs = paginator.get_page(page)

    # Prepare the response data
    data = {
        'results': list(paginated_logs.object_list),
        'page': paginated_logs.number,
        'total_pages': paginator.num_pages,
        'total_results': paginator.count,
        'window': {
            'from': start_dt.isoformat(),
            'to': end_dt.isoformat(),
        }
    }

    return JsonResponse(data)
  
