    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    if request.method == 'POST':
        ble_key = request.data.get('ble_key', None)
        imei=request.data.get('imei', None)
        reg_no = request.data.get('reg_no', None)
