@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('vehicle_tagging', 'update')
def TagSendOwnerOtp(request ):  
    user=request.user 
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    role="dealer"
    man=get_user_object(user,role)
    if not man:
        return Response({"error":"Request must be from "+role+"."}, status=status.HTTP_400_BAD_REQUEST)
    
    device_model_id = request.data.get('device_id')
    # Validate current status and update the status

    device_model = get_object_or_404(DeviceTag, device__id=device_model_id,  status__in=["Owner_OTP_Sent",'Dealer_OTP_Verified'])
    if STATIC_OTP_CAP:
        device_model.otp  = str(685472)
    else:
        device_model.otp = str(secrets.randbelow(1000000)).zfill(6)
    
    device_model.otp_time=timezone.now() 
    device_model.status = 'Owner_OTP_Sent'
    device_model.save()
    user=device_model.vehicle_owner.users.last()

 
    text="Dear Vehicle Owner, to confirm tagging of your VLTD with your vehicle, please enter the OTP: {}. OTP will expire in 24 hours. Please do NOT share. -SkyTron".format(device_model.otp)
    tpid="1007518520513302294"
    send_SMS( user.mobile,text,tpid) 
    send_mail(
                'Login OTP',
                text,
                'noreply@skytron.in',
                [user.email],
                fail_silently=False,
    )
    return Response({"message": "Owner OTP sent successfully."}, status=200)



@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('vehicle_tagging', 'update')
def TagSendOwnerOtpFinal(request ):  
    user=request.user 
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    role="dealer"
    man=get_user_object(user,role)
    if not man:
        return Response({"error":"Request must be from "+role+"."}, status=status.HTTP_400_BAD_REQUEST)
    
    device_model_id = request.data.get('device_id')
    # Validate current status and update the status
    #device_model = get_object_or_404(DeviceTag, id=device_model_id,   status='TempActive')
    device_model = get_object_or_404(DeviceTag, device__id=device_model_id,  status__in=['Owner_OTP_Verified','Dealer_OTP_Verified','TempActiveSent','TempActive',"Owner_Final_OTP_Sent"])

    two_days_ago = timezone.now() - timedelta(days=2)
    device_imei = device_model.device.imei if device_model.device else None
    activation_received = bool(device_imei) and ActivationCommandReply.objects.filter(
        imei=device_imei,
        timestamp__gte=two_days_ago,
    ).exists()
    if not activation_received:
        return Response(
            {"error": "Waiting for activation message from device. Please ensure the device has sent an activation reply within the last 2 days."},
            status=status.HTTP_400_BAD_REQUEST,
        )

    if STATIC_OTP_CAP:
        device_model.otp  = str(685472)
    else:
        device_model.otp = str(secrets.randbelow(1000000)).zfill(6)

    device_model.otp_time=timezone.now() 
    device_model.status = 'Owner_Final_OTP_Sent'
    device_model.save()
    user=device_model.vehicle_owner.users.last()

 
    text="Dear Vehicle Owner, to confirm tagging of your VLTD with your vehicle, please enter the OTP: {}. OTP will expire in 24 hours. Please do NOT share. -SkyTron".format(device_model.otp)
    tpid="1007518520513302294"
    send_SMS( user.mobile,text,tpid) 
    send_mail(
                'Login OTP',
                text,
                'noreply@skytron.in',
                [user.email],
                fail_silently=False,
    )
    return Response({"message": "Owner OTP sent successfully."}, status=200)


