@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('device_stock', 'filter')
def deviceStockFilter(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    user=request.user
    man=None
    data = request.data.copy()    

    is_tagged_filter = request.data.get('is_tagged')
    if user.role=="devicemanufacture":
        #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
        man=get_user_object(user,"devicemanufacture")
        data['created_by_id'] = request.user.id 
    elif user.role=="dealer":
        #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
        man=get_user_object(user,"dealer")
        data['dealer_id'] = man.id 
        #is_tagged_filter=True


    
    if not man:
        if not check_permission(user, 'device_stock', 'view'):
            return Response({"error":"Request must be from device manufacture or dealer"}, status=status.HTTP_400_BAD_REQUEST)
        # RBAC-permitted role (e.g. helpdesk) — no manufacturer/dealer filter; sees all stock

    # Deserialize the input data
    serializer = DeviceStockFilterSerializer(data=data)
    serializer.is_valid(raise_exception=True)

    # Add pagination to limit results
    page_size = min(int(request.data.get('page_size', 50)), 200)  # Max 200 records per page
    page = max(int(request.data.get('page', 1)), 1)
    offset = (page - 1) * page_size

    # Use raw SQL or values() for maximum performance
    from django.db.models import Exists, OuterRef, Case, When, BooleanField
    
    # Build the base query with only essential fields
    base_query = DeviceStock.objects.filter(**serializer.validated_data).exclude(stock_status=DEVICE_STOCK_DELETED_STATUS)
    
    # Get total count
    total_count = base_query.count()
    
    # Apply is_tagged filter at database level if specified
    if is_tagged_filter is not None:
        is_tagged_bool = is_tagged_filter == 'True'
        tagged_subquery = DeviceTag.objects.filter(device=OuterRef('pk'))
        base_query = base_query.annotate(
            is_tagged=Exists(tagged_subquery)
        ).filter(is_tagged=is_tagged_bool)
        total_count = base_query.count()
    
    # Use values() to get only required data as dictionaries (much faster than model instances)
    device_data = base_query.select_related('model', 'dealer', 'created_by').values(
        'id', 'device_esn', 'iccid', 'imei', 'telecom_provider1', 'telecom_provider2',
        'msisdn1', 'msisdn2', 'imsi1', 'imsi2', 'esim_validity', 'remarks', 'created', 'stock_status', 
        'esim_status', 'assigned', 'shipping_remark',
        # Related model fields
        'model__id', 'model__model_name', 'model__test_agency', 'model__vendor_id',
        'model__tac_no', 'model__hardware_version',
        # Dealer fields (using correct field names)
        'dealer__id', 'dealer__company_name',
        # Created by fields (using correct field names)
        'created_by__id', 'created_by__name', 'created_by__email'
    ).order_by('-id')[offset:offset + page_size]
    
    # Convert to list and add is_tagged for each item if not already filtered
    result_data = []
    device_ids = []
    
    for item in device_data:
        device_ids.append(item['id'])
        result_data.append(item)
    
    # Prefetch esim providers for all devices in this page and build a map
    esim_provider_map = {}
    if device_ids:
        from .serializers import eSimProviderSerializer
        ds_with_providers = DeviceStock.objects.filter(id__in=device_ids).prefetch_related('esim_provider')
        for ds in ds_with_providers:
            esim_provider_map[ds.id] = eSimProviderSerializer(ds.esim_provider.all(), many=True).data

    # Fetch latest device tag info for each device in this page
    device_tag_map = {}
    if device_ids:
        tag_rows = DeviceTag.objects.filter(device_id__in=device_ids).values(
            'id', 'device_id', 'vehicle_reg_no', 'engine_no', 'chassis_no',
            'vehicle_make', 'vehicle_model', 'status', 'tagged', 'vehicle_owner_id', 'tagged_by_id'
        ).order_by('device_id', '-id')
        for tag in tag_rows:
            if tag['device_id'] not in device_tag_map:
                device_tag_map[tag['device_id']] = {
                    'id': tag['id'],
                    'device_id': tag['device_id'],
                    'vehicle_reg_no': tag['vehicle_reg_no'],
                    'engine_no': tag['engine_no'],
                    'chassis_no': tag['chassis_no'],
                    'vehicle_make': tag['vehicle_make'],
                    'vehicle_model': tag['vehicle_model'],
                    'status': tag['status'],
                    'tagged': tag['tagged'],
                    'vehicle_owner_id': tag['vehicle_owner_id'],
                    'tagged_by_id': tag['tagged_by_id'],
                }

    # If is_tagged_filter was not applied, get is_tagged status for all items in one query
    if is_tagged_filter is None and device_ids:
        tagged_device_ids = set(
            DeviceTag.objects.filter(device_id__in=device_ids).values_list('device_id', flat=True)
        )
        for item in result_data:
            item['is_tagged'] = item['id'] in tagged_device_ids
    elif is_tagged_filter is not None:
        # If filtered, all items have the same is_tagged value
        for item in result_data:
            item['is_tagged'] = is_tagged_filter == 'True'
    
    # Calculate pagination info
    total_pages = (total_count + page_size - 1) // page_size
    has_next = page < total_pages
    has_previous = page > 1

    # Prefetch all COPs for all device models in this page
    device_model_ids = set()
    for item in result_data:
        if item.get('model__id'):
            device_model_ids.add(item['model__id'])
    device_model_cop_map = {}
    if device_model_ids:
        from .serializers import DeviceCOPSerializer
        all_cops = DeviceCOP.objects.filter(device_model_id__in=device_model_ids).order_by('-created')
        # Group by device_model_id
        for cop in all_cops:
            model_id = cop.device_model_id
            if model_id not in device_model_cop_map:
                device_model_cop_map[model_id] = []
            device_model_cop_map[model_id].append(DeviceCOPSerializer(cop).data)

    # Format the response to match the expected structure
    formatted_data = []
    for item in result_data:
        device_id = item['id']
        model_id = item.get('model__id')
        formatted_item = {
            'id': item['id'],
            'device_esn': item['device_esn'],
            'iccid': item['iccid'],
            'imei': item['imei'],
            'telecom_provider1': item['telecom_provider1'],
            'telecom_provider2': item['telecom_provider2'],
            'msisdn1': item['msisdn1'],
            'msisdn2': item['msisdn2'],
            'imsi1': item.get('imsi1'),
            'imsi2': item.get('imsi2'),
            'esim_validity': item['esim_validity'],
            'remarks': item['remarks'],
            'created': item['created'],
            'stock_status': item['stock_status'],
            'esim_status': item['esim_status'],
            'assigned': item['assigned'],
            'shipping_remark': item['shipping_remark'],
            'is_tagged': item.get('is_tagged', False),
            'esim_provider': esim_provider_map.get(item['id'], []),
            'model': {
                'id': item['model__id'],
                'model_name': item['model__model_name'],
                'test_agency': item['model__test_agency'],
                'vendor_id': item['model__vendor_id'],
                'tac_no': item['model__tac_no'],
                'hardware_version': item['model__hardware_version'],
            } if item['model__id'] else None,
            'dealer': {
                'id': item['dealer__id'],
                'company_name': item['dealer__company_name'],
            } if item['dealer__id'] else None,
            'created_by': {
                'id': item['created_by__id'],
                'name': item['created_by__name'],
                'email': item['created_by__email'],
            } if item['created_by__id'] else None,
            'device_tag_info': device_tag_map.get(device_id),
            # Add all COPs for this device model, latest first
            'cops': device_model_cop_map.get(model_id, []),
        }
        formatted_data.append(formatted_item)

    return JsonResponse({
        'data': formatted_data,
        'pagination': {
            'current_page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': total_pages,
            'has_next': has_next,
            'has_previous': has_previous
        }
    }, status=200)


# Tag statuses that mean "this device is not (or no longer) actively tagged
# to a vehicle" — a DeviceTag row in one of these states must not count as
# "tagged" when deciding whether a DeviceStock is free/available.
DEVICE_STOCK_UNTAGGED_TAG_STATUSES = ['TagDeleted', 'Device_Untagged', 'untaged_after_failed_taging']

DEVICE_STOCK_DELETED_STATUS = 'Deleted'

# Filter fields on DeviceStockUntaggedFilterSerializer that should be matched
# with a partial (icontains) lookup on the DeviceStock model itself.
DEVICE_STOCK_ICONTAINS_FIELDS = [
    'imei', 'iccid', 'iccid2', 'msisdn1', 'msisdn2', 'imsi1', 'imsi2',
    'device_esn', 'telecom_provider1', 'telecom_provider2', 'remarks',
]


def _strip_blank_filters(data):
    """
    Drop any key whose value is None or '' (frontends commonly send '' for
    cleared filter inputs) so those keys are treated as "not filtered"
    regardless of the underlying field type.
    """
    cleaned = {}
    for key, value in data.items():
        if value is None:
            continue
        if isinstance(value, str) and value.strip() == '':
            continue
        cleaned[key] = value
    return cleaned


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_http_methods(['GET', 'POST'])
@require_permission('device_stock', 'filter')
def deviceStockUntaggedFilter(request):
    """
    List/filter DeviceStock rows that have no *active* DeviceTag pointing at
    them (a tag in a terminal/untagged status doesn't count as tagged).
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    user = request.user
    man = None
    role_filter = Q()

    if user.role == "devicemanufacture":
        man = get_user_object(user, "devicemanufacture")
        if man:
            role_filter = Q(created_by=user)
    elif user.role == "dealer":
        man = get_user_object(user, "dealer")
        if man:
            role_filter = Q(dealer=man)

    if not man:
        if not check_permission(user, 'device_stock', 'view'):
            return Response({"error": "Request must be from device manufacture or dealer"}, status=status.HTTP_400_BAD_REQUEST)
        # RBAC-permitted role (e.g. helpdesk) — no manufacturer/dealer filter; sees all stock

    data = _strip_blank_filters(request.data.copy())
    serializer = DeviceStockUntaggedFilterSerializer(data=data)
    serializer.is_valid(raise_exception=True)
    filters = dict(serializer.validated_data)

    page_size = min(max(int(filters.pop('page_size', 50) or 50), 1), 200)
    page = max(int(filters.pop('page', 1) or 1), 1)
    offset = (page - 1) * page_size

    dealer_id = filters.pop('dealer_id', None)
    unassigned_only = filters.pop('unassigned_only', False)
    upload_file_name = filters.pop('upload_file_name', None)

    query = Q()
    for field in DEVICE_STOCK_ICONTAINS_FIELDS:
        if field in filters:
            query &= Q(**{f"{field}__icontains": filters.pop(field)})

    for field in ['model_id', 'stock_status', 'esim_status', 'upload_batch_id']:
        if field in filters:
            query &= Q(**{field: filters.pop(field)})

    if unassigned_only:
        query &= Q(dealer__isnull=True)
    elif dealer_id is not None:
        query &= Q(dealer_id=dealer_id)

    if upload_file_name:
        query &= Q(upload_batch__file_name__icontains=upload_file_name)

    from django.db.models import Exists
    active_tag_subquery = DeviceTag.objects.filter(device=OuterRef('pk')).exclude(
        status__in=DEVICE_STOCK_UNTAGGED_TAG_STATUSES
    )

    base_query = (
        DeviceStock.objects
        .filter(role_filter)
        .filter(query)
        .exclude(stock_status=DEVICE_STOCK_DELETED_STATUS)
        .annotate(is_actively_tagged=Exists(active_tag_subquery))
        .filter(is_actively_tagged=False)
    )

    total_count = base_query.count()

    device_stock = base_query.select_related(
        'model', 'dealer', 'created_by', 'upload_batch'
    ).prefetch_related('esim_provider').order_by('-id')[offset:offset + page_size]

    result_serializer = DeviceStockSerializer2(device_stock, many=True)

    total_pages = (total_count + page_size - 1) // page_size if page_size else 0

    return JsonResponse({
        'data': result_serializer.data,
        'pagination': {
            'current_page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': total_pages,
            'has_next': page < total_pages,
            'has_previous': page > 1,
        }
    }, status=200)


def _truncate_deleted_value(prefix, original_value, max_length):
    """
    Build the "deleted_<id>_<original_value>" replacement value for a unique
    field, truncated to fit the column's max_length. If the prefix alone
    already exceeds max_length, the prefix itself is truncated.
    """
    if len(prefix) >= max_length:
        return prefix[:max_length]
    available = max_length - len(prefix)
    return prefix + str(original_value)[:available]


def _get_device_stock_blocking_references(stock):
    """
    Return the list of related model names that still hold a live reference
    to this DeviceStock row, found by introspecting every FK/M2M relation
    that points at DeviceStock (so a newly added related model is picked up
    automatically). DeviceActivationLog is an immutable audit trail (see its
    docstring), not a live reference, so it never blocks a soft-delete.
    """
    blocking = []
    for rel in DeviceStock._meta.related_objects:
        if rel.related_model is DeviceActivationLog:
            continue
        related_manager = getattr(stock, rel.get_accessor_name())
        if related_manager.exists():
            blocking.append(rel.related_model.__name__)
    return blocking


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_http_methods(['GET', 'POST'])
@require_permission('device_stock', 'delete')
def deviceStockSoftDelete(request):
    """
    Soft-delete a batch of DeviceStock rows: verify ownership, block any id
    still referenced by another model, and for the rest rewrite every unique
    field to "deleted_<id>_<original_value>" and set stock_status='Deleted'.
    Nothing is hard-deleted.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    user = request.user
    stock_ids = request.data.get('stock_ids') or request.data.get('ids')
    if not isinstance(stock_ids, list) or not stock_ids:
        return JsonResponse({'error': "'stock_ids' must be a non-empty list of device stock IDs."}, status=400)

    man = None
    scope_filter = {}
    if user.role == "devicemanufacture":
        man = get_user_object(user, "devicemanufacture")
        if man:
            scope_filter = {'created_by': user}
    elif user.role == "dealer":
        man = get_user_object(user, "dealer")
        if man:
            scope_filter = {'dealer': man}

    if not man:
        if not check_permission(user, 'device_stock', 'delete'):
            return Response({"error": "Request must be from device manufacture or dealer"}, status=status.HTTP_400_BAD_REQUEST)
        # RBAC-permitted role (e.g. helpdesk) — no manufacturer/dealer scoping; can manage all stock

    deleted_ids = []
    blocked = []
    not_found = []

    for raw_id in stock_ids:
        try:
            stock_id = int(raw_id)
        except (TypeError, ValueError):
            blocked.append({'id': raw_id, 'error': 'Invalid stock id.'})
            continue

        stock = DeviceStock.objects.filter(id=stock_id, **scope_filter).exclude(
            stock_status=DEVICE_STOCK_DELETED_STATUS
        ).last()
        if not stock:
            not_found.append(stock_id)
            continue

        blocking_models = _get_device_stock_blocking_references(stock)
        if blocking_models:
            blocked.append({
                'id': stock_id,
                'error': f"Cannot delete: still referenced by {', '.join(blocking_models)}.",
            })
            continue

        with transaction.atomic():
            prefix = f"deleted_{stock_id}_"
            for field in stock._meta.get_fields():
                if isinstance(field, models.CharField) and getattr(field, 'unique', False):
                    value = getattr(stock, field.name, None)
                    if value:
                        setattr(stock, field.name, _truncate_deleted_value(prefix, value, field.max_length))
            stock.stock_status = DEVICE_STOCK_DELETED_STATUS
            stock.save()
        deleted_ids.append(stock_id)

    response_data = {
        'message': f"{len(deleted_ids)} of {len(stock_ids)} device stock record(s) deleted.",
        'deleted_ids': deleted_ids,
    }
    if blocked:
        response_data['blocked'] = blocked
    if not_found:
        response_data['not_found'] = not_found

    return JsonResponse(response_data, status=200)


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_http_methods(['GET', 'POST'])
@require_permission('device_stock', 'create')
def deviceStockCreateBulk(request ):
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    user=request.user 
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    man=get_user_object(user,"devicemanufacture")
    if not man:
        return Response({"error":"Request must be from device manufacture"}, status=status.HTTP_400_BAD_REQUEST)
    
    if 'excel_file' not in request.FILES or 'model_id' not in request.data:
        return JsonResponse({'error': 'Please provide an Excel file and model_id.'}, status=400)

    model_id = request.data['model_id']
    mod=DeviceModel.objects.filter(id=model_id,created_by=user).last()
    if not mod:
        return JsonResponse({'error': 'invalid model_id or unauthorised user.'}, status=400)

    uploaded_file_name = request.FILES['excel_file'].name
    if DeviceStockUploadBatch.objects.filter(file_name=uploaded_file_name).exists():
        return JsonResponse({'error': f"A file named '{uploaded_file_name}' has already been uploaded."}, status=400)
    upload_batch = DeviceStockUploadBatch.objects.create(
        file_name=uploaded_file_name,
        uploaded_by=user,
        device_model=mod,
    )

    esim_provider = request.data['esim_provider']
    if not isinstance(esim_provider, list)  : 
        var_str = str(esim_provider) 
        for ch in ['[', ']', '{', '}']:
            var_str = var_str.replace(ch, '')
        esim_provider = [item.strip() for item in var_str.split(',')]
    #for e in esim_provider:
    #    st=False
    #    for ee in mod.eSimProviders:
    #        if ee==e.id:
    #            True
    #    if not st:
    #        return JsonResponse({'error': 'Esim provider id='+"Unable to process request."+' is not in the devicemodel\'s esimprovider list.'}, status=400)





    try:
        excel_data = pd.read_excel(request.FILES['excel_file'], engine='openpyxl')
    except Exception as e:
        return JsonResponse({'error': 'Error reading Excel file.', 'details': "Unable to process request."}, status=400)

    # Normalize column names to lowercase so 'IMEI', 'Imei', etc. all work
    excel_data.columns = excel_data.columns.str.lower()

    headers = list(excel_data.columns)
    success_count = 0
    success_rows = []
    error_rows = []

    for index, row in excel_data.iterrows():
        # Skip the header and example rows
        if index == 0 or 'example' in str(row[0]).lower():
            continue
        try:
            a=int(row.get('imei', ''))
            #a=int(row.get('imsi1', ''))
            #if row.get('imsi2', '')!="":
            #    a=int(row.get('imsi2', ''))
        except:
            continue
            
        def clean_int_field(val):
            """Convert float-like values (e.g. 33243.0) to integer strings."""
            if val is None or val == '':
                return ''
            try:
                return str(int(float(str(val))))
            except (ValueError, TypeError):
                return str(val)

        # Extract data from the row
        # Column name mapping (Excel header → model field):
        #   "Device ESN"                  → device_esn
        #   "Primary ICCID"               → iccid
        #   "Secondary ICCID"             → iccid2
        #   "Primary Telecom Provider"    → telecom_provider1
        #   "Secondary Telecom Provider"  → telecom_provider2
        #   "Primary MSISDN"              → msisdn1
        #   "Secondary MSISDN"            → msisdn2
        data = {
            'model': model_id,
            'device_esn': row.get('device esn', ''),
            'iccid': clean_int_field(row.get('primary iccid', '')),
            'iccid2': clean_int_field(row.get('secondary iccid', '')),
            'imei': clean_int_field(row.get('imei', '')),
            'telecom_provider1': row.get('primary telecom provider', ''),
            'telecom_provider2': row.get('secondary telecom provider', ''),
            'msisdn1': clean_int_field(row.get('primary msisdn', '')),
            'msisdn2': clean_int_field(row.get('secondary msisdn', '')),
            'imsi1': clean_int_field(row.get('imsi1', '')),
            'imsi2': clean_int_field(row.get('imsi2', '')),
            'stock_status': "NotAssigned",
            'esim_status': "NotAssigned",
            'esim_provider': esim_provider,
            'remarks': row.get('remarks', ''),
            'created_by': request.user.id,
            'created': timezone.now(),
            'upload_batch': upload_batch.id,
        }

        # Pre-flight: check ALL unique fields at once and report every conflict before writing anything
        unique_fields_check = ['device_esn', 'iccid', 'imei', 'iccid2', 'msisdn1', 'msisdn2']
        unique_conflicts = {}
        for uf in unique_fields_check:
            val = data.get(uf)
            if val not in (None, '', 'None'):
                if DeviceStock.objects.filter(**{uf: val}).exists():
                    unique_conflicts[uf] = f"{uf} '{val}' already exists."
        if unique_conflicts:
            error_rows.append({'row': index + 1, 'errors': unique_conflicts})
            continue

        # Validate and create DeviceStock instance — atomic per row so no partial saves stall future retries
        serializer = DeviceStockSerializer(data=data)
        if serializer.is_valid():
            try:
                with transaction.atomic():
                    serializer.save()
                success_count += 1
                success_rows.append(index + 1)
            except Exception as save_exc:
                error_rows.append({'row': index + 1, 'errors': {'save_error': str(save_exc)}})
        else:
            error_rows.append({'row': index + 1, 'errors': serializer.errors})

    message = f'{success_count} out of {len(excel_data) - 1} provided stocks are successfully uploaded.'

    response_data = {
        'message': message,
        'success_rows': success_rows,
        'error_rows': error_rows,
    }

    return JsonResponse(response_data, status=200)

@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@transaction.atomic
@require_permission('device_stock', 'create')
def deviceStockCreate(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    user=request.user 
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    man=get_user_object(user,"devicemanufacture")
    if not man:
        return Response({"error":"Request must be from device manufacture"}, status=status.HTTP_400_BAD_REQUEST)
    mod=DeviceModel.objects.filter(id=request.data['model'],)
    if not mod.exists():
        return Response({"error": "Device model not found."}, status=status.HTTP_400_BAD_REQUEST)
    approved = DeviceModelTechnicalOnboardingRequest.objects.filter(
        device_model_id=request.data['model'],
        status='StateAdminApproved'
    ).exists()
    if not approved:
        return Response(
            {"error": "Device model does not have an approved technical onboarding (StateAdminApproved required)."},
            status=status.HTTP_400_BAD_REQUEST
        )
    # Deserialize the input data
    data = request.data.copy()
    data['created'] = timezone.now()   
    data['created_by'] = request.user.id
    data['stock_status'] =  "NotAssigned"
    data['esim_status'] =  "NotAssigned"

    def clean_int_field(val):
        if val is None or val == '':
            return ''
        try:
            return str(int(float(str(val))))
        except (ValueError, TypeError):
            return str(val)

    try:
        data['imei'] = clean_int_field(data['imei'])
        int(data['imei'])  # validate it's numeric
    except:
        return JsonResponse({"status":"Error, Invalid imei  "}, status=400)

    for field in ['iccid', 'iccid2', 'msisdn1', 'msisdn2', 'imsi1', 'imsi2']:
        if field in data:
            data[field] = clean_int_field(data[field])

    # Pre-flight: check ALL unique fields at once and report every conflict before writing anything
    unique_fields = ['device_esn', 'iccid', 'imei', 'iccid2', 'msisdn1', 'msisdn2']
    unique_conflicts = {}
    for field in unique_fields:
        val = data.get(field)
        if val not in (None, '', 'None'):
            if DeviceStock.objects.filter(**{field: val}).exists():
                unique_conflicts[field] = f"{field} '{val}' already exists."
    if unique_conflicts:
        return Response({'errors': unique_conflicts}, status=status.HTTP_400_BAD_REQUEST)

    serializer = DeviceStockSerializer(data=data)
    serializer.is_valid(raise_exception=True)

    # Save the DeviceStock instance (atomic — rolls back everything on any failure)
    serializer.save()

    return Response(serializer.data, status=201)


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('device_management', 'create')
def COPCreate(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

     
     
        
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    role="devicemanufacture"
    user=request.user
    uo=get_user_object(user,role)
    if not uo:
        return Response({"error":"Request must be from  "+role+'.'}, status=status.HTTP_400_BAD_REQUEST)
    
    manufacturer = request.user.id 
    if STATIC_OTP_CAP:
                otp  = str(685472)
    else:
                otp = str(secrets.randbelow(1000000)).zfill(6)

    new_model_create_raw = request.data.get('new_model_create', False)
    if isinstance(new_model_create_raw, str):
        new_model_create = new_model_create_raw.strip().lower() in ('true', '1', 'yes')
    else:
        new_model_create = bool(new_model_create_raw)

    cop_status = 'Manufacturer_OTP_Verified' if new_model_create else 'Manufacturer_OTP_Sent'

    data = {
        'created_by': manufacturer,
        'created': timezone.now(),  
        'status': cop_status,
        'valid':True,
        'latest':True,
        'otp_time': timezone.now(),
        'otp':otp
    }

    # Attach the file to the request data
    request_data = request.data.copy()
    request_data.update(data)

    # Create a serializer instance
    serializer = DeviceCOPSerializer(data=request_data)

    # Validate and save the data along with the file
    if serializer.is_valid():
        # Save the DeviceCOP instance
        device_cop_instance = serializer.save()

        # Handle the uploaded file
        uploaded_file = request.FILES.get('cop_file')
        if uploaded_file:
            # Save the file to a specific location
            safe_file_name = os.path.basename(uploaded_file.name)
            relative_file_path = f"fileuploads/cop_files/{device_cop_instance.id}_{safe_file_name}"
            absolute_file_path = os.path.join(HOST_STORAGE_PATH, relative_file_path)
            os.makedirs(os.path.dirname(absolute_file_path), exist_ok=True)
            with open(absolute_file_path, 'wb') as file:
                for chunk in uploaded_file.chunks():
                    file.write(chunk)
            
            # Update the cop_file field in the DeviceCOP instance
            device_cop_instance.cop_file = relative_file_path
