@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_http_methods(['GET', 'POST'])
@require_permission('manufacturer_management', 'view')
def manufacturer_device_model_overview(request):
    """
    Manufacturer dashboard: every device model of the logged-in manufacturer with
    its approval status, latest technical onboarding status, stock counts by
    stock status, tagging counts by tag status and online/offline counts.

    Online = tagged device with a GPS packet in the last 15 minutes.
    Offline = currently tagged devices - online.

    Body (optional): page (default 1), page_size (default 50, max 200).
    `totals` always cover all models; only `device_models` is paginated.
    """
    from .models import (
        DeviceModelTechnicalOnboardingDemoDevice, DeviceModelTechnicalOnboardingRequest,
        DeviceStock, DeviceTag, GPSData, Manufacturer,
    )

    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    manufacturer = get_user_object(request.user, 'devicemanufacture')
    if not manufacturer:
        return Response({'error': 'Request must be from devicemanufacture.'}, status=status.HTTP_400_BAD_REQUEST)

    manufacturer_user_ids = list(manufacturer.users.values_list('id', flat=True))
    onboarding_requests = list(
        DeviceModelTechnicalOnboardingRequest.objects
        .filter(manufacturer=manufacturer)
        .order_by('id')
    )
    onboarded_model_ids = {r.device_model_id for r in onboarding_requests}

    device_models = list(
        DeviceModel.objects
        .filter(Q(created_by_id__in=manufacturer_user_ids) | Q(id__in=onboarded_model_ids))
        .order_by('-created', '-id')
    )
    model_ids = [m.id for m in device_models]

    latest_onboarding = {}
    for r in onboarding_requests:
        latest_onboarding[r.device_model_id] = r  # ascending id, last wins

    # Stock-receipt rejection reasons, per onboarding request.
    receipt_rejections = {}
    for d in DeviceModelTechnicalOnboardingDemoDevice.objects.filter(
        onboarding_request_id__in=[r.id for r in latest_onboarding.values()], receipt_rejected=True
    ).order_by('id'):
        receipt_rejections.setdefault(d.onboarding_request_id, []).append({
            'demo_device_id': d.id,
            'imei': d.imei,
            'reason': d.receipt_reject_reason,
            'rejected_at': d.receipt_rejected_at,
        })

    def onboarding_reject_reason(req):
        if req.status == 'stock_rejected':
            return '; '.join(x['reason'] for x in receipt_rejections.get(req.id, []) if x['reason']) or None
        if req.status in ('technically_not_compatible', 'StateAdminRejected'):
            return req.final_comment
        return None

    stock_by_model = {}
    for row in (
        DeviceStock.objects.filter(model_id__in=model_ids)
        .exclude(stock_status=DEVICE_STOCK_DELETED_STATUS)
        .values('model_id', 'stock_status').annotate(c=Count('id'))
    ):
        stock_by_model.setdefault(row['model_id'], {})[row['stock_status']] = row['c']

    tag_by_model = {}
    for row in (
        DeviceTag.objects.filter(device__model_id__in=model_ids)
        .values('device__model_id', 'status').annotate(c=Count('id'))
    ):
        tag_by_model.setdefault(row['device__model_id'], {})[row['status']] = row['c']

    window_start = timezone.now() - timedelta(minutes=15)
    online_tags = (
        GPSData.objects
        .filter(entry_time__gte=window_start, device_tag__device__model_id__in=model_ids)
        .exclude(device_tag__status__in=['Device_Untagged', 'TagDeleted', 'untaged_after_failed_taging'])
        .values_list('device_tag__device__model_id', 'device_tag_id')
        .distinct()
    )
    online_by_model = {}
    for model_id, _tag_id in online_tags:
        online_by_model[model_id] = online_by_model.get(model_id, 0) + 1

    inactive_tag_statuses = {'Device_Untagged', 'TagDeleted', 'untaged_after_failed_taging'}
    result = []
    for m in device_models:
        stock = stock_by_model.get(m.id, {})
        tags = tag_by_model.get(m.id, {})
        tagged = sum(c for st, c in tags.items() if st not in inactive_tag_statuses)
        online = online_by_model.get(m.id, 0)
        onboarding = latest_onboarding.get(m.id)
        result.append({
            'device_model_id': m.id,
            'model_name': m.model_name,
            'vendor_id': m.vendor_id,
            'tac_no': m.tac_no,
            'tac_validity': m.tac_validity,
            'hardware_version': m.hardware_version,
            'created': m.created,
            'model_status': m.status,
            'reject_reason': m.reject_reason or None,
            'rejected_at': m.rejected_at,
            'technical_onboarding': {
                'request_id': onboarding.id,
                'status': onboarding.status,
                'request_datetime': onboarding.request_datetime,
                'final_comment': onboarding.final_comment,
                'reject_reason': onboarding_reject_reason(onboarding),
                'receipt_rejections': receipt_rejections.get(onboarding.id, []),
            } if onboarding else None,
            'stock': {
                'total': sum(stock.values()),
                'by_status': stock,
            },
            'tagging': {
                'total_tagged': tagged,
                'by_status': tags,
            },
            'devices': {
                'online': online,
                'offline': max(0, tagged - online),
            },
        })

    totals = {
        'total_models': len(result),
        'total_stock': sum(r['stock']['total'] for r in result),
        'total_tagged': sum(r['tagging']['total_tagged'] for r in result),
        'total_online': sum(r['devices']['online'] for r in result),
        'total_offline': sum(r['devices']['offline'] for r in result),
    }

    try:
        page = max(int(request.data.get('page', 1)), 1)
        page_size = min(max(int(request.data.get('page_size', 50)), 1), 200)
    except (TypeError, ValueError):
        return Response({'error': 'page and page_size must be integers.'}, status=status.HTTP_400_BAD_REQUEST)
    total_count = len(result)
    offset = (page - 1) * page_size

    return Response({
        'totals': totals,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size,
        },
        'device_models': result[offset:offset + page_size],
    }, status=status.HTTP_200_OK)


# Whitelisted IP / URL rules for a device model.
WHITELISTED_IP_MIN_ITEMS = 1
WHITELISTED_IP_MAX_ITEMS = 10


def _validate_whitelisted_ip(raw_value):
    """
    Validate a comma-separated list of IP addresses or URLs.

    Accepts an IPv4/IPv6 address, a full URL, or a bare hostname.
    Between 1 and 10 items. Duplicates removed, order preserved.

    Returns (cleaned_string, error_message). Exactly one is non-None.
    """
    raw_value = (raw_value or '').strip()
    if not raw_value:
        return None, 'whitelisted_ip is required. Provide at least one IP address or URL.'

    items = [part.strip() for part in raw_value.split(',') if part.strip()]
    if not items:
        return None, 'whitelisted_ip is required. Provide at least one IP address or URL.'

    if len(items) > WHITELISTED_IP_MAX_ITEMS:
        return None, (
            f'whitelisted_ip can have at most {WHITELISTED_IP_MAX_ITEMS} items. '
            f'{len(items)} were provided.'
        )

    url_validator = URLValidator()
    cleaned = []
    invalid = []

    for item in items:
        if item in cleaned:
            continue

        try:
            ipaddress.ip_address(item)
            cleaned.append(item)
            continue
        except ValueError:
            pass

        candidate = item if '://' in item else f'https://{item}'
        try:
            url_validator(candidate)
            cleaned.append(item)
            continue
        except DjangoValidationError:
            invalid.append(item)

    if invalid:
        return None, (
            'whitelisted_ip contains invalid entries: '
            + ', '.join(invalid)
            + '. Each item must be an IP address or a URL.'
        )

    return ', '.join(cleaned), None  


# Device IP range rules for an eSIM provider.
DEVICE_IP_RANGE_MIN_ITEMS = 1
DEVICE_IP_RANGE_MAX_ITEMS = 20


def _validate_device_ip_range(raw_value):
    """
    Validate a comma-separated list of IP ranges.

    Accepts either notation:
      CIDR        103.21.58.0/24
      start-end   103.21.58.1-103.21.58.50

    Between 1 and 20 ranges. Duplicates removed, order preserved.

    Returns (cleaned_string, error_message). Exactly one is non-None.
    """
    raw_value = (raw_value or '').strip()
    if not raw_value:
        return None, 'device_ip_range is required. Provide at least one IP range.'

    items = [part.strip() for part in raw_value.split(',') if part.strip()]
    if not items:
        return None, 'device_ip_range is required. Provide at least one IP range.'

    if len(items) > DEVICE_IP_RANGE_MAX_ITEMS:
        return None, (
            f'device_ip_range can have at most {DEVICE_IP_RANGE_MAX_ITEMS} ranges. '
            f'{len(items)} were provided.'
        )

    cleaned = []
    invalid = []

    for item in items:
        if item in cleaned:
            continue

        # CIDR notation
        if '/' in item:
            try:
                ipaddress.ip_network(item, strict=False)
                cleaned.append(item)
                continue
            except ValueError:
                invalid.append(item)
                continue

        # start-end notation
        if '-' in item:
            start, _, end = item.partition('-')
            try:
                start_ip = ipaddress.ip_address(start.strip())
                end_ip = ipaddress.ip_address(end.strip())
            except ValueError:
                invalid.append(item)
                continue
            if start_ip.version != end_ip.version:
                invalid.append(item)
                continue
            if start_ip > end_ip:
                invalid.append(item)
                continue
            cleaned.append(item)
            continue

        invalid.append(item)

    if invalid:
        return None, (
            'device_ip_range contains invalid entries: '
            + ', '.join(invalid)
            + '. Use CIDR (103.21.58.0/24) or start-end (103.21.58.1-103.21.58.50).'
        )

    return ', '.join(cleaned), None




# Whitelisted phone numbers for a device model.
WHITELISTED_PHONE_MAX_ITEMS = 10


def _validate_whitelisted_phone_number(raw_value):
    """
    Validate a comma-separated list of phone numbers. Optional field.

    Returns (cleaned_string_or_None, error_message).
    Both None means the field was not supplied — that is allowed.
    """
    raw_value = str(raw_value or '').strip()
    if not raw_value:
        return None, None

    items = [part.strip() for part in raw_value.split(',') if part.strip()]
    if not items:
        return None, None

    if len(items) > WHITELISTED_PHONE_MAX_ITEMS:
        return None, (
            f'whitelisted_phone_number can have at most '
            f'{WHITELISTED_PHONE_MAX_ITEMS} numbers. {len(items)} were provided.'
        )

    cleaned = []
    invalid = []
    for item in items:
        digits = re.sub(r'\D', '', item)
        if len(digits) < 10 or len(digits) > 15:
            invalid.append(item)
            continue
        if digits in cleaned:
            continue
        cleaned.append(digits)

    if invalid:
        return None, (
            'whitelisted_phone_number contains invalid entries: '
            + ', '.join(invalid)
            + '. Each number must have 10 to 15 digits.'
        )

    return ', '.join(cleaned), None


def _apply_device_model_ip_filters(queryset, request):
    """
    Optional manufacturer_id / model_id filters, shared by the superadmin
    and eSIM provider IP-config listings.

    Returns (queryset, error_message). Exactly one is non-None.
    """
    manufacturer_id = request.query_params.get('manufacturer_id')
    model_id = request.query_params.get('model_id')

    if model_id:
        if not str(model_id).isdigit():
            return None, 'model_id must be a number.'
        queryset = queryset.filter(id=model_id)

    if manufacturer_id:
        if not str(manufacturer_id).isdigit():
            return None, 'manufacturer_id must be a number.'
        manufacturer = Manufacturer.objects.filter(id=manufacturer_id).first()
        if not manufacturer:
            return None, 'No manufacturer found with this id.'
        queryset = queryset.filter(created_by__in=manufacturer.users.all())

    return queryset, None




def _device_model_ip_config_payload(queryset):
    """
    Serialise device models with their IP / whitelist configuration and
    their linked M2M (eSIM) providers.

    Manufacturer is resolved through created_by, matching how tagging
    Step 1 resolves it. DeviceModel has no direct manufacturer FK.
    """
    device_models = list(
        queryset.select_related('created_by').prefetch_related('eSimProviders')
    )

    # One query for all manufacturers, instead of one per model.
    creator_ids = {dm.created_by_id for dm in device_models if dm.created_by_id}
    manufacturer_by_user = {}
    if creator_ids:
        manufacturers = Manufacturer.objects.filter(
            users__id__in=creator_ids
        ).prefetch_related('users').distinct()
        for manufacturer in manufacturers:
            for user in manufacturer.users.all():
                if user.id in creator_ids:
                    manufacturer_by_user[user.id] = manufacturer

    payload = []
    for dm in device_models:
        manufacturer = manufacturer_by_user.get(dm.created_by_id)
        payload.append({
            'model_id': dm.id,
            'model_name': dm.model_name,
            'manufacturer_id': manufacturer.id if manufacturer else None,
            'manufacturer_name': manufacturer.company_name if manufacturer else None,
            'whitelisted_ip': dm.whitelisted_ip,
            'whitelisted_phone_number': dm.whitelisted_phone_number,
            'device_ip_range': dm.device_ip_range,
            'threshold': dm.threshold,
            'm2m_providers': [
                {
                    'id': provider.id,
                    'name': provider.company_name,
                    'device_ip_range': provider.device_ip_range,
                }
                for provider in dm.eSimProviders.all()
            ],
        })

    return payload




@api_view(['GET'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def superadmin_device_model_ip_config_list(request):
    """
    GET /api/devicemodel/ip-config/superadmin/list/

    All device models with their whitelist / IP configuration.
    Optional query params: manufacturer_id, model_id.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    if not get_user_object(request.user, "superadmin"):
        return Response(
            {"error": "Request must be from a superadmin."},
            status=status.HTTP_400_BAD_REQUEST
        )

    queryset, filter_error = _apply_device_model_ip_filters(
        DeviceModel.objects.all(), request
    )
    if filter_error:
        return Response({"error": filter_error}, status=status.HTTP_400_BAD_REQUEST)

    data = _device_model_ip_config_payload(queryset)
    return Response({
        "status": "success",
        "count": len(data),
        "data": data,
    }, status=status.HTTP_200_OK)


