@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
@require_permission('device_management', 'create')
def create_device_model(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

     
    user_id = request.user.id
    user=request.user 
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    man=get_user_object(user,"devicemanufacture")
    if not man:
        return Response({"error":"Request must be from device manufacture"}, status=status.HTTP_400_BAD_REQUEST)
    
    field_errors = {}

    whitelisted_ip, whitelist_error = _validate_whitelisted_ip(
        request.data.get('whitelisted_ip')
    )
    if whitelist_error:
        field_errors['whitelisted_ip'] = whitelist_error

    whitelisted_phone_number = None
    if request.data.get('whitelisted_phone_number'):
        whitelisted_phone_number, phone_error = _validate_whitelisted_phone_number(
            request.data.get('whitelisted_phone_number')
        )
        if phone_error:
            field_errors['whitelisted_phone_number'] = phone_error

    # device_ip_range = None
    # if request.data.get('device_ip_range'):
    #     device_ip_range, ip_range_error = _validate_device_ip_range(
    #         request.data.get('device_ip_range')
    #     )
    #     if ip_range_error:
    #         field_errors['device_ip_range'] = ip_range_error

    provider_combinations, combinations_error = _validate_provider_combinations(
        request.data.get('provider_combinations')
    )
    if combinations_error:
        field_errors['provider_combinations'] = combinations_error

    # Selected M2M providers must have completed integration, and every TSP in
    # the combinations must be backed by one of their confirmed IP ranges.
    if hasattr(request.data, 'getlist'):
        esim_provider_ids = request.data.getlist('eSimProviders')
    else:
        esim_provider_ids = request.data.get('eSimProviders') or []
        if not isinstance(esim_provider_ids, list):
            esim_provider_ids = [esim_provider_ids]
    selected_providers = eSimProvider.objects.filter(id__in=[i for i in esim_provider_ids if str(i).isdigit()])
    not_integrated = selected_providers.exclude(id__in=m2m_integrated_providers(selected_providers).values('id'))
    if not_integrated.exists():
        field_errors['eSimProviders'] = (
            "M2M integration is not complete for: "
            + ', '.join(not_integrated.values_list('company_name', flat=True))
        )
    elif provider_combinations:
        available = _confirmed_tsps(selected_providers)
        requested = {tsp for combination in provider_combinations for tsp in combination}
        unavailable = sorted(requested - available)
        if unavailable:
            field_errors['provider_combinations'] = (
                "No selected M2M provider has a confirmed IP range for: "
                + ', '.join(unavailable)
                + (". Available: " + ', '.join(sorted(available)) if available else ". No TSP is available yet.")
            )

    if field_errors:
        return Response({"errors": field_errors}, status=status.HTTP_400_BAD_REQUEST)
     


     
    #"superadmin","devicemanufacture","stateadmin","dtorto","dealer","owner","esimprovider"
    if STATIC_OTP_CAP:
                otp  = str(685472)
    else:
                otp = str(secrets.randbelow(1000000)).zfill(6)

    # Create data for the new DeviceModel entry
    _mqtt_pw = ''.join(secrets.choice(string.ascii_lowercase + string.digits) for _ in range(71))
    data = {
        'otp_time':timezone.now(),
        'otp': otp,
        'created_by': user_id,
        'created': timezone.now(),
        'status': 'Manufacturer_OTP_Sent',
        'mqtt_pw': _mqtt_pw,
        'whitelisted_ip': whitelisted_ip,
        'whitelisted_phone_number': whitelisted_phone_number,
        'device_ip_range': None,
        # Threshold is admin-controlled. 0 means unlimited. Forced here so
        # a manufacturer cannot set their own limit at model creation.
        'threshold': 0,
        # Normalised at validation, so what's stored is always upper-case
        # and suffix-free — step 2 compares against it directly.
        'provider_combinations': json.dumps(provider_combinations),
    }

    # Attach the file to the request data
    request_data = request.data.copy()
    request_data.update(data)
    #print("requestdata",request_data) 
    serializer = DeviceModelSerializer(data=request_data)

    # Validate and save the data along with the file
    if serializer.is_valid():
        # Save the DeviceModel instance
        device_model_instance = serializer.save()
        # Handle the uploaded file
        uploaded_file = request.FILES.get('tac_doc_path')
        if uploaded_file:
            # Save the file to a specific location
            
            file_path = save_file(request, 'tac_doc_path', 'fileuploads/tac_docs')  
            
            """file_path = 'fileuploads/tac_docs/' + str(device_model_instance.id) + '_' + uploaded_file.name
            with open(file_path, 'wb') as file:
                for chunk in uploaded_file.chunks():
                    file.write(chunk)
            stateadmin=StateAdmin.objects.last()"""
            
            # Update the tac_doc_path field in the DeviceModel instance
            device_model_instance.tac_doc_path = file_path
            device_model_instance.save()
            text="Dear user, confirmation OTP for VLTD Model Creation at SkyTron portal is {}. DO NOT disclose it to anyone. Warm Regards, SkyTron".format(otp)
            tpid="1007338577423920274" 
            send_SMS(user.mobile,text,tpid) 
            send_mail(
                'Login OTP',
                text,
                'noreply@skytron.in',
                [user.email],
                fail_silently=False,
            )
            d=serializer.data
            d.pop('otp', None)#.drop('otp')
            return Response(d, status=status.HTTP_201_CREATED)

    return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class DeviceModelUpdateView(generics.UpdateAPIView):
    queryset = DeviceModel.objects.all()
    serializer_class = DeviceModelFileUploadSerializer

    def perform_update(self, serializer):
        file = self.request.FILES.get('tac_doc_path', None)
        if file:
            fs = FileSystemStorage(location=settings.MEDIA_ROOT + 'fileuploads/tac_docs/')
            filename = fs.save(file.name, file)
            tac_doc_path = 'fileuploads/tac_docs/' + filename
            serializer.validated_data['tac_doc_path'] = tac_doc_path
        serializer.save()

