import re
from django.db.models import Exists, OuterRef

# Common passwords to reject (case-insensitive)
COMMON_PASSWORDS = [
    'password', 'password1', 'password123', 'password@123', 'password#123',
    'welcome', 'welcome1', 'welcome123', 'welcome@123', 'welcome#123',
    'admin', 'admin123', 'admin@123', 'admin#123',
    'test', 'test123', 'test@123', 'test#123',
    'qwerty', 'qwerty123', 'qwerty@123',
    '12345678', '123456789', '1234567890',
    'abc123', 'abc@123', 'letmein', 'monkey123',
    'dragon123', 'master123', 'sunshine123',
    'iloveyou', 'princess123', 'football123',
    'welcome1!', 'password1!', 'admin1234!',
    'passw0rd', 'p@ssw0rd', 'p@ssword',
]

def is_valid_string(s): 
    s = s.strip()
    
    # Check the length
    if len(s) < 8 or len(s) > 25:
        return False
     
    if s.lower() in COMMON_PASSWORDS:
        return False
     
    allowed_pattern = re.compile(r'^[A-Za-z0-9!@#$%^*()_\-+=\[\]{};:\'",.<>?/\\|`~]+$')
    if not allowed_pattern.match(s):
        return False
     
    has_uppercase = re.search(r'[A-Z]', s)
    has_lowercase = re.search(r'[a-z]', s)
    has_digit = re.search(r'[0-9]', s) 
    has_special = re.search(r'[!@#$%^*()_\-+=\[\]{};:\'",.<>?/\\|`~]', s)
    
 
    if has_uppercase and has_lowercase and has_digit and has_special:
        return True
    else:
        return False

def invalidate_user_sessions(user, reason="security"):
    """
    Blacklist every outstanding JWT and close every active Session for a user.
    Called whenever the user's authentication state changes (password reset)
    so tokens issued before the change stop working immediately, instead of
    remaining valid until their original expiry.
    """
    from .login_settings_cache import remove_active_session

    for session in Session.objects.filter(user=user).exclude(status='logout'):
        token = session.token
        if token:
            try:
                payload = decode_jwt_token(token)
                if payload:
                    jti = payload.get('jti', f"{reason}_{user.id}_{int(timezone.now().timestamp())}")
                    expires_at = datetime.fromtimestamp(payload.get('exp', 0))
                    TokenBlacklist.blacklist_token(
                        token=token,
                        user_id=user.id,
                        jti=jti,
                        expires_at=expires_at,
                        reason=reason
                    )
            except Exception as e:
                logger.error(f"Error blacklisting token for user {user.id}: {e}")
            try:
                remove_active_session(user.id, token)
            except Exception:
                pass
        session.status = 'logout'
        session.save(update_fields=['status'])

    Token.objects.filter(user=user).delete()


@csrf_exempt
@api_view(['POST'])
@throttle_classes([PasswordResetRateThrottle])  # 3 requests per minute, block IP for 5 min
@permission_classes([AllowAny])
# Identity comes only from mobile + dob + link token, never from a logged-in
# session; this also stops a stray "Authorization: Token <link token>" header
# (sent by the frontend SetPassword page) from failing authentication with 401.
@authentication_classes([])
@require_http_methods(['GET', 'POST'])
def password_reset(request ):
    # One identical response for every failure (missing field, mobile/dob/id_no
    # mismatch, bad or expired link, ...) so nothing reveals which detail was wrong.
    failed = Response({'error': 'Unable to reset password. Please check your details or request a new link.'}, status=status.HTTP_400_BAD_REQUEST)
    errors = validate_inputs(request)
    if errors:
        return failed

    
    """
    Reset user password.
    """
    if request.method == 'POST':
        mobile = request.data.get('mobile', None)
        id_no = request.data.get('id_no', None)
        new_password = request.data.get('new_password', None)
        dob = (request.data.get('dob', None) or '')
        dob = dob.replace('/', '-') or None

        if not dob:
            return failed
        if not mobile:
            return failed
        if not new_password:
            return failed
        
        
        try:
            new_password = decrypt_field(new_password,PRIVATE_KEY)
        except Exception:  # malformed base64 etc.
            new_password = None
        if not new_password:
            return failed

        if not is_valid_string(new_password):
            return failed

        try:
            dob_candidates = set()
            if dob:
                dob = dob.strip()
                dob_candidates.add(dob)

                parts = dob.split('-')
                if len(parts) == 3 and all(p.isdigit() for p in parts):
                    if len(parts[0]) == 4:
                        year, month, day = parts
                    else:
                        day, month, year = parts

                    dob_candidates.add(f"{year}-{month.zfill(2)}-{day.zfill(2)}")
                    dob_candidates.add(f"{day.zfill(2)}-{month.zfill(2)}-{year}")

            user = User.objects.filter(
                dob__in=list(dob_candidates),
                mobile=mobile
            ).last()
            
            if not user:
                return failed

            
            # C-3: a link token is compulsory.
            #   token2 - registration link (/new?q=), raw one-time token kept in user.password
            #   token  - forgot-password link (/reset-password?q=), issued by reset_password_request
            onboarding_token = request.data.get('token2', None)
            forgot_token = request.data.get('token', None)
            if onboarding_token:
                is_forgot_flow = False
                if not _check_onboarding_token(user, onboarding_token):
                    return failed
            elif forgot_token:
                is_forgot_flow = True
                if not _check_password_reset_token(user, forgot_token):
                    return failed
            else:
                return failed

            
            valid=True
            pas=False
            if user.role == "superadmin":
                pas=True
            elif user.role in ["schooladmin", "school_admin", "parentuser", "parent"]:
                # School/parent users do not have legacy profile models with idProofno.
                # Validate them using mobile + dob (+ token2 when provided).
                pas = True
            elif user.role ==  "dtorto":
                prof=dto_rto.objects.filter( 
                users=user, 
                ).last()
                


            elif user.role ==  "stateadmin":
                prof=StateAdmin.objects.filter( 
                users=user, 
                ).last()
            elif user.role ==  "devicemanufacture":
                prof=Manufacturer.objects.filter( 
                users=user, 
                ).last() 
            elif user.role ==  "dealer":
                prof=Dealer.objects.filter( 
                users=user, 
                ).last() 
            elif user.role ==  "owner":
                prof=VehicleOwner.objects.filter( 
                users=user, 
                ).last() 
            elif user.role ==  "esimprovider":
                prof=eSimProvider.objects.filter( 
                users=user, 
                ).last() 
            elif user.role ==  "filment":
                prof=Dealer.objects.filter( 
                users=user, 
                ).last() 
            elif user.role ==  "sosadmin":
                prof=EM_admin.objects.filter( 
                users=user, 
                ).last() 
                """elif user.role ==  "teamleader":
                    prof=EMTeams.objects.filter( 
                    users=user, 
                    ).last()
                    if id_no != prof.idProofno[-4:]:
                        user=None
                """
            elif user.role ==  "sosexecutive":
                prof=EM_ex.objects.filter( 
                users=user, 
                ).last()  
            elif user.role ==  "testagency":
                prof=TestAgency.objects.filter( 
                users=user, 
                ).last()
            else:
                # Custom IAM roles: use id_card_name (stores ID card number) for last-4-char validation
                if user.id_card_name:
                    if not id_no:
                        return failed
                    if id_no != user.id_card_name[-4:]:
                        user = None
                pas = True
            if not pas:
                if not id_no:
                    return failed
                if not prof:
                    return failed
                if not prof.idProofno:
                    return failed
            
                if id_no != prof.idProofno[-4:]:
                    user=None
                
                
            if not user:
                return failed

            
        except Exception as e:
            logger.exception(f"password_reset failed: {e}")
            return failed

        if not user:
            return failed

        hashed_password = make_password(new_password)
        user.password = hashed_password
        if is_forgot_flow:
            # Forgot password only changes the password - it must not
            # re-activate an account an admin has deactivated.
            user.save(update_fields=['password'])
            cache.delete(_password_reset_cache_key(user.id))  # one-time link
        else:
            # Registration link: first password set activates the account
            user.status='active'
            user.is_active = True
            user.save()

        # Password changed: any token/session issued before this point must
        # stop working immediately rather than remaining valid until its
        # original expiry (prevents reuse of a token after the account's
        # credentials have changed).
        invalidate_user_sessions(user, reason="security")

        return Response({'message': 'Password reset successfully'})



