@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([UserRateThrottle])
def session_verify(request):
    """
    Return the identity and permissions of the token making this request.

    The frontend calls this right after OTP verification, with the token it
    just received, and trusts only this server answer - not the fields of the
    validate_otp response, which an attacker can alter in transit (VAPT: OTP
    bypass via response manipulation). A pre-OTP/forged/ended token never
    reaches this view (JWTAuthentication rejects it, so DRF returns 403).

    POST with {"login_txn": <pre-OTP token>} additionally requires that the
    bearer token is the one validate_otp issued for that login transaction,
    and only once - an older, still-valid token replayed into a manipulated
    validate_otp response is rejected.
    """
    if request.method == 'POST':
        login_txn = request.data.get('login_txn')
        if not consume_login_txn(login_txn, request.auth):
            return Response({'authenticated': False, 'error': 'Login verification failed.'},
                            status=status.HTTP_403_FORBIDDEN)
    user = request.user
    return Response({
        'authenticated': True,
        'user_id': user.id,
        'role': user.role,
        'permissions': get_all_module_permissions(user),
    }, status=status.HTTP_200_OK)


@csrf_exempt
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle]) 
@require_http_methods(['GET', 'POST'])
def user_logout(request ): 
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    
    """
    User logout - Invalidates token and blacklists it.
    """
    if request.method == 'POST':
        token = request.data.get('token', None)

        if not token:
            return Response({'error': 'Session token not provided'}, status=status.HTTP_400_BAD_REQUEST)

        # Every logged-in user may end their own session (no RBAC module
        # needed - otherwise some roles could never revoke their token), but
        # only their own.
        session = Session.objects.filter(token=token, user=request.user).last()

        if not session:
            return Response({'error': 'Invalid session token'}, status=status.HTTP_404_NOT_FOUND)

        # Update session status to logout
        session.status = 'logout'
        session.save()

        # ===== REMOVE SESSION FROM REDIS =====
        from .login_settings_cache import remove_active_session
        remove_active_session(session.user.id, token)
        # ===== END SESSION REMOVAL =====

        # SECURITY FIX: Blacklist the JWT token to prevent reuse
        try:
            # Decode token to get expiration and JTI
            payload = decode_jwt_token(token)
            if payload:
                from datetime import datetime
                jti = payload.get('jti', f"logout_{session.user.id}_{int(timezone.now().timestamp())}")
                expires_at = datetime.fromtimestamp(payload.get('exp', 0))
                
                # Add token to blacklist
                TokenBlacklist.blacklist_token(
                    token=token,
                    user_id=session.user.id,
                    jti=jti,
                    expires_at=expires_at,
                    reason="logout"
                )
                logger.info(f"Token blacklisted for user {session.user.id} on logout")
            
            # Also delete any legacy Token objects
            Token.objects.filter(user=session.user).delete()
            
        except Exception as e:
            logger.error(f"Error blacklisting token on logout: {e}")
            # Continue with logout even if blacklisting fails
        
        # Update user login status
        try:
            session.user.login = False
            session.user.save()
        except:
            pass

        return Response({'status': 'Logout successful', 'message': 'Token has been invalidated'})
