class FavoriteUpdateAPIView(APIView):
    """
    POST /api/favorites/<uuid:pk>/update/

    Updates favorite label.
    """

    permission_classes = [IsAuthenticated]

    def post(self, request, pk):

        favorite = get_object_or_404(
            Favorite,
            pk=pk,
            user=request.user
        )

        serializer = FavoriteUpdateSerializer(
            data=request.data
        )

        serializer.is_valid(raise_exception=True)

        favorite.label = serializer.validated_data["label"]

        favorite.save(
            update_fields=[
                "label",
                "updated_at",
            ]
        )

        favorite = (
            Favorite.objects
            .select_related(
                "bus",
                "route",
                "route__source_stop",
                "route__destination_stop",
                "route__state",
                "bus_stop",
                "bus_stop__state",
                "bus_stop__district",
            )
            .get(pk=favorite.pk)
        )

        return success_response(
            data=FavoriteDetailSerializer(
                favorite
            ).data,
            message="Favorite updated successfully",
        )
        
        
