def _get_own_ip_range_entry(request, entry_id):
    """
    Fetch one IP range entry belonging to the calling provider.

    Returns (entry, error_response). Exactly one is None.
    """
    provider = eSimProvider.objects.filter(users=request.user).first()
    if not provider:
        return None, Response(
            {"error": "No eSimProvider account found for this user."},
            status=status.HTTP_400_BAD_REQUEST
        )

    if not str(entry_id or '').isdigit():
        return None, Response(
            {"error": "A valid id is required."},
            status=status.HTTP_400_BAD_REQUEST
        )

    entry = eSimProviderIPRange.objects.filter(
        id=entry_id, provider=provider, is_active=True
    ).first()
    if not entry:
        return None, Response(
            {"error": "No IP range found with this id for your account."},
            status=status.HTTP_400_BAD_REQUEST
        )

    return entry, None


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def esim_provider_ip_range_update(request):
    """
    POST /api/esim-provider/ip-range/update/

    Multipart. Edit one IP range entry. Send only the fields to change.
    The certificate is replaced only when a new file is attached.
    """
    entry, error_response = _get_own_ip_range_entry(
        request, request.data.get('id')
    )
    if error_response:
        return error_response

    field_errors = {}

    # ip_range — only validated when supplied
    if request.data.get('ip_range') is not None:
        ip_range, range_error = _validate_single_ip_range(
            request.data.get('ip_range')
        )
        if range_error:
            field_errors['ip_range'] = range_error
        elif ip_range != entry.ip_range:
            clash = eSimProviderIPRange.objects.filter(
                provider=entry.provider, ip_range=ip_range, is_active=True
            ).exclude(id=entry.id).exists()
            if clash:
                field_errors['ip_range'] = (
                    'This IP range is already registered for your account.'
                )
            else:
                entry.ip_range = ip_range

    if field_errors:
        return Response({"errors": field_errors},
                        status=status.HTTP_400_BAD_REQUEST)

    # Certificate replaced only when a new file is sent
    if request.FILES.get('certificate_file'):
        new_path = save_file(
            request, 'certificate_file', 'fileuploads/esim_ip_certificates'
        )
        if not new_path:
            return Response(
                {"error": "Certificate upload failed. Use a PDF or image "
                          "under 1 MB."},
                status=status.HTTP_400_BAD_REQUEST
            )
        entry.certificate_file = new_path

    if request.data.get('isp_name') is not None:
        entry.isp_name = (request.data.get('isp_name') or '').strip() or None

    if request.data.get('remarks') is not None:
        entry.remarks = (request.data.get('remarks') or '').strip() or None

    entry.save()

    return Response({
        "status": "success",
        "message": "IP range updated successfully.",
        "data": {
            "id": entry.id,
            "ip_range": entry.ip_range,
            "isp_name": entry.isp_name,
            "certificate_file": entry.certificate_file,
            "remarks": entry.remarks,
            "updated_at": entry.updated_at,
        }
    }, status=status.HTTP_200_OK)
    

@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def esim_provider_ip_range_delete(request):
    """
    POST /api/esim-provider/ip-range/delete/

    Soft delete. The row and its certificate stay in the database;
    is_active is set to False so it stops appearing and stops being
    used in checks.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    entry, error_response = _get_own_ip_range_entry(
        request, request.data.get('id')
    )
    if error_response:
        return error_response

    entry.is_active = False
    entry.save(update_fields=['is_active', 'updated_at'])

    return Response({
        "status": "success",
        "message": "IP range deleted successfully.",
        "data": {"id": entry.id, "ip_range": entry.ip_range},
    }, status=status.HTTP_200_OK)
    
 
 

def _ip_in_ranges(ip_value, ranges):
    """
    Is this IP inside any of the provider's registered ranges?

    Handles both formats the validator accepts:
      CIDR         103.21.58.0/24
      start-end    103.21.58.1-103.21.58.50
    """
    try:
        ip = ipaddress.ip_address(str(ip_value).strip())
    except ValueError:
        return False

    for raw in ranges:
        raw = str(raw or '').strip()
        if not raw:
            continue
        try:
            if '/' in raw:
                if ip in ipaddress.ip_network(raw, strict=False):
                    return True
            elif '-' in raw:
                start_raw, end_raw = raw.split('-', 1)
                start = ipaddress.ip_address(start_raw.strip())
                end = ipaddress.ip_address(end_raw.strip())
                if start <= ip <= end:
                    return True
            else:
                if ip == ipaddress.ip_address(raw):
                    return True
        except ValueError:
            continue

    return False


@api_view(['GET'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def m2m_provider_ip_scan(request):
    """
    GET /api/m2m/ip-scan/?provider_id=<id>&days=<n>

    For one M2M provider, lists every IP its tagged devices have sent
    data from, and flags any IP outside the provider's registered
    ranges as fake.

    Superadmin only.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    if not get_user_object(request.user, "superadmin"):
        return Response(
            {"error": "Request must be from a superadmin."},
            status=status.HTTP_400_BAD_REQUEST
        )

    provider_id = request.query_params.get('provider_id')
    if not str(provider_id or '').isdigit():
        return Response({"error": "provider_id must be a number."},
                        status=status.HTTP_400_BAD_REQUEST)

    provider = eSimProvider.objects.filter(id=provider_id).first()
    if not provider:
        return Response({"error": "No M2M provider found with this id."},
                        status=status.HTTP_400_BAD_REQUEST)

    # How far back to look. Default 7 days, so the query stays bounded.
    days_raw = request.query_params.get('days', '7')
    if not str(days_raw).isdigit() or not (1 <= int(days_raw) <= 90):
        return Response({"error": "days must be a number between 1 and 90."},
                        status=status.HTTP_400_BAD_REQUEST)
    since = timezone.now() - timedelta(days=int(days_raw))

    ranges = list(
        eSimProviderIPRange.objects.filter(
            provider=provider, is_active=True
        ).values_list('ip_range', flat=True)
    )

    tag_ids = list(
        DeviceTag.objects.filter(esim_provider=provider)
        .values_list('id', flat=True)
    )

    if not tag_ids:
        return Response({
            "status": "success",
            "provider": {"id": provider.id, "company_name": provider.company_name},
            "registered_ranges": ranges,
            "summary": {"total_ips": 0, "ok_ips": 0, "fake_ips": 0,
                        "devices_checked": 0},
            "data": [],
        }, status=status.HTTP_200_OK)

    # Unique IPs per table, then merged.
    seen = {}
    sources = (
        ('gps', GPSData.objects.filter(
            device_tag_id__in=tag_ids, entry_time__gte=since,
            source_ip__isnull=False)),
        ('em', EMGPSLocation.objects.filter(
            device_tag_id__in=tag_ids, source_ip__isnull=False)),
    )

    for label, queryset in sources:
        rows = (queryset
                .values('source_ip')
                .annotate(packet_count=Count('id'),
                          device_count=Count('device_tag_id', distinct=True))
                )
        for row in rows:
            ip = str(row['source_ip'])
            entry = seen.setdefault(ip, {
                'source_ip': ip,
                'packet_count': 0,
                'device_count': 0,
                'seen_in': [],
            })
            entry['packet_count'] += row['packet_count']
            entry['device_count'] = max(entry['device_count'],
                                        row['device_count'])
            entry['seen_in'].append(label)

    data = []
    fake_count = 0
    for ip, entry in seen.items():
        is_ok = _ip_in_ranges(ip, ranges)
        if not is_ok:
            fake_count += 1
        entry['status'] = 'ok' if is_ok else 'fake'
        data.append(entry)

    data.sort(key=lambda r: (r['status'] != 'fake', -r['packet_count']))

    return Response({
        "status": "success",
        "provider": {"id": provider.id, "company_name": provider.company_name},
        "registered_ranges": ranges,
        "days_checked": int(days_raw),
        "summary": {
            "total_ips": len(data),
            "ok_ips": len(data) - fake_count,
            "fake_ips": fake_count,
            "devices_checked": len(tag_ids),
        },
        "data": data,
    }, status=status.HTTP_200_OK)
    
   
@api_view(['POST'])
@permission_classes([IsAuthenticated])
def m2m_config_test(request):
    """
    POST /api/esim-provider/m2m-config/test/

    Calls the provider's own m2m_api_url (with their token + sample_iccid)
    and checks the response. Can be called multiple times.

    On the FIRST time the result is 'ok':
      - m2m_api_verified is set True (permanently)
      - config fields become locked for future edits
    """
    provider = eSimProvider.objects.filter(users=request.user).first()
    if not provider:
        return Response(
            {"error": "No eSimProvider account found for this user."},
            status=status.HTTP_400_BAD_REQUEST
        )

    if provider.m2m_api_verified:
        return Response(
            {"error": "M2M API is already verified. No need to test again."},
            status=status.HTTP_400_BAD_REQUEST
        )

    if not provider.m2m_api_url or not provider.m2m_api_token or not provider.m2m_sample_iccid:
        return Response(
            {"error": "Please submit api_url, token and sample_iccid first."},
            status=status.HTTP_400_BAD_REQUEST
        )

    # At least one IP range with its ISP certificate must be uploaded
    # before technical onboarding can be completed.
    if not eSimProviderIPRange.objects.filter(
        provider=provider, is_active=True
    ).exists():
        return Response(
            {"error": "Please upload at least one IP range with its ISP "
                      "certificate before completing technical onboarding."},
            status=status.HTTP_400_BAD_REQUEST
        )

    now = timezone.now()

    try:
        resp = requests.post(
            provider.m2m_api_url,
            json={"k1": provider.m2m_api_token, "k2": provider.m2m_sample_iccid},
            headers={"Content-Type": "application/json"},
            timeout=10,
        )
    except Timeout:
        return _save_test_result(
            provider, now, 'incorrect_api', {"error": "timeout"},
            "API timeout — either API is not available or IP whitelisting not done."
        )
    except RequestException as e:
        return _save_test_result(
            provider, now, 'incorrect_api', {"error": str(e)},
            "Could not reach the API — please check the URL and try again."
        )

    if resp.status_code in (401, 403):
        return _save_test_result(
            provider, now, 'token_expired',
            {"http_status": resp.status_code, "body": _safe_json(resp)},
            "Token expired or unauthorized."
        )

    if resp.status_code != 200:
        return _save_test_result(
            provider, now, 'incorrect_api',
            {"http_status": resp.status_code, "body": _safe_json(resp)},
            f"API returned HTTP {resp.status_code}."
        )

    body = _safe_json(resp)
    if body is None:
        return _save_test_result(
            provider, now, 'invalid_format', {"raw_text": resp.text[:2000]},
            "API did not return valid JSON."
        )

    # Same normaliser Step 2 of tagging uses, so both know one format.
    normalised, error_code, error_message = _normalise_m2m_result(body)
    if error_code:
        return _save_test_result(provider, now, error_code, body, error_message)

    # This test only checks the response SHAPE, not whether the SIM is any
    # good — the sample SIM may be old or expired, and that must not fail
    # onboarding. A field that is present but blank (e.g. fallbackStatus)
    # is acceptable; only a missing field fails.
    missing_fields = [f for f in REQUIRED_M2M_RESPONSE_FIELDS if f not in normalised]

    if missing_fields:
        provider.m2m_last_test_result = body
        provider.m2m_api_last_tested_at = now
        provider.m2m_technical_onboarding_status = 'invalid_format'
        provider.save(update_fields=[
            'm2m_technical_onboarding_status', 'm2m_last_test_result', 'm2m_api_last_tested_at'
        ])
        return Response({
            "status": "error",
            "message": "API response is missing required fields.",
            "missing_fields": missing_fields,
            "m2m_technical_onboarding_status": provider.m2m_technical_onboarding_status,
        }, status=status.HTTP_200_OK)

    # ── All checks passed ──────────────────────────────────────────────
    first_time_verified = not provider.m2m_api_verified
    provider.m2m_last_test_result = body
    provider.m2m_api_last_tested_at = now
    provider.m2m_technical_onboarding_status = 'ok'
    if first_time_verified:
        provider.m2m_api_verified = True
        provider.m2m_api_verified_at = now

    provider.save(update_fields=[
        'm2m_technical_onboarding_status', 'm2m_last_test_result',
        'm2m_api_last_tested_at', 'm2m_api_verified', 'm2m_api_verified_at'
    ])

    return Response({
        "status": "success",
        "message": "API verified successfully." + (
            " Configuration is now locked." if first_time_verified else ""
        ),
        "m2m_technical_onboarding_status": provider.m2m_technical_onboarding_status,
        "m2m_api_verified": provider.m2m_api_verified,
    }, status=status.HTTP_200_OK)


def _save_test_result(provider, now, onboarding_status, raw_result, message):
    provider.m2m_technical_onboarding_status = onboarding_status
    provider.m2m_last_test_result = raw_result
    provider.m2m_api_last_tested_at = now
    provider.save(update_fields=[
        'm2m_technical_onboarding_status', 'm2m_last_test_result', 'm2m_api_last_tested_at'
    ])
    return Response({
        "status": "error",
        "message": message,
        "m2m_technical_onboarding_status": provider.m2m_technical_onboarding_status,
    }, status=status.HTTP_200_OK)


def _safe_json(resp):
    try:
        return resp.json()
    except ValueError:
        return None





# ── M2M / eSIM provider API (Mapwala format) ──────────────────────────
# Success code returned by the provider when the lookup worked.
M2M_SUCCESS_RESPONSE_CODES = {"LCM_001"}

# Provider response codes that mean "bad credential" rather than "bad data".
# Empty for now — fill in once the provider shares their error code list.
M2M_AUTH_ERROR_RESPONSE_CODES = set()


def _parse_ddmmyyyy(value):
    """Provider sends dates as DD-MM-YYYY. Returns a date, or None."""
    if not value:
        return None
    for fmt in ('%d-%m-%Y', '%Y-%m-%d'):
        try:
            return datetime.strptime(str(value).strip(), fmt).date()
        except ValueError:
            continue
    return None




# Fields compared between the device model and the M2M provider response.
# (model field, m2m response field, compare digits only)
M2M_MODEL_MATCH_FIELDS = (
    ('whitelisted_ip', 'whitelisted_ip', False),
    ('whitelisted_phone_number', 'whitelisted_phone_number', True),
    ('device_ip_range', 'device_ip_range', False),
)


def _normalise_match_values(raw_value, digits_only=False):
    """
    Turn a comma-separated string (or list) into a set for comparison.

    Order and spacing are ignored, so "a, b" and "b,a" are equal.
    Returns None when there is nothing to compare.
    """
    if raw_value is None:
        return None

    if isinstance(raw_value, (list, tuple)):
        items = [str(item) for item in raw_value]
    else:
        items = str(raw_value).split(',')

    cleaned = set()
    for item in items:
        item = item.strip()
        if digits_only:
            item = re.sub(r'\D', '', item)
        if item:
            cleaned.add(item.lower())

    return cleaned or None


def _check_m2m_model_field_match(device_model, normalised):
    """
    Compare the manufacturer's saved values against what the M2M
    provider reports for this SIM.

    Skipped when either side is blank. The provider does not send these
    fields yet, so every check currently bypasses.

    Returns an error message, or None when everything matches.
    """
    for model_field, m2m_field, digits_only in M2M_MODEL_MATCH_FIELDS:
        model_values = _normalise_match_values(
            getattr(device_model, model_field, None), digits_only
        )
        if not model_values:
            continue  # manufacturer has not set it — nothing to check

        m2m_values = _normalise_match_values(
            normalised.get(m2m_field), digits_only
        )
        if not m2m_values:
            continue  # provider does not send it yet — bypass

        if model_values != m2m_values:
            logger.warning(
                'M2M mismatch on %s for device model id %s: model=%s provider=%s',
                model_field, device_model.id,
                sorted(model_values), sorted(m2m_values)
            )
            return (
                f"{model_field} does not match the value registered "
                f"by the manufacturer for this device model."
            )

    return None


def _normalise_m2m_result(body):
    """
    Convert a provider's raw response into our internal shape.

    Returns (normalised_dict, error_code, error_message).
    Exactly one of normalised_dict / error_code is set.
    """
    if not isinstance(body, dict):
        return None, 'invalid_format', "API did not return a JSON object."

    response_code = body.get('apiResponseCode')
    response_msg = body.get('apiResponseMsg') or ''

    if not response_code:
        return None, 'invalid_format', "API response is missing 'apiResponseCode'."

    if response_code in M2M_AUTH_ERROR_RESPONSE_CODES:
        return None, 'token_expired', f"Provider rejected the credential ({response_code})."

    if response_code not in M2M_SUCCESS_RESPONSE_CODES:
        return None, 'incorrect_api', f"API returned {response_code}. {response_msg}".strip()

    result_obj = body.get('resultObj')
    if not isinstance(result_obj, list):
        return None, 'invalid_format', "API response is missing the 'resultObj' list."

    if not result_obj:
        return None, 'incorrect_api', "API returned no SIM record for this ICCID."

    sim = result_obj[0]
    if not isinstance(sim, dict):
        return None, 'invalid_format', "'resultObj' does not contain a SIM object."

    return {
        'iccid': sim.get('iccid'),
        'sim_status': sim.get('cardStatus'),
        'card_state': sim.get('cardState'),
        'activation_date': _parse_ddmmyyyy(sim.get('activateOn')),
        'validity_date': _parse_ddmmyyyy(sim.get('expiredOn')),
        'telecom_provider': sim.get('primaryTSP'),
        'msisdn': sim.get('primaryMSISDN'),
        'primary_status': sim.get('primaryStatus'),
        'fallback_tsp': sim.get('fallbackTSP'),
        'fallback_msisdn': sim.get('fallbackMSISDN'),
        'fallback_status': sim.get('fallbackStatus'),
        'data_usage': sim.get('dataUsage'),
        'data_usage_date': _parse_ddmmyyyy(sim.get('dataUsageDate')),
        # Not returned by the provider today. Present so the model match
        # check activates automatically when they start sending them.
        'whitelisted_ip': sim.get('whitelistedIp'),
        'whitelisted_phone_number': sim.get('whitelistedPhoneNumber'),
        'device_ip_range': sim.get('deviceIpRange'),
    }, None, None


# =====================================================================
# SECTION 2 
# =====================================================================
 
# ── New tagging flow: tunable thresholds ─────────────────────────────
# Vehicle registered longer ago than this is treated as an "old" vehicle.
REGISTRATION_AGE_THRESHOLD_YEARS = 2
# Minimum remaining SIM validity required, by vehicle age.
SIM_VALIDITY_OLD_VEHICLE_YEARS = 1
SIM_VALIDITY_NEW_VEHICLE_YEARS = 2
# GPS packets older than this are not counted as received (Step 4).
GPS_PACKET_FRESHNESS_HOURS = 24
# OTP validity — matches the existing tagging flow.
TAGGING_OTP_EXPIRY_HOURS = 24
# Minimum gap between OTP resend requests.
TAGGING_OTP_RESEND_COOLDOWN_SECONDS = 60

# Temporary registration number format:
#   <district_code> + TEMP_REG_NO_MARKER + last 4 of chassis number
# e.g. AS01Tmp8595
TEMP_REG_NO_MARKER = 'TMP'
TEMP_REG_NO_CHASSIS_DIGITS = 4

# Device is physically fitted to a vehicle and tagging is complete.
TAGGING_FINAL_STOCK_STATUS = 'Fitted'
# The provider's API confirmed the SIM is active during step 2.
TAGGING_FINAL_ESIM_STATUS = 'ESIM_Active_Confirmed'
# Terminal state for a completed tag.
TAGGING_FINAL_TAG_STATUS = 'Owner_Final_OTP_Verified'

 
# Vahan response keys that must be present and non-empty. These map to
# NOT NULL columns, so a missing one is rejected before we try to save.
REQUIRED_VAHAN_FIELDS = [
    'chassisNo', 'deviceActivationStatus', 'deviceSerialno', 'engineNo',
    'fitmentCentreName', 'gnssConstellationCode', 'imeiNo', 'makerName',
    'modelName', 'ownerName', 'tacNo', 'tacValidUpto', 'vehClass',
]
 
 
# =====================================================================
# SECTION 3 
# =====================================================================
 
def _shift_years(d, years):
    """Add/subtract whole years from a date, handling 29 Feb safely."""
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        return d.replace(month=2, day=28, year=d.year + years)
 
 
def _parse_vahan_date(value):
    """Vahan sends dates as YYYY-MM-DD."""
    if not value:
        return None
    for fmt in ('%Y-%m-%d', '%d-%m-%Y'):
        try:
            return datetime.strptime(str(value).strip(), fmt).date()
        except ValueError:
            continue
    return None
 
 
def call_vahan_api(imei, iccid=None):
    """
    Look up vehicle + device details by IMEI.
 
    Vahan access is not available yet, so this reads from the
    VahanDummyData table. Swap the body for the real HTTP call when access
    is granted — the return contract stays the same.
 
    An unknown IMEI returns an error, which is how the real Vahan behaves
    for a device it has no record of.
 
    NOTE: the `iccid` argument exists only so the dummy can echo back the
    submitted value, which keeps the ICCID cross-check testable. The real
    Vahan call takes IMEI only — drop the argument when swapping it in.
 
    Returns (data_dict, error_message). Exactly one is non-None.
    """
    if not imei:
        return None, "IMEI is required for the Vahan lookup."
 
    # --- DUMMY DATA — replace with the real call ---------------------
    record = VahanDummyData.objects.filter(
        imei=str(imei).strip(), is_active=True
    ).first()
    if not record:
        return None, "No vehicle record found on Vahan for this IMEI."
 
    return record.to_vahan_response(submitted_iccid=iccid), None
    # -----------------------------------------------------------------
 
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([UserRateThrottle])
def set_vahan_dummy_data(request):
    """
    Superadmin POST API: set a row of Vahan dummy data by IMEI.

    POST /api/pub/vahan_dummy_data/set/

    Body: imei (required, 15 digits) plus any VahanDummyData fields.
    - IMEI already in the table: only the fields sent are updated.
    - IMEI not in the table: a new row is created (chassis_no, engine_no,
      device_serial_no and veh_class are then required).

    Superadmin only: device_tagging_step1_create trusts this table as the
    Vahan record. Remove together with VahanDummyData once the real Vahan
    integration is live.
    """
    if getattr(request.user, 'role', None) != 'superadmin':
        return Response({'error': 'Only superadmin can access this.'}, status=status.HTTP_403_FORBIDDEN)

    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    imei = str(request.data.get('imei') or '').strip()
    if not imei:
        return Response({'error': 'imei is required.'}, status=status.HTTP_400_BAD_REQUEST)
    if not imei.isdigit() or len(imei) != 15:
        return Response({'error': 'imei must be exactly 15 digits.'}, status=status.HTTP_400_BAD_REQUEST)

    data = request.data.copy()
    data['imei'] = imei

    record = VahanDummyData.objects.filter(imei=imei).first()
    serializer = VahanDummyDataSerializer(record, data=data, partial=record is not None)
    if not serializer.is_valid():
        return Response({'errors': serializer.errors}, status=status.HTTP_400_BAD_REQUEST)

    saved = serializer.save()
    return Response(
        {
            'status': 'updated' if record is not None else 'created',
            'data': VahanDummyDataSerializer(saved).data,
            'vahan_response': saved.to_vahan_response(),
        },
        status=status.HTTP_200_OK if record is not None else status.HTTP_201_CREATED,
    )


def _validate_vahan_response(vahan_data):
    """
    Confirm the Vahan response carries everything the NOT NULL columns
    need, before we attempt to save. Without this, a short response would
    fail with a database IntegrityError instead of a readable message.
 
    Returns an error message, or None when the response is usable.
    """
    if not isinstance(vahan_data, dict):
        return "Vahan did not return a valid response."
 
    missing = [f for f in REQUIRED_VAHAN_FIELDS if not str(vahan_data.get(f) or '').strip()]
    if missing:
        return f"Vahan response is missing required fields: {', '.join(missing)}."
 
    if _parse_vahan_date(vahan_data.get('tacValidUpto')) is None:
        return "Vahan returned an unreadable TAC validity date."
 
    # A registered vehicle must carry a readable registration date. A
    # vehicle with no registration number is a fresh vehicle and is
    # allowed to have neither.
    reg_no = str(vahan_data.get('regNo') or '').strip()
    if reg_no and _parse_vahan_date(vahan_data.get('dateOfRegistration')) is None:
        return "Vahan returned an unreadable vehicle registration date."
 
    return None
 
 
def _get_tagging_dealer(request):
    """
    Common check 1 — the caller must be a dealer.
    Returns (dealer, error_response).
    """
    dealer = get_user_object(request.user, "dealer")
    if not dealer:
        return None, Response(
            {"error": "Request must be from a dealer."},
            status=status.HTTP_400_BAD_REQUEST
        )
    return dealer, None
 
 
def _get_tagging_record(request, record_id, expected_step):
    """
    Common checks 2-5, applied by every step API after Step 1:
 
      - caller is a dealer
      - record exists and is not soft deleted
      - record was created by THIS user
      - record is sitting at exactly the expected step
 
    The step check blocks both skipping ahead and redoing a finished step.
    Repeat calls WHILE on a step (OTP resend, re-checking packets) stay
    allowed, because the step only advances on success.
 
    Returns (record, dealer, error_response).
    """
    dealer, error = _get_tagging_dealer(request)
    if error:
        return None, None, error
 
    if not record_id:
        return None, None, Response(
            {"error": "id is required."}, status=status.HTTP_400_BAD_REQUEST
        )
 
    record = DeviceStockMaster.objects.filter(id=record_id, is_deleted=False).first()
    if not record:
        return None, None, Response(
            {"error": "No such entry found."}, status=status.HTTP_400_BAD_REQUEST
        )
 
    if record.created_by_id != request.user.id:
        return None, None, Response(
            {"error": "This entry was created by another user."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    if record.current_step != expected_step:
        if record.current_step > expected_step:
            msg = f"Step {expected_step} is already completed for this entry."
        else:
            msg = (
                f"Step {record.current_step} must be completed first. "
                f"This entry is currently at step {record.current_step}."
            )
        return None, None, Response(
            {
                "error": msg,
                "current_step": record.current_step,
            },
            status=status.HTTP_400_BAD_REQUEST
        )
 
    return record, dealer, None
 
 
def _send_tagging_otp(mobile, email, otp, vehicle_reg_no, imei):
    """Send a tagging OTP by SMS (and email when available)."""
    text = (
        "Dear VLTD Dealer/ Manufacturer, we have received a request for tagging "
        "and activation of following device and vehicle- Vehicle Reg No:{}, "
        "Device IMEI No:{}. To confirm, please enter the OTP {}. - SkyTron"
    ).format(vehicle_reg_no or '-', imei, otp)
    tpid = "1007201930295888818"
    try:
        send_SMS(mobile, text, tpid)
    except Exception as e:
        logger.error(f"Tagging OTP SMS failed for {mobile}: {e}")
    if email:
        try:
            send_mail('Tagging OTP', text, 'noreply@skytron.in', [email], fail_silently=True)
        except Exception as e:
            logger.error(f"Tagging OTP email failed for {email}: {e}")
 
 
def _resolve_tagging_district(dealer, district_id):
    """
    Work out which district this tagging belongs to.

    A dealer can be assigned several districts, so:
      - district_id given  -> must be one of the dealer's own
      - not given, one district -> use it
      - not given, several      -> ask the dealer to choose

    Returns (district, error_message).
    """
    dealer_districts = dealer.districts.filter(status='active')

    if district_id:
        district = dealer_districts.filter(id=district_id).first()
        if not district:
            return None, "This district is not assigned to your dealership."
        return district, None

    count = dealer_districts.count()
    if count == 1:
        return dealer_districts.first(), None
    if count == 0:
        return None, "No active district is assigned to your dealership."
    return None, "Please select a district — your dealership covers more than one."


def _resolve_vehicle_category(veh_class):
    """
    Match Vahan's vehClass against Settings_VehicleCategory by name.

    Deliberately does NOT create a missing category. That model requires
    maxSpeed and warnSpeed, which Vahan does not send — and those values
    drive the over-speed alerts that become violation reports. Guessing
    them would produce wrong enforcement records, so a missing category
    is an error a human resolves once.

    Returns (category, error_message).
    """
    veh_class = (veh_class or '').strip()
    if not veh_class:
        return None, "Vahan did not return a vehicle class."

    category = Settings_VehicleCategory.objects.filter(category__iexact=veh_class).first()
    if not category:
        return None, (
            f"Vehicle category '{veh_class}' is not set up in the system. "
            "Please ask an administrator to add it with the correct speed limits."
        )
    return category, None


def _build_temp_reg_no(district, chassis_no):
    """
    Build a temporary registration number for a vehicle that has not been
    registered yet.

        district_code + 'Tmp' + last 4 characters of the chassis number
        e.g. AS01 + Tmp + 8595  ->  AS01Tmp8595

    Returns (temp_reg_no, error_message).
    """
    code = (getattr(district, 'district_code', '') or '').strip().upper()
    if not code:
        return None, "This district has no district code configured."

    chassis = (chassis_no or '').strip()
    if len(chassis) < TEMP_REG_NO_CHASSIS_DIGITS:
        return None, "Chassis number from Vahan is too short to build a temporary registration number."

    temp_reg_no = f"{code}{TEMP_REG_NO_MARKER}{chassis[-TEMP_REG_NO_CHASSIS_DIGITS:].upper()}"

    # vehicle_reg_no is unique on DeviceTag, so a collision would only
    # surface at the step 5 commit. Catch it here instead.
    if DeviceTag.objects.filter(vehicle_reg_no=temp_reg_no).exists():
        return None, f"Temporary registration number {temp_reg_no} is already in use."
    if DeviceStockMaster.objects.filter(vahan_reg_no=temp_reg_no, is_deleted=False).exists():
        return None, f"Temporary registration number {temp_reg_no} is already in use."

    return temp_reg_no, None

 
 # Device is physically fitted to a vehicle and tagging is complete.
TAGGING_FINAL_STOCK_STATUS = 'Fitted'
# The provider's API confirmed the SIM is active during step 2.
TAGGING_FINAL_ESIM_STATUS = 'ESIM_Active_Confirmed'
# Terminal state for a completed tag.
TAGGING_FINAL_TAG_STATUS = 'Owner_Final_OTP_Verified'



# Whether taggings still in progress count against a model's threshold.
# False = only devices that reached DeviceStock are counted.
THRESHOLD_COUNTS_IN_PROGRESS = False


def _check_device_model_threshold(device_model):
    """
    Enforce the per-model tagging limit set by the admin.

    Returns an error message string when the limit is reached,
    or None when tagging is allowed.
    A threshold of 0 means no limit.
    """
    threshold = device_model.threshold or 0
    if threshold <= 0:
        return None

    # Counting tagged devices, per TL. DeviceTag links to the model
    # through DeviceStock, so the lookup goes device -> model.
    used = DeviceTag.objects.filter(device__model=device_model).count()

    if THRESHOLD_COUNTS_IN_PROGRESS:
        # Taggings started but not yet finished. Completed ones are
        # excluded because they are already counted in DeviceStock.
        used += DeviceStockMaster.objects.filter(
            device_model=device_model,
            is_deleted=False,
            created_device_stock_id__isnull=True
        ).count()

    if used >= threshold:
        logger.warning(
            'Tagging blocked: device model %s (id %s) reached its threshold '
            '(%s used, limit %s).',
            device_model.model_name, device_model.id, used, threshold
        )
        return "Device not found."

    return None


