# =====================================================================
# STEP 2 API
# =====================================================================
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step2_esim(request):
    """
    POST /api/device-tagging/step2/
 
    Queries the eSIM provider's M2M API for the SIM, validates its status
    and remaining validity against the vehicle's registration age, and
    stores the result.
 
    On success, sends a 6-digit OTP to the dealer (start of Step 3).
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)
 
    record_id = request.data.get('id')
 
    # ── Common checks + must be sitting at step 2 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=2)
    if error:
        return error
 
    # ── Second guard: eSIM data must not already be stored ───────────
    # Belt and braces alongside the step check, because this step has an
    # external side effect (it sends the dealer OTP).
    if record.step2_completed_at or record.m2m_raw_response:
        return Response(
            {"error": "eSIM data is already saved for this entry."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    provider = record.esim_provider
    if not provider.m2m_api_url or not provider.m2m_api_token:
        return Response(
            {"error": "This eSIM provider has not configured their M2M API."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Call the provider's M2M API ──────────────────────────────────
    try:
        resp = requests.post(
            provider.m2m_api_url,
            json={"k1": provider.m2m_api_token, "k2": record.iccid},
            headers={"Content-Type": "application/json"},
            timeout=10,
        )
    except Timeout:
        return Response(
            {"error": "eSIM provider API timed out. Please try again."},
            status=status.HTTP_400_BAD_REQUEST
        )
    except RequestException as e:
        logger.error(f"M2M API call failed for record {record.id}: {e}")
        return Response(
            {"error": "Could not reach the eSIM provider API."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    if resp.status_code in (401, 403):
        return Response(
            {"error": "eSIM provider API rejected our credentials."},
            status=status.HTTP_400_BAD_REQUEST
        )
    if resp.status_code != 200:
        return Response(
            {"error": f"eSIM provider API returned HTTP {resp.status_code}."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    body = _safe_json(resp)
    if body is None:
        return Response(
            {"error": "eSIM provider API did not return valid JSON."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # Same normaliser used by the provider onboarding test — one place
    # that knows the provider's response format.
    normalised, error_code, error_message = _normalise_m2m_result(body)
    if error_code:
        return Response({"error": error_message}, status=status.HTTP_400_BAD_REQUEST)
 
    # ── Returned ICCID must be the one we asked about ────────────────
    if str(normalised.get('iccid') or '').strip() != record.iccid:
        return Response(
            {"error": "eSIM provider returned details for a different ICCID."},
            status=status.HTTP_400_BAD_REQUEST
        )
        
    
    # ── Model config must match what the provider reports ────────────
    # Bypassed while either side is blank. See _check_m2m_model_field_match.
    match_error = _check_m2m_model_field_match(record.device_model, normalised)
    if match_error:
        return Response({"error": match_error}, status=status.HTTP_400_BAD_REQUEST)
 
    today = timezone.localdate()
 
    # ── Check: activation date is today or earlier ───────────────────
    activation_date = normalised.get('activation_date')
    if not activation_date:
        return Response(
            {"error": "eSIM provider did not return an activation date."},
            status=status.HTTP_400_BAD_REQUEST
        )
    if activation_date > today:
        return Response(
            {
                "error": "eSIM activation date is in the future.",
                "activation_date": activation_date,
            },
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Check: SIM is active ─────────────────────────────────────────
    card_status = str(normalised.get('sim_status') or '').strip()
    if card_status.lower() != 'active':
        return Response(
            {
                "error": "eSIM is not active.",
                "sim_status": card_status,
            },
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Check: remaining validity, by vehicle registration age ───────
    expiry_date = normalised.get('validity_date')
    if not expiry_date:
        return Response(
            {"error": "eSIM provider did not return an expiry date."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    reg_no = (record.vahan_reg_no or '').strip()
    reg_date = record.vahan_date_of_registration
    threshold_date = _shift_years(today, -REGISTRATION_AGE_THRESHOLD_YEARS)
 
    if not reg_no:
        # Case C — fresh vehicle, not registered yet.
        required_years = SIM_VALIDITY_NEW_VEHICLE_YEARS
        case_label = "fresh vehicle (no registration number)"
    elif reg_date and reg_date < threshold_date:
        # Case A — registered longer ago than the threshold.
        required_years = SIM_VALIDITY_OLD_VEHICLE_YEARS
        case_label = f"registered more than {REGISTRATION_AGE_THRESHOLD_YEARS} years ago"
    else:
        # Case B — registered within the threshold.
        required_years = SIM_VALIDITY_NEW_VEHICLE_YEARS
        case_label = f"registered within {REGISTRATION_AGE_THRESHOLD_YEARS} years"
 
    required_expiry = _shift_years(today, required_years)
    if expiry_date < required_expiry:
        return Response(
            {
                "error": (
                    f"eSIM validity is too short. Vehicle is {case_label}, "
                    f"so at least {required_years} year(s) of validity is required."
                ),
                "expiry_date": expiry_date,
                "minimum_required_expiry": required_expiry,
            },
            status=status.HTTP_400_BAD_REQUEST
        )

    # ── Check: primary/fallback TSP matches the combination picked ───
    if record.provider_combination:
        combination = {_normalise_tsp(name) for name in record.provider_combination}
        primary_tsp = _normalise_tsp(normalised.get('telecom_provider'))
        fallback_tsp = _normalise_tsp(normalised.get('fallback_tsp'))

        if not primary_tsp or primary_tsp not in combination:
            return Response(
                {
                    "error": "eSIM primary provider does not match the selected combination.",
                    "primary_tsp": normalised.get('telecom_provider'),
                    "selected_combination": record.provider_combination,
                },
                status=status.HTTP_400_BAD_REQUEST
            )
        if not fallback_tsp or fallback_tsp not in combination:
            return Response(
                {
                    "error": "eSIM fallback provider does not match the selected combination.",
                    "fallback_tsp": normalised.get('fallback_tsp'),
                    "selected_combination": record.provider_combination,
                },
                status=status.HTTP_400_BAD_REQUEST
            )

    # ── All checks passed — save the eSIM data ───────────────────────
    now = timezone.now()
 
    record.m2m_iccid = normalised.get('iccid')
    record.m2m_card_state = normalised.get('card_state')
    record.m2m_card_status = normalised.get('sim_status')
    record.m2m_activation_date = activation_date
    record.m2m_expiry_date = expiry_date
    record.m2m_primary_tsp = normalised.get('telecom_provider')
    record.m2m_primary_msisdn = normalised.get('msisdn')
    record.m2m_primary_status = normalised.get('primary_status')
    record.m2m_fallback_tsp = normalised.get('fallback_tsp') or None
    record.m2m_fallback_msisdn = normalised.get('fallback_msisdn') or None
    record.m2m_fallback_status = normalised.get('fallback_status') or None
    record.m2m_data_usage = normalised.get('data_usage')
    record.m2m_data_usage_date = normalised.get('data_usage_date')
    record.m2m_raw_response = body
 
    # ── Generate and send the dealer OTP (start of Step 3) ───────────
    otp = str(secrets.randbelow(1000000)).zfill(6)
    record.dealer_otp = otp
    record.dealer_otp_sent_at = now
 
    record.step2_completed_at = now
    record.current_step = 3
    record.updated_by = request.user
    record.save()
 
    _send_tagging_otp(
        mobile=request.user.mobile,
        email=getattr(request.user, 'email', None),
        otp=otp,
        vehicle_reg_no=record.vahan_reg_no,
        imei=record.imei,
    )
 
    return Response({
        "status": "success",
        "message": "Step 2 completed successfully. OTP has been sent to your registered mobile number.",
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            "esim": {
                "iccid": record.m2m_iccid,
                "card_state": record.m2m_card_state,
                "card_status": record.m2m_card_status,
                "activation_date": record.m2m_activation_date,
                "expiry_date": record.m2m_expiry_date,
                "primary_tsp": record.m2m_primary_tsp,
                "primary_msisdn": record.m2m_primary_msisdn,
                "primary_status": record.m2m_primary_status,
                "fallback_tsp": record.m2m_fallback_tsp,
                "fallback_msisdn": record.m2m_fallback_msisdn,
                "fallback_status": record.m2m_fallback_status,
                "data_usage": record.m2m_data_usage,
                "data_usage_date": record.m2m_data_usage_date,
            },
            "validity_case": case_label,
            "step2_completed_at": record.step2_completed_at,
        }
    }, status=status.HTTP_200_OK)
 
 
 # Wrong OTP submissions allowed before the OTP is invalidated.
TAGGING_OTP_MAX_ATTEMPTS = 5

# The fixed test OTP for the tagging flow is controlled by MASTER_OTP_ENABLED
# (see auth_security.is_master_otp).
 



# Number of SOS / emergency buttons a device may have.
EMG_BUTTONS_MIN = 1
EMG_BUTTONS_MAX = 10

# Certificate number prefix. Format is not finalised — using a dummy
# serial for now. Replace once the real format is provided.
CERTIFICATE_NO_PREFIX = 'AS0000'


def _validate_device_sell_amount(raw_value):
    """
    Sale amount of the device, entered by the dealer.
    Returns (Decimal, error_message). Exactly one is non-None.
    """
    raw_value = str(raw_value or '').strip()
    if not raw_value:
        return None, 'This field is required.'

    try:
        amount = Decimal(raw_value)
    except (InvalidOperation, ValueError):
        return None, 'device_sell_amount must be a number.'

    if amount < 0:
        return None, 'device_sell_amount cannot be negative.'

    if amount >= Decimal('10000000000'):
        return None, 'device_sell_amount is too large.'

    return amount.quantize(Decimal('0.01')), None


def _validate_no_of_emg_buttons(raw_value):
    """
    Number of SOS / emergency buttons fitted, 1 to 10.
    Returns (int, error_message). Exactly one is non-None.
    """
    raw_value = str(raw_value or '').strip()
    if not raw_value:
        return None, 'This field is required.'

    try:
        count = int(raw_value)
    except (TypeError, ValueError):
        return None, 'no_of_emg_buttons must be a whole number.'

    if count < EMG_BUTTONS_MIN or count > EMG_BUTTONS_MAX:
        return None, (
            f'no_of_emg_buttons must be between {EMG_BUTTONS_MIN} '
            f'and {EMG_BUTTONS_MAX}.'
        )

    return count, None




def _build_certificate_no(record):
    """
    Certificate number for a completed tagging.

    The real format has not been finalised — this is a dummy serial built
    from the record id. Replace once the format is provided.
    """
    return f"{CERTIFICATE_NO_PREFIX}{record.id}"


def _get_fitment_centre_details(dealer):
    """
    Fitment centre details come from the dealer who did the tagging.

    Name is the dealer's company name. Address comes from the dealer's
    user account — the Dealer model itself has no address field.

    Returns (name, address).
    """
    name = dealer.company_name if dealer else ''

    address = ''
    if dealer:
        dealer_user = dealer.users.filter(status='active').first() or dealer.users.first()
        if dealer_user:
            parts = [
                (dealer_user.address or '').strip(),
                (dealer_user.address_State or '').strip(),
                (dealer_user.address_pin or '').strip(),
            ]
            address = ', '.join(p for p in parts if p)

    return name, address


def _build_certificate_fields(record):
    """
    The certificate-specific fields, on top of whatever the existing
    Vahan info API returns.
    """
    fitment_name, fitment_address = _get_fitment_centre_details(record.dealer)

    return {
        "cert_no": _build_certificate_no(record),
        "serial_no": record.created_device_tag_id or '',
        "esim_valid_upto": (
            record.m2m_expiry_date.isoformat() if record.m2m_expiry_date else ''
        ),
        "primary_msisdn": record.m2m_primary_msisdn or '',
        "fallback_msisdn": record.m2m_fallback_msisdn or '',
        "no_of_emg_buttons": (
            str(record.no_of_emg_buttons) if record.no_of_emg_buttons else ''
        ),
        "fitment_center_name": fitment_name,
        "fitment_center_address": fitment_address,
        # RTO name is taken from the district for now.
        "rto_name": record.district.district if record.district else '',
    }
    
    
def _tagging_otp_matches(stored_otp, submitted_otp):
    """
    Compare a submitted OTP against the stored one.

    The master OTP (MASTER_OTP_ENABLED) is also accepted, so the flow can be
    tested without waiting for a real SMS.
    """
    if not stored_otp or not submitted_otp:
        return False

    if secrets.compare_digest(str(stored_otp), str(submitted_otp)):
        return True

    if is_master_otp(submitted_otp):
        return True

    return False
 
 
# =====================================================================
# SECTION 4 
# STEP 3 — RESEND DEALER OTP
# =====================================================================
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step3_resend_otp(request):
    """
    POST /api/device-tagging/step3/resend-otp/
 
    Generates a fresh OTP and sends it to the dealer's registered mobile.
 
    Can be called repeatedly while the record sits at step 3, subject to a
    cooldown. Once step 3 is verified the record moves on and this endpoint
    rejects it.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)
 
    record_id = request.data.get('id')
 
    # ── Common checks + must be sitting at step 3 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=3)
    if error:
        return error
 
    now = timezone.now()
 
    # ── Cooldown — stops the endpoint being hammered ─────────────────
    if record.dealer_otp_sent_at:
        elapsed = (now - record.dealer_otp_sent_at).total_seconds()
        if elapsed < TAGGING_OTP_RESEND_COOLDOWN_SECONDS:
            wait = int(TAGGING_OTP_RESEND_COOLDOWN_SECONDS - elapsed)
            return Response(
                {
                    "error": f"Please wait {wait} more second(s) before requesting a new OTP.",
                    "retry_after_seconds": wait,
                },
                status=status.HTTP_400_BAD_REQUEST
            )
 
    # ── Fresh OTP, attempt counter reset ─────────────────────────────
    otp = str(secrets.randbelow(1000000)).zfill(6)
    record.dealer_otp = otp
    record.dealer_otp_sent_at = now
    record.dealer_otp_attempts = 0
    record.updated_by = request.user
    record.save(update_fields=[
        'dealer_otp', 'dealer_otp_sent_at', 'dealer_otp_attempts',
        'updated_by', 'updated_at'
    ])
 
    _send_tagging_otp(
        mobile=request.user.mobile,
        email=getattr(request.user, 'email', None),
        otp=otp,
        vehicle_reg_no=record.vahan_reg_no,
        imei=record.imei,
    )
 
    return Response({
        "status": "success",
        "message": "OTP has been sent to your registered mobile number.",
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            "otp_sent_at": record.dealer_otp_sent_at,
            "otp_expires_in_hours": TAGGING_OTP_EXPIRY_HOURS,
        }
    }, status=status.HTTP_200_OK)
 
 
# =====================================================================
# SECTION 5 
# STEP 3 — VERIFY DEALER OTP
# =====================================================================
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step3_verify_otp(request):
    """
    POST /api/device-tagging/step3/verify-otp/
 
    Verifies the dealer OTP. On success the record advances to step 4.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)
 
    record_id = request.data.get('id')
    submitted_otp = str(request.data.get('otp') or '').strip()
 
    # ── Common checks + must be sitting at step 3 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=3)
    if error:
        return error
 
    if not submitted_otp:
        return Response(
            {"error": "otp is required."}, status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── An OTP must actually be outstanding ──────────────────────────
    if not record.dealer_otp or not record.dealer_otp_sent_at:
        return Response(
            {"error": "No OTP is pending for this entry. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    now = timezone.now()
 
    # ── Expiry ───────────────────────────────────────────────────────
    if now > record.dealer_otp_sent_at + timedelta(hours=TAGGING_OTP_EXPIRY_HOURS):
        return Response(
            {"error": "This OTP has expired. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Attempt limit ────────────────────────────────────────────────
    if record.dealer_otp_attempts >= TAGGING_OTP_MAX_ATTEMPTS:
        return Response(
            {"error": "Too many incorrect attempts. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Compare ──────────────────────────────────────────────────────
    if not _tagging_otp_matches(record.dealer_otp, submitted_otp):
        record.dealer_otp_attempts += 1
        remaining = TAGGING_OTP_MAX_ATTEMPTS - record.dealer_otp_attempts
 
        if remaining <= 0:
            # Burn the OTP so the counter cannot simply be waited out.
            record.dealer_otp = None
            record.save(update_fields=['dealer_otp', 'dealer_otp_attempts', 'updated_at'])
            return Response(
                {"error": "Too many incorrect attempts. Please request a new OTP."},
                status=status.HTTP_400_BAD_REQUEST
            )
 
        record.save(update_fields=['dealer_otp_attempts', 'updated_at'])
        return Response(
            {
                "error": "Incorrect OTP.",
                "attempts_remaining": remaining,
            },
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Verified — advance to step 4 ─────────────────────────────────
    record.dealer_otp_verified_at = now
    record.dealer_otp_attempts = 0
    record.step3_completed_at = now
    record.current_step = 4
    record.updated_by = request.user
    record.save(update_fields=[
        'dealer_otp_verified_at', 'dealer_otp_attempts', 'step3_completed_at',
        'current_step', 'updated_by', 'updated_at'
    ])
 
    return Response({
        "status": "success",
        "message": "OTP verified successfully. Step 3 completed.",
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            "dealer_otp_verified_at": record.dealer_otp_verified_at,
            "step3_completed_at": record.step3_completed_at,
        }
    }, status=status.HTTP_200_OK)







# Packets older than this are not counted as received.
# Also bounds the query: only this window is scanned.
GPS_PACKET_FRESHNESS_HOURS = 24
 
# Safety cap on how many rows are scanned per table for one device — a
# backstop against a runaway scan, not the real bound. The freshness
# window above is what's supposed to bound the work; a device sending
# nothing but PVT packets every second or two for hours can otherwise
# push a rare alert packet (e.g. an EA,10 emergency trigger from hours
# earlier) past a low cap before the scan ever reaches it, even though
# it's well inside the freshness window.
GPS_PACKET_SCAN_LIMIT = 50000

from datetime import timezone as dt_timezone

# --- PVT pre-checks --------------------
# Window for finding the device's latest PVT.
PVT_PRECHECK_WINDOW_MINUTES = 5
# Max gap between the time inside the packet and the time the server received it.  
PVT_MAX_CLOCK_DRIFT_SECONDS = 60
# Main input voltage must exceed this,
PVT_MIN_MAIN_INPUT_VOLTAGE = Decimal('10.5')
# Devices must be fitted inside Assam. 
TAGGING_ALLOWED_STATE_ISO = 'IN-AS'
REVERSE_GEOCODE_URL = 'https://map-geocoding.gromed.in/reverse'
REVERSE_GEOCODE_TIMEOUT_SECONDS = 3
REVERSE_GEOCODE_CACHE_SECONDS = 3600

# Device ESN / serial number format returned by Vahan, e.g. ASMABC00000013:
#   3-char state code + 3-char vendor code + 8-digit serial.
VAHAN_DEVICE_SERIAL_PATTERN = re.compile(r'^[A-Z]{3}[A-Z0-9]{3}[0-9]{8}$')

# Telecom service providers a device model's combinations can be built
# from. More may be added later.
TSP_CHOICES = ['AIRTEL', 'VI', 'JIO', 'BSNL', 'MTNL']
# Every combination needs at least this many providers.
MIN_PROVIDERS_PER_COMBINATION = 2


def _normalise_tsp(value):
    """
    Telecom provider name in a comparable form.

    The M2M API is inconsistent — 'AIRTEL' in one response and 'Airtel'
    in another, and BSNL arrives as 'BSNL_S' on some SIMs . Upper-case it and drop any suffix.
    """
    return str(value or '').strip().upper().split('_')[0]


# Words that identify each TSP in an IP range's free-text isp_name.
TSP_ISP_ALIASES = {
    'AIRTEL': ('airtel', 'bharti'),
    'JIO': ('jio', 'reliance'),
    'VI': ('vi', 'vodafone', 'idea'),
    'BSNL': ('bsnl', 'bharat sanchar'),
    'MTNL': ('mtnl', 'mahanagar'),
}


def _isp_name_to_tsp(isp_name):
    """Map an IP range's isp_name ('Bharti Airtel Ltd', 'Vodafone Idea') to a
    TSP_CHOICES code, or None if it names no known TSP."""
    name = str(isp_name or '').strip().lower()
    if not name:
        return None
    if _normalise_tsp(name) in TSP_CHOICES:
        return _normalise_tsp(name)
    for tsp, aliases in TSP_ISP_ALIASES.items():
        if any(re.search(r'\b' + re.escape(alias) + r'\b', name) for alias in aliases):
            return tsp
    return None


def _confirmed_tsps(providers):
    """TSPs usable by a device model with these M2M providers: those covered
    by an active IP range of a provider whose M2M integration is complete."""
    isp_names = eSimProviderIPRange.objects.filter(
        provider__in=m2m_integrated_providers(providers), is_active=True,
    ).values_list('isp_name', flat=True)
    return {tsp for tsp in map(_isp_name_to_tsp, isp_names) if tsp}


def _validate_provider_combinations(raw):
    """
    Check the combinations supplied at model creation.

    Returns (combinations, error) — exactly one is non-None. Accepts a
    JSON string, since model creation is multipart and form values
    arrive as text.
    """
    if raw in (None, '', b''):
        return [], None

    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except ValueError:
            return None, "provider_combinations must be valid JSON."

    if not isinstance(raw, list):
        return None, "provider_combinations must be a list of combinations."

    combinations = []
    seen = set()
    for position, entry in enumerate(raw, start=1):
        if not isinstance(entry, list):
            return None, f"Combination {position} must be a list of provider names."

        names = [_normalise_tsp(name) for name in entry]
        if len(names) < MIN_PROVIDERS_PER_COMBINATION:
            return None, f"Combination {position} needs at least {MIN_PROVIDERS_PER_COMBINATION} providers."

        unknown = [name for name in names if name not in TSP_CHOICES]
        if unknown:
            return None, f"Combination {position} has unknown providers: {', '.join(unknown)}."

        if len(set(names)) != len(names):
            return None, f"Combination {position} has the same provider more than once."

        key = frozenset(names)
        if key in seen:
            return None, f"Combination {position} is a duplicate."
        seen.add(key)

        combinations.append(names)

    return combinations, None
 
# The 9 packet types, in display order.
TAGGING_PACKET_TYPES = [
    'login_packet',
    'health_packet',
    'pvt_packet',
    'emergency_start',
    'ble_emergency_start',
    'emergency_stop',
    'sos_start',
    'sos_start_ble',
    'sos_stop',
]
 

TAGGING_REQUIRED_PACKETS = list(TAGGING_PACKET_TYPES)
 
 
# =====================================================================
# SECTION 2
# =====================================================================
 
def _normalise_packet(raw):
    """
    Packets arrive with two header spellings — '$EPB,...' and '$,EPB,...'.
    Normalise so field positions line up.
    """
    return (raw or '').strip().replace('$,', '$', 1)
 
 
BLE_MARKER_PATTERN = re.compile(r'\{SOS_PUB_[^}]*\}', re.IGNORECASE)


def _packet_has_ble_marker(raw):
    """
    True when the packet carries the BLE source marker.

    VERIFIED against real data: a BLE-triggered SOS/emergency packet ends
    with a '{SOS_PUB_<reg_no>}' tag (seen as both '{SOS_PUB_AS01CC0001}'
    and '{SOS_PUB_AS01CC0001*}' in production) — not a literal 'BLE'
    string, which never appears in real packets.
    """
    tail = _normalise_packet(raw)[-60:]
    return bool(BLE_MARKER_PATTERN.search(tail))
 
 
# Matched on structure, not on a registration prefix. The registration
# number varies by state — and a second-hand commercial vehicle keeps its
# original plate even after moving to another state — so any prefix must
# be accepted.
LOGIN_PACKET_PATTERN = re.compile(r'^\$[A-Z0-9]+,\$\d{15},')
 
 
def _is_login_packet(raw, ble=None):
    """
    Login packet: $<reg no>,$<imei>,$<fw>,$<fw>,$<position>
    Matched on structure — the old check looked for a '$AS' prefix and so
    only found Assam vehicles.
    """
    return bool(LOGIN_PACKET_PATTERN.match((raw or '').strip()))
 
def _is_health_packet(raw, ble=None):
    """
    VERIFIED against real data:
      $,HLM,MAPW,1.1.1,<imei>,100,10,0,5,5,0011,11.2 4.20,*

    Field-based rather than a ',HLM,' substring — normalisation strips the
    leading comma, so the substring check never matched real packets.
    """
    return _packet_type_in_header(raw, 'HLM')
 
 
def _is_pvt_packet(raw, ble=None):
    # VERIFIED — 24.7M rows in production.
    return _packet_type_in_header(raw, 'PVT')
 
 
def _is_emergency_alert(raw, code):
    """
    Emergency start/stop are PVT packets with the status field replaced:
    field 3 ('NR' when normal) becomes 'EA', field 4 carries the alert
    code — '10' for start, '11' for stop.

    VERIFIED against real data:
      $,PVT,MAPW,1.1.1,EA,10,L,<imei>,<reg>,...  (start)
      $,PVT,MAPW,1.1.1,EA,11,L,<imei>,<reg>,...  (stop)
    """
    parts = _packet_fields(raw)
    return (
        len(parts) > 4
        and parts[0].upper() == 'PVT'
        and parts[3].upper() == 'EA'
        and parts[4] == code
    )


def _is_emergency_start(raw, ble=False):
    if not _is_emergency_alert(raw, '10'):
        return False
    return _packet_has_ble_marker(raw) == ble


def _is_emergency_stop(raw, ble=None):
    return _is_emergency_alert(raw, '11')
 
 
def _is_sos_packet(raw, msg_type, ble=False):
    """
    SOS packets in GPSemDataLog. EMR = start, SEM = stop.

    VERIFIED — EMR 6.2M rows, SEM 48K rows in production.
    The BLE split is VERIFIED too — see _packet_has_ble_marker.
    """
    if not _packet_type_in_header(raw, msg_type):
        return False
    return _packet_has_ble_marker(raw) == ble
 
# Which table each packet type lives in, and how to recognise it.
# One place to correct a matcher — nothing else needs touching.
TAGGING_PACKET_MATCHERS = {
    'login_packet':        ('gps',   lambda r: _is_login_packet(r),                  True),
    'health_packet':       ('gps',   lambda r: _is_health_packet(r),                 False),
    'pvt_packet':          ('gps',   lambda r: _is_pvt_packet(r),                    True),
    'emergency_start':     ('gps',   lambda r: _is_emergency_start(r, ble=False),    True),
    'ble_emergency_start': ('gps',   lambda r: _is_emergency_start(r, ble=True),     True),
    'emergency_stop':      ('gps',   lambda r: _is_emergency_stop(r),                True),
    'sos_start':           ('gpsem', lambda r: _is_sos_packet(r, 'EMR', ble=False),  True),
    'sos_start_ble':       ('gpsem', lambda r: _is_sos_packet(r, 'EMR', ble=True),   True),
    'sos_stop':            ('gpsem', lambda r: _is_sos_packet(r, 'SEM'),             True),
}
 
 
def _extract_pvt_lat_lon(raw):
    """
    Pull latitude and longitude out of a PVT packet.

    Real format:
      $PVT,DTPL,1.0.0,NR,01,L,<imei>,<reg>,0,<date>,<time>,<lat>,N,<lon>,E,...
                                                            +11  +12 +13 +14

    The N/E direction fields are checked as an anchor, so if the layout
    ever shifts we return None instead of a wrong coordinate.
    """
    parts = _packet_fields(raw)
    try:
        idx = next(i for i, p in enumerate(parts) if p.upper() == 'PVT')
    except StopIteration:
        return None, None

    try:
        lat_raw, lat_dir = parts[idx + 11], parts[idx + 12].upper()
        lon_raw, lon_dir = parts[idx + 13], parts[idx + 14].upper()

        if lat_dir not in ('N', 'S') or lon_dir not in ('E', 'W'):
            return None, None

        lat = Decimal(lat_raw)
        lon = Decimal(lon_raw)
    except (IndexError, InvalidOperation, ValueError):
        return None, None

    if lat == 0 and lon == 0:
        return None, None

    if lat_dir == 'S':
        lat = -lat
    if lon_dir == 'W':
        lon = -lon

    return lat, lon


def _is_normal_pvt_packet(raw):
    """
    True for a normal position PVT packet.

    """
    parts = _packet_fields(raw)
    try:
        idx = next(i for i, p in enumerate(parts) if p.upper() == 'PVT')
    except StopIteration:
        return False
    return len(parts) > idx + 3 and parts[idx + 3].upper() == 'NR'


def _extract_pvt_datetime(raw):
    """
    Device timestamp from inside a PVT packet

    """
    parts = _packet_fields(raw)
    try:
        idx = next(i for i, p in enumerate(parts) if p.upper() == 'PVT')
    except StopIteration:
        return None
    try:
        naive = datetime.strptime(parts[idx + 9] + parts[idx + 10], '%d%m%Y%H%M%S')
    except (IndexError, ValueError):
        return None
    return naive.replace(tzinfo=dt_timezone.utc)


def _extract_pvt_main_input_voltage(raw):
    """
    Main input voltage from a PVT packet.
    """
    parts = _packet_fields(raw)
    try:
        idx = next(i for i, p in enumerate(parts) if p.upper() == 'PVT')
    except StopIteration:
        return None
    try:
        return Decimal(parts[idx + 24])
    except (IndexError, InvalidOperation, ValueError):
        return None


def _reverse_geocode_state_iso(latitude, longitude):
    """
    Returns (iso_code, error) — exactly one is non-None. A lookup that
    fails for any reason returns an error rather than a code, so the
    caller blocks the device instead of letting it through unverified


    Cached because step 4 is re-runnable and dealers call it repeatedly
    while triggering alerts, so the same coordinate is looked up over and
    over. A cache failure must never fail a tagging.
    """
    unavailable = "Location could not be verified at the moment. Please try again."

    cache_key = f"revgeo:{round(float(latitude), 4)}:{round(float(longitude), 4)}"
    try:
        cached = cache.get(cache_key)
    except Exception:
        cached = None
    if cached:
        return cached, None

    try:
        response = requests.get(
            REVERSE_GEOCODE_URL,
            params={
                'format': 'json',
                'lat': str(latitude),
                'lon': str(longitude),
                'addressdetails': 1,
                'zoom': 18,
            },
            timeout=REVERSE_GEOCODE_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        address = (response.json() or {}).get('address') or {}
    except (Timeout, RequestException, ValueError) as exc:
        logger.warning("Tagging reverse geocode failed for %s,%s: %s", latitude, longitude, exc)
        return None, unavailable

    iso_code = str(address.get('ISO3166-2-lvl4') or '').strip().upper()
    if not iso_code:
        logger.warning("Tagging reverse geocode returned no state for %s,%s", latitude, longitude)
        return None, unavailable

    try:
        cache.set(cache_key, iso_code, REVERSE_GEOCODE_CACHE_SECONDS)
    except Exception:
        pass
    return iso_code, None


def _run_pvt_prechecks(record):
    """
    Three checks on the device's latest normal PVT packet, run before the
    9-packet scan.

    Returns (error_message, details). error_message is None when all
    three pass.
    """
    now = timezone.now()
    cutoff = now - timedelta(minutes=PVT_PRECHECK_WINDOW_MINUTES)
    reg_no = (record.vahan_reg_no or '').strip()

    rows = (
        GPSDataLog.objects
        .filter(timestamp__gte=cutoff, raw_data__contains=record.imei)
        .order_by('-timestamp')
        .values_list('raw_data', 'timestamp')[:GPS_PACKET_SCAN_LIMIT]
    )

    latest = None
    for raw_data, received_at in rows.iterator():
        if reg_no and reg_no not in raw_data:
            continue
        if not _is_pvt_packet(raw_data) or not _is_normal_pvt_packet(raw_data):
            continue
        latest = (raw_data, received_at)
        break

    if not latest:
        return "No data found.", None

    raw_data, received_at = latest
    details = {'raw_data': raw_data, 'received_at': received_at.isoformat()}

    # ── Check 1: device clock against server receive time ────────────
    packet_time = _extract_pvt_datetime(raw_data)
    if packet_time is None:
        return "No data found.", details
    drift = abs((received_at - packet_time).total_seconds())
    details['packet_datetime'] = packet_time.isoformat()
    details['clock_drift_seconds'] = drift
    if drift > PVT_MAX_CLOCK_DRIFT_SECONDS:
        return "No data found.", details

    # ── Check 2: coordinates present, non-zero, and inside Assam ─────
    latitude, longitude = _extract_pvt_lat_lon(raw_data)
    if latitude is None or longitude is None or latitude == 0 or longitude == 0:
        return "Device must be within Assam.", details
    details['latitude'] = str(latitude)
    details['longitude'] = str(longitude)

    state_iso, geocode_error = _reverse_geocode_state_iso(latitude, longitude)
    if geocode_error:
        return geocode_error, details
    details['state_iso'] = state_iso
    if state_iso != TAGGING_ALLOWED_STATE_ISO:
        return "Device must be within Assam.", details

    # ── Check 3: wired to the vehicle supply ─────────────────────────
    voltage = _extract_pvt_main_input_voltage(raw_data)
    details['main_input_voltage'] = str(voltage) if voltage is not None else None
    if voltage is None or voltage <= PVT_MIN_MAIN_INPUT_VOLTAGE:
        return "Device must be connected to main power.", details

    return None, details
 
 
# =====================================================================
# SECTION 3
# STEP 4 API
# =====================================================================

def _scan_for_packets(queryset, types_for_table, reg_no):
    remaining = dict(types_for_table)
    found = {}
    for raw_data, packet_time in queryset.iterator():
        if not remaining:
            break
        matched_types = []
        for packet_type, (_table, matcher, needs_reg_no) in remaining.items():
            # Packet types that carry a registration number must match
            # the vehicle's own number as well as the IMEI. This is
            # what catches a device fitted without the correct plate
            # configured — the device would transmit with the wrong
            # or factory default registration, and must not pass this
            # step.
            #
            # The health packet carries no registration number, so it
            # is matched on IMEI alone.
            if needs_reg_no and reg_no and reg_no not in raw_data:
                continue
            try:
                if matcher(raw_data):
                    found[packet_type] = (raw_data, packet_time)
                    matched_types.append(packet_type)
            except Exception:
                # A malformed packet is simply not a match.
                continue
        for packet_type in matched_types:
            remaining.pop(packet_type, None)
    return found


def _run_packet_check(imei, reg_no):
    """
    Runs the PVT pre-checks plus the 9-packet scan for an arbitrary
    imei/reg_no pair.

    Shared by device_tagging_step4_packet_check (via a thin adapter around
    its DeviceStockMaster record) and the device-renewal flow, which has
    no DeviceStockMaster row to hang off.

    Query strategy: the GPS log tables have no IMEI column and no index on
    raw_data, so matching by IMEI alone would mean a full scan of tables
    holding tens of millions of rows. Restricting to the freshness window
    first bounds the work — which is why the threshold is not just a
    validation rule.

    Returns (precheck_error, precheck_details, results, all_received, missing, latitude, longitude).
    precheck_error is None when the PVT pre-checks passed; results/all_received/
    missing/latitude/longitude are None when the pre-checks failed (the scan
    never ran).
    """
    precheck_record = SimpleNamespace(imei=imei, vahan_reg_no=reg_no)
    precheck_error, precheck_details = _run_pvt_prechecks(precheck_record)
    if precheck_error:
        return precheck_error, precheck_details, None, False, None, None, None

    now = timezone.now()
    cutoff = now - timedelta(hours=GPS_PACKET_FRESHNESS_HOURS)
    reg_no = (reg_no or '').strip()

    # ── Pull this device's recent packets — two queries, not eighteen ─
    # Scanned lazily, newest first, checking every packet type routed to
    # that table on each row and dropping a type out of the search the
    # moment it's matched. This way a device blasting out one packet type
    # (PVT, typically) at high frequency can't push a rarer type further
    # back in the same table out of reach before the scan gets to it —
    # the scan for a still-missing type keeps going deeper regardless of
    # how many rows of other types sit in front of it.
    gps_types = {
        pt: TAGGING_PACKET_MATCHERS[pt] for pt in TAGGING_PACKET_TYPES
        if TAGGING_PACKET_MATCHERS[pt][0] == 'gps'
    }
    gpsem_types = {
        pt: TAGGING_PACKET_MATCHERS[pt] for pt in TAGGING_PACKET_TYPES
        if TAGGING_PACKET_MATCHERS[pt][0] == 'gpsem'
    }

    gps_qs = (
        GPSDataLog.objects
        .filter(timestamp__gte=cutoff, raw_data__contains=imei)
        .order_by('-timestamp')
        .values_list('raw_data', 'timestamp')[:GPS_PACKET_SCAN_LIMIT]
    )
    gpsem_qs = (
        GPSemDataLog.objects
        .filter(timestamp__gte=cutoff, raw_data__contains=imei)
        .order_by('-timestamp')
        .values_list('raw_data', 'timestamp')[:GPS_PACKET_SCAN_LIMIT]
    )

    found_by_type = {
        **_scan_for_packets(gps_qs, gps_types, reg_no),
        **_scan_for_packets(gpsem_qs, gpsem_types, reg_no),
    }

    # ── Build results in display order ────────────────────────────────
    results = {}
    latest_pvt_raw = None

    for packet_type in TAGGING_PACKET_TYPES:
        found = found_by_type.get(packet_type)

        if found:
            raw_data, packet_time = found
            results[packet_type] = {
                'received': True,
                'timestamp': packet_time.isoformat(),
                'raw_data': raw_data,
            }
            if packet_type == 'pvt_packet':
                latest_pvt_raw = raw_data
        else:
            results[packet_type] = {
                'received': False,
                'timestamp': None,
                'raw_data': None,
            }

    # ── Latitude / longitude from the latest PVT packet ───────────────
    latitude, longitude = (None, None)
    if latest_pvt_raw:
        latitude, longitude = _extract_pvt_lat_lon(latest_pvt_raw)

    # ── Did everything required arrive? ──────────────────────────────
    missing = [p for p in TAGGING_REQUIRED_PACKETS if not results[p]['received']]
    all_received = not missing

    return None, precheck_details, results, all_received, missing, latitude, longitude


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step4_packet_check(request):
    """
    POST /api/device-tagging/step4/

    Checks whether the fitted device is transmitting all required packet
    types, and records the result.

    Re-runnable: the dealer will typically call this several times while
    triggering alerts on the device. Each call re-checks live and
    overwrites the stored result. The record only advances to step 5 once
    every required packet has been seen inside the freshness window.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    record_id = request.data.get('id')

    # ── Common checks + must be sitting at step 4 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=4)
    if error:
        return error

    # ── PVT pre-checks + 9-packet scan ────────────────────────────────
    precheck_error, precheck_details, results, all_received, missing, latitude, longitude = (
        _run_packet_check(record.imei, record.vahan_reg_no)
    )
    if precheck_error:
        logger.info(
            "Tagging step 4 pre-check failed for record %s (imei %s): %s | %s",
            record.id, record.imei, precheck_error, precheck_details,
        )
        return Response(
            {"status": "failed", "error": precheck_error},
            status=status.HTTP_400_BAD_REQUEST
        )
    now = timezone.now()

    # ── Store — every call overwrites, so the record always holds the
    #    most recent check ────────────────────────────────────────────
    record.packet_results = results
    record.packets_all_received = all_received
    record.packets_checked_at = now
    record.packet_latitude = latitude
    record.packet_longitude = longitude
    record.updated_by = request.user

    update_fields = [
        'packet_results', 'packets_all_received', 'packets_checked_at',
        'packet_latitude', 'packet_longitude', 'updated_by', 'updated_at',
    ]

    if all_received:
        record.step4_completed_at = now
        record.current_step = 5
        update_fields += ['step4_completed_at', 'current_step']

    record.save(update_fields=update_fields)

    return Response({
        "status": "success" if all_received else "pending",
        "message": (
            "All required packets received. Step 4 completed."
            if all_received else
            "Some packets have not been received yet. Trigger them on the device and check again."
        ),
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            "imei": record.imei,
            "vehicle_reg_no": record.vahan_reg_no,
            "checked_at": record.packets_checked_at,
            "freshness_window_hours": GPS_PACKET_FRESHNESS_HOURS,
            "all_received": all_received,
            "missing_packets": missing,
            "latitude": record.packet_latitude,
            "longitude": record.packet_longitude,
            "packets": results,
        }
    }, status=status.HTTP_200_OK)


# =====================================================================
# DEVICE eSIM VALIDITY RENEWAL / EXTENSION
# =====================================================================
# Devices tagged & activated by dealers under a manufacturer's device
# model eventually need their eSIM validity extended. A dealer (for
# devices they personally tagged) or a manufacturer (for devices under
# their own device models) can request a renewal of 1 or 2 years once the
# device has been active for at least RENEWAL_MIN_DAYS_SINCE_ACTIVATION
# days. A successful renewal re-runs the full activation process — eSIM
# re-validation via the M2M provider, the same PVT/packet checks used in
# tagging step 4, a Vahan validity push, and a fresh certificate.

RENEWAL_ELIGIBILITY_WINDOW_DAYS = 60          # "next 2 months"
RENEWAL_MIN_DAYS_SINCE_ACTIVATION = 300
RENEWAL_MIN_EXTENSION_YEARS = 1
RENEWAL_LIST_PAGE_SIZE = 25
RENEWAL_LIST_MAX_PAGE_SIZE = 100


def _paginate_params(params, default_page_size=RENEWAL_LIST_PAGE_SIZE, max_page_size=RENEWAL_LIST_MAX_PAGE_SIZE):
    try:
        page = max(1, int(params.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        page_size = int(params.get('page_size') or default_page_size)
    except (TypeError, ValueError):
        page_size = default_page_size
    page_size = max(1, min(page_size, max_page_size))
    return page, page_size


def _pagination_meta(page, page_size, total_count):
    total_pages = (total_count + page_size - 1) // page_size if total_count else 0
    return {
        "page": page,
        "page_size": page_size,
        "total_count": total_count,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_previous": page > 1,
    }


def _latest_active_device_tag(device):
    """Latest non-deleted DeviceTag for a device — the activation record used for renewal."""
    return (
        DeviceTag.objects
        .filter(device=device)
        .exclude(status__in=['TagDeleted', 'untaged_after_failed_taging'])
        .order_by('-tagged')
        .first()
    )


def _push_vahan_validity(device, device_tag, new_expiry_dt):
    """
    Push the renewed eSIM validity to Vahan.

    PLACEHOLDER: no Vahan "push"/"update" operation exists in this
    codebase today — every existing Vahan integration
    (GetVahanAPIInfo, vahan_by_imei, vahan_by_regno, call_vahan_api) only
    reads/looks up a VLTD record. This stub records the attempt without
    raising, so a renewal can still complete while the real integration
    is confirmed with the Parivahan integration owner.

    Returns (response_dict, error_message). Exactly one of response_dict's
    "success" key reflects the outcome; error_message is set whenever the
    push did not actually happen.
    """
    logger.info(
        "Vahan push not implemented — skipping for device %s (imei %s), new validity %s",
        device.id, device.imei, new_expiry_dt,
    )
    return (
        {"note": "Vahan push integration not yet available.", "attempted": False},
        "Vahan push integration is not yet available.",
    )


def _device_renewal_scope_or_error(user, base_qs, device_field_prefix=''):
    """
    Applies manufacturer/dealer/superadmin scoping to a queryset.

    `device_field_prefix` is '' when the queryset's rows ARE DeviceStock
    (API 1), or 'device__' when the queryset is DeviceRenewalRequest and
    the FK path needs to be traversed (unused for API 3, which scopes on
    its own denormalised dealer/manufacturer FKs instead — see
    device_renewal_history_list).

    Returns (queryset, error_response). error_response is None on success.
    """
    if user.role == 'superadmin':
        return base_qs, None
    elif user.role == 'devicemanufacture':
        manufacturer = get_user_object(user, 'devicemanufacture')
        if not manufacturer:
            return None, Response(
                {"status": "error", "message": "Manufacturer profile not found."},
                status=status.HTTP_404_NOT_FOUND
            )
        return base_qs.filter(**{f'{device_field_prefix}model__created_by__in': manufacturer.users.all()}), None
    elif user.role == 'dealer':
        dealer = get_user_object(user, 'dealer')
        if not dealer:
            return None, Response(
                {"status": "error", "message": "Dealer profile not found."},
                status=status.HTTP_404_NOT_FOUND
            )
        return base_qs.filter(**{f'{device_field_prefix}dealer': dealer}), None
    else:
        return None, Response(
            {"status": "error", "message": "Your role cannot access device renewal information."},
            status=status.HTTP_403_FORBIDDEN
        )


@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_permission('device_renewal_management', 'view')
def device_renewal_eligible_list(request):
    """
    GET or POST /api/device-renewal/eligible/

    Devices whose eSIM validity expires within RENEWAL_ELIGIBILITY_WINDOW_DAYS,
    role-scoped:
      - superadmin: all devices.
      - manufacturer: only devices under their own device models.
      - dealer: only devices assigned to them (DeviceStock.dealer).

    Optional filters (query string on GET, body on POST):
        search       partial match on imei/iccid
        page         default 1
        page_size    default 25, max 100
    """
    user = request.user
    now = timezone.now()
    horizon = now + timedelta(days=RENEWAL_ELIGIBILITY_WINDOW_DAYS)

    base_qs = DeviceStock.objects.filter(
        esim_validity__isnull=False,
        esim_validity__gte=now,
        esim_validity__lte=horizon,
    ).exclude(stock_status__in=['Deleted', 'Device_Untagged'])

    qs, error = _device_renewal_scope_or_error(user, base_qs)
    if error:
        return error

    params = request.data if request.method == 'POST' else request.query_params

    search = str(params.get('search') or '').strip()
    if search:
        qs = qs.filter(Q(imei__icontains=search) | Q(iccid__icontains=search))

    qs = qs.select_related('model', 'model__created_by', 'dealer').order_by('esim_validity')

    total_count = qs.count()
    page, page_size = _paginate_params(params)
    start = (page - 1) * page_size
    devices = list(qs[start:start + page_size])

    # Attach the latest DeviceTag per device without an N+1 — this list is
    # small, bounded by the eligibility window.
    device_ids = [d.id for d in devices]
    tags_by_device = {}
    for tag in DeviceTag.objects.filter(device_id__in=device_ids).exclude(
        status__in=['TagDeleted', 'untaged_after_failed_taging']
    ).order_by('device_id', '-tagged'):
        tags_by_device.setdefault(tag.device_id, tag)
    for d in devices:
        d._latest_tag = tags_by_device.get(d.id)

    serializer = DeviceRenewalEligibleDeviceSerializer(devices, many=True)
    return Response({
        "status": "success",
        "data": serializer.data,
        "pagination": _pagination_meta(page, page_size, total_count),
    }, status=status.HTTP_200_OK)


@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_permission('device_renewal_management', 'create')
@transaction.atomic
def device_renewal_submit(request):
    """
    POST /api/device-renewal/submit/
    body: {device_id, requested_duration_years: 1|2}

    Submits a renewal request for a device. Both dealer and manufacturer
    can submit, scoped to their own devices. On success, re-runs the full
    activation process: eSIM re-validation via the M2M provider, the PVT/
    packet checks from tagging step 4, a Vahan validity push, and a fresh
    certificate.
    """
    user = request.user

    input_serializer = DeviceRenewalSubmitSerializer(data=request.data)
    if not input_serializer.is_valid():
        return Response(
            {"status": "error", "message": "Invalid input.", "errors": input_serializer.errors},
            status=status.HTTP_400_BAD_REQUEST
        )
    device_id = input_serializer.validated_data['device_id']
    duration_years = input_serializer.validated_data['requested_duration_years']

    device = DeviceStock.objects.filter(id=device_id).select_related(
        'model', 'model__created_by', 'dealer'
    ).first()
    if not device:
        return Response({"status": "error", "message": "Device not found."}, status=status.HTTP_404_NOT_FOUND)

    # ── Scope: manufacturer/dealer may only renew their own devices ──────
    dealer = manufacturer = None
    if user.role == 'devicemanufacture':
        manufacturer = get_user_object(user, 'devicemanufacture')
        if not manufacturer or not device.model or device.model.created_by not in manufacturer.users.all():
            return Response(
                {"status": "error", "message": "You can only renew devices under your own device models."},
                status=status.HTTP_403_FORBIDDEN
            )
    elif user.role == 'dealer':
        dealer = get_user_object(user, 'dealer')
        if not dealer or device.dealer_id != dealer.id:
            return Response(
                {"status": "error", "message": "You can only renew devices you tagged yourself."},
                status=status.HTTP_403_FORBIDDEN
            )
    elif user.role != 'superadmin':
        return Response(
            {"status": "error", "message": "Your role cannot submit renewal requests."},
            status=status.HTTP_403_FORBIDDEN
        )

    # ── Guard against a request already in flight for this device ───────
    if DeviceRenewalRequest.objects.filter(device=device, status='pending').exists():
        return Response(
            {"status": "error", "message": "A renewal request is already in progress for this device."},
            status=status.HTTP_400_BAD_REQUEST
        )

    device_tag = _latest_active_device_tag(device)
    if not device_tag:
        return Response(
            {"status": "error", "message": "Device has no active tagging record."},
            status=status.HTTP_400_BAD_REQUEST
        )

    # ── 300-day-since-activation check (client's explicit business rule) ─
    days_since_activation = (timezone.now() - device_tag.tagged).days
    if days_since_activation < RENEWAL_MIN_DAYS_SINCE_ACTIVATION:
        return Response({
            "status": "error",
            "message": (
                f"Device must be active for at least {RENEWAL_MIN_DAYS_SINCE_ACTIVATION} days "
                f"before renewal can be requested. Currently {days_since_activation} days."
            ),
            "days_since_activation": days_since_activation,
        }, status=status.HTTP_400_BAD_REQUEST)

    renewal = DeviceRenewalRequest.objects.create(
        device=device,
        device_tag=device_tag,
        requested_by=user,
        requester_role=user.role,
        dealer=dealer,
        manufacturer=manufacturer,
        requested_duration_years=duration_years,
        old_esim_validity=device.esim_validity,
        status='pending',
    )

    # ── M2M call — reuse the same provider/parse helpers as tagging step 2 ─
    provider = device_tag.esim_provider or device.esim_provider.first()
    if not provider:
        renewal.status = 'failed'
        renewal.rejection_reason = "No eSIM provider is associated with this device; cannot check M2M validity."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    if not provider.m2m_api_url or not provider.m2m_api_token:
        renewal.status = 'failed'
        renewal.rejection_reason = "This eSIM provider has not configured their M2M API."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    try:
        resp = requests.post(
            provider.m2m_api_url,
            json={"k1": provider.m2m_api_token, "k2": device.iccid},
            headers={"Content-Type": "application/json"},
            timeout=10,
        )
    except Timeout:
        renewal.status = 'failed'
        renewal.rejection_reason = "eSIM provider API timed out. Please try again."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)
    except RequestException as e:
        logger.error(f"M2M API call failed for renewal request {renewal.id}: {e}")
        renewal.status = 'failed'
        renewal.rejection_reason = "Could not reach the eSIM provider API."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    if resp.status_code in (401, 403):
        renewal.status = 'failed'
        renewal.rejection_reason = "eSIM provider API rejected our credentials."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)
    if resp.status_code != 200:
        renewal.status = 'failed'
        renewal.rejection_reason = f"eSIM provider API returned HTTP {resp.status_code}."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    body = _safe_json(resp)
    if body is None:
        renewal.status = 'failed'
        renewal.rejection_reason = "eSIM provider API did not return valid JSON."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    normalised, error_code, error_message = _normalise_m2m_result(body)
    renewal.m2m_raw_response = body
    renewal.m2m_checked_at = timezone.now()
    if error_code:
        renewal.status = 'failed'
        renewal.rejection_reason = error_message
        renewal.save()
        return Response({"status": "error", "message": error_message}, status=status.HTTP_400_BAD_REQUEST)

    # ── 1-year expiry validation (flat rule, regardless of requested duration) ─
    new_expiry_date = normalised.get('validity_date')
    if not new_expiry_date:
        renewal.status = 'failed'
        renewal.rejection_reason = "eSIM provider did not return an expiry date."
        renewal.save()
        return Response({"status": "error", "message": renewal.rejection_reason}, status=status.HTTP_400_BAD_REQUEST)

    old_validity_date = device.esim_validity.date() if device.esim_validity else timezone.localdate()
    min_required_expiry = _shift_years(old_validity_date, RENEWAL_MIN_EXTENSION_YEARS)
    if new_expiry_date < min_required_expiry:
        renewal.status = 'rejected'
        renewal.rejection_reason = (
            f"New eSIM expiry ({new_expiry_date}) is not at least {RENEWAL_MIN_EXTENSION_YEARS} "
            f"year(s) later than the current validity ({old_validity_date})."
        )
        renewal.save()
        return Response({
            "status": "error",
            "message": renewal.rejection_reason,
            "new_expiry_date": new_expiry_date,
            "minimum_required_expiry": min_required_expiry,
        }, status=status.HTTP_400_BAD_REQUEST)

    new_expiry_dt = timezone.make_aware(datetime.combine(new_expiry_date, datetime.min.time()))

    # ── Packet re-check — reuse the same PVT prechecks + 9-packet scan as tagging step 4 ─
    precheck_error, precheck_details, results, all_received, missing, latitude, longitude = (
        _run_packet_check(device.imei, device_tag.vehicle_reg_no)
    )
    renewal.pvt_precheck_details = precheck_details
    renewal.packet_results = results
    renewal.packets_all_received = all_received
    renewal.packets_checked_at = timezone.now()
    if precheck_error or not all_received:
        renewal.status = 'failed'
        renewal.rejection_reason = precheck_error or f"Missing packets: {', '.join(missing)}"
        renewal.save()
        return Response({
            "status": "error",
            "message": renewal.rejection_reason,
            "missing_packets": missing,
        }, status=status.HTTP_400_BAD_REQUEST)

    # ── All checks passed — commit the new validity ──────────────────────
    device.esim_validity = new_expiry_dt
    device.save(update_fields=['esim_validity'])

    # ── Vahan push (best-effort — does not fail the request; see gap note) ─
    vahan_response, vahan_error = _push_vahan_validity(device, device_tag, new_expiry_dt)
    renewal.vahan_push_status = 'failed' if vahan_error else 'success'
    renewal.vahan_push_response = vahan_response
    renewal.vahan_pushed_at = timezone.now()

    # ── Certificate regeneration (best-effort — does not fail the request) ─
    now = timezone.now()
    relative_path = f"fileuploads/renewal_certs/{renewal.id}.pdf"
    file_path = os.path.join(HOST_STORAGE_PATH, relative_path)
    try:
        os.makedirs(os.path.dirname(file_path), exist_ok=True)
        geneateCet(
            file_path,
            device.imei,
            device.model.model_name if device.model else '',
            device.model.model_name if device.model else '',
            new_expiry_dt.strftime('%d/%m/%Y'),
            device_tag.vehicle_reg_no,
            device_tag.tagged.strftime('%d/%m/%Y'),
            device_tag.tagged.strftime('%d/%m/%Y'),
            device_tag.tagged.strftime('%d/%m/%Y'),
            'Renewed',
            now.strftime('%d/%m/%Y'),
        )
        renewal.certificate_file_path = relative_path
        renewal.certificate_generated_at = now
    except Exception:
        logger.exception("Renewal certificate generation failed for request %s", renewal.id)

    renewal.new_esim_validity = new_expiry_dt
    renewal.status = 'success'
    renewal.save()

    return Response({
        "status": "success",
        "message": "Device renewed successfully.",
        "data": DeviceRenewalRequestListSerializer(renewal).data,
    }, status=status.HTTP_200_OK)


@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@require_permission('device_renewal_management', 'view')
def device_renewal_history_list(request):
    """
    GET or POST /api/device-renewal/history/

    Renewal request history, role-scoped:
      - superadmin: all requests.
      - manufacturer: only requests for devices under their own device models.
      - dealer: only requests they themselves submitted (their own DeviceRenewalRequest.dealer).

    Optional filters (query string on GET, body on POST):
        status       filter by DeviceRenewalRequest.status
        search       partial match on device imei/iccid
        page         default 1
        page_size    default 25, max 100
    """
    user = request.user
    qs = DeviceRenewalRequest.objects.select_related(
        'device', 'device_tag', 'requested_by', 'dealer', 'manufacturer'
    )

    if user.role == 'superadmin':
        pass
    elif user.role == 'devicemanufacture':
        manufacturer = get_user_object(user, 'devicemanufacture')
        if not manufacturer:
            return Response(
                {"status": "error", "message": "Manufacturer profile not found."},
                status=status.HTTP_404_NOT_FOUND
            )
        qs = qs.filter(device__model__created_by__in=manufacturer.users.all())
    elif user.role == 'dealer':
        dealer = get_user_object(user, 'dealer')
        if not dealer:
            return Response(
                {"status": "error", "message": "Dealer profile not found."},
                status=status.HTTP_404_NOT_FOUND
            )
        qs = qs.filter(dealer=dealer)
    else:
        return Response(
            {"status": "error", "message": "Your role cannot view renewal history."},
            status=status.HTTP_403_FORBIDDEN
        )

    params = request.data if request.method == 'POST' else request.query_params

    status_filter = str(params.get('status') or '').strip()
    if status_filter:
        qs = qs.filter(status=status_filter)

    search = str(params.get('search') or '').strip()
    if search:
        qs = qs.filter(Q(device__imei__icontains=search) | Q(device__iccid__icontains=search))

    qs = qs.order_by('-created_at')

    total_count = qs.count()
    page, page_size = _paginate_params(params)
    start = (page - 1) * page_size
    page_entries = qs[start:start + page_size]

    serializer = DeviceRenewalRequestListSerializer(page_entries, many=True)
    return Response({
        "status": "success",
        "data": serializer.data,
        "pagination": _pagination_meta(page, page_size, total_count),
    }, status=status.HTTP_200_OK)


def _get_owner_mobile(vehicle_owner):
    """Registered mobile of the vehicle owner's active user account."""
    owner_user = vehicle_owner.users.filter(status='active').first()
    if not owner_user or not owner_user.mobile:
        return None, None
    return owner_user.mobile, getattr(owner_user, 'email', None)


def _check_step5_prerequisites(record):
    """
    The three checks specified before the owner OTP is sent:

      1. all required GPS packets were received
      2. that check is still inside the freshness window
      3. every earlier step completed properly

    Returns an error message, or None when the record is ready.
    """
    if not record.step1_completed_at:
        return "Step 1 is not complete for this entry."
    if not record.step2_completed_at:
        return "Step 2 is not complete for this entry."
    if not record.step3_completed_at or not record.dealer_otp_verified_at:
        return "Dealer OTP has not been verified for this entry."
    if not record.step4_completed_at:
        return "Step 4 is not complete for this entry."

    if not record.packets_all_received:
        return "Required GPS packets have not been received. Please complete step 4 again."

    if not record.packets_checked_at:
        return "GPS packets have not been checked. Please complete step 4 again."

    age = timezone.now() - record.packets_checked_at
    if age > timedelta(hours=GPS_PACKET_FRESHNESS_HOURS):
        return (
            f"The GPS packet check is more than {GPS_PACKET_FRESHNESS_HOURS} hours old. "
            "Please run step 4 again before requesting the owner OTP."
        )

    return None


def _as_end_of_day(d):
    """
    DeviceStock.esim_validity is a DateTimeField but the provider gives a
    date. Store end of that day so a SIM is not treated as expired on its
    own expiry date.
    """
    if not d:
        return None
    naive = datetime.combine(d, dtime(23, 59, 59))
    return timezone.make_aware(naive) if timezone.is_naive(naive) else naive


def _blank_to_none(value):
    """
    Several DeviceStock columns are unique AND nullable (msisdn2, iccid2).
    Storing '' in them would collide between any two devices with no
    fallback SIM, so blanks must become NULL.
    """
    value = (value or '').strip()
    return value or None
  
# =====================================================================
# SECTION 4 
# STEP 5 
# =====================================================================
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step5_send_owner_otp(request):
    """
    POST /api/device-tagging/step5/send-otp/
 
    Sends a 6-digit OTP to the vehicle owner's registered mobile — the
    owner resolved from the phone number given in step 1.
 
    Callable repeatedly while the record sits at step 5, subject to a
    cooldown. Also serves as the resend endpoint.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)
 
    record_id = request.data.get('id')
 
    # ── Common checks + must be sitting at step 5 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=5)
    if error:
        return error
 
    # ── Everything before this step must genuinely be complete ───────
    prerequisite_error = _check_step5_prerequisites(record)
    if prerequisite_error:
        return Response({"error": prerequisite_error}, status=status.HTTP_400_BAD_REQUEST)
 
    owner_mobile, owner_email = _get_owner_mobile(record.vehicle_owner)
    if not owner_mobile:
        return Response(
            {"error": "The vehicle owner has no active account with a registered mobile number."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    now = timezone.now()
 
    # ── Cooldown ─────────────────────────────────────────────────────
    if record.owner_otp_sent_at:
        elapsed = (now - record.owner_otp_sent_at).total_seconds()
        if elapsed < TAGGING_OTP_RESEND_COOLDOWN_SECONDS:
            wait = int(TAGGING_OTP_RESEND_COOLDOWN_SECONDS - elapsed)
            return Response(
                {
                    "error": f"Please wait {wait} more second(s) before requesting a new OTP.",
                    "retry_after_seconds": wait,
                },
                status=status.HTTP_400_BAD_REQUEST
            )
 
    otp = str(secrets.randbelow(1000000)).zfill(6)
    record.owner_otp = otp
    record.owner_otp_sent_at = now
    record.owner_otp_attempts = 0
    record.updated_by = request.user
    record.save(update_fields=[
        'owner_otp', 'owner_otp_sent_at', 'owner_otp_attempts',
        'updated_by', 'updated_at'
    ])
 
    _send_tagging_otp(
        mobile=owner_mobile,
        email=owner_email,
        otp=otp,
        vehicle_reg_no=record.vahan_reg_no,
        imei=record.imei,
    )
 
    return Response({
        "status": "success",
        "message": "OTP has been sent to the vehicle owner's registered mobile number.",
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            # Masked — the dealer should not be able to read the owner's number
            # off this endpoint.
            "owner_mobile": f"{owner_mobile[:2]}xxxxxx{owner_mobile[-2:]}",
            "otp_sent_at": record.owner_otp_sent_at,
            "otp_expires_in_hours": TAGGING_OTP_EXPIRY_HOURS,
        }
    }, status=status.HTTP_200_OK)
 
 
# =====================================================================
# SECTION 5 
# STEP 5
# =====================================================================
 
@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
@transaction.atomic
def device_tagging_step5_verify_owner_otp(request):
    """
    POST /api/device-tagging/step5/verify-otp/
 
    The owner receives the OTP and passes it to the dealer, who submits it
    here. On success this creates the real records:
 
      - one DeviceStock row  (device + SIM details)
      - one DeviceTag row    (vehicle details, linked to the stock row)
 
    Both are created in a single transaction with the record update, so a
    failure part-way leaves nothing behind.
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)
 
    record_id = request.data.get('id')
    submitted_otp = str(request.data.get('otp') or '').strip()
 
    # ── Common checks + must be sitting at step 5 ────────────────────
    record, dealer, error = _get_tagging_record(request, record_id, expected_step=5)
    if error:
        return error
 
    if not submitted_otp:
        return Response({"error": "otp is required."}, status=status.HTTP_400_BAD_REQUEST)
 
    prerequisite_error = _check_step5_prerequisites(record)
    if prerequisite_error:
        return Response({"error": prerequisite_error}, status=status.HTTP_400_BAD_REQUEST)
 
    if not record.owner_otp or not record.owner_otp_sent_at:
        return Response(
            {"error": "No OTP is pending for this entry. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    now = timezone.now()
 
    if now > record.owner_otp_sent_at + timedelta(hours=TAGGING_OTP_EXPIRY_HOURS):
        return Response(
            {"error": "This OTP has expired. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    if record.owner_otp_attempts >= TAGGING_OTP_MAX_ATTEMPTS:
        return Response(
            {"error": "Too many incorrect attempts. Please request a new OTP."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    if not _tagging_otp_matches(record.owner_otp, submitted_otp):
        record.owner_otp_attempts += 1
        remaining = TAGGING_OTP_MAX_ATTEMPTS - record.owner_otp_attempts
 
        if remaining <= 0:
            record.owner_otp = None
            record.save(update_fields=['owner_otp', 'owner_otp_attempts', 'updated_at'])
            return Response(
                {"error": "Too many incorrect attempts. Please request a new OTP."},
                status=status.HTTP_400_BAD_REQUEST
            )
 
        record.save(update_fields=['owner_otp_attempts', 'updated_at'])
        return Response(
            {"error": "Incorrect OTP.", "attempts_remaining": remaining},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── OTP verified. Build the final records. ───────────────────────
 
    reg_no = (record.vahan_reg_no or '').strip().upper()
    engine_no = (record.vahan_engine_no or '').strip().upper()
    chassis_no = (record.vahan_chassis_no or '').strip().upper()
    device_esn = (record.vahan_device_serial_no or '').strip()
    msisdn1 = (record.m2m_primary_msisdn or '').strip()
    msisdn2 = _blank_to_none(record.m2m_fallback_msisdn)
 
    # ── Last-moment uniqueness check ─────────────────────────────────
    # Step 1 checked what it could, but another dealer may have tagged the
    # same device in the meantime. Checking here turns a database
    # IntegrityError into a readable message.
    conflicts = {}
    if DeviceStock.objects.filter(imei=record.imei).exists():
        conflicts['imei'] = "already exists in device stock"
    if DeviceStock.objects.filter(iccid=record.iccid).exists():
        conflicts['iccid'] = "already exists in device stock"
    if device_esn and DeviceStock.objects.filter(device_esn=device_esn).exists():
        conflicts['device_esn'] = "already exists in device stock"
    if msisdn1 and DeviceStock.objects.filter(msisdn1=msisdn1).exists():
        conflicts['msisdn1'] = "already exists in device stock"
    if msisdn2 and DeviceStock.objects.filter(msisdn2=msisdn2).exists():
        conflicts['msisdn2'] = "already exists in device stock"
    if reg_no and DeviceTag.objects.filter(vehicle_reg_no=reg_no).exists():
        conflicts['vehicle_reg_no'] = "already tagged to a device"
    if engine_no and DeviceTag.objects.filter(engine_no=engine_no).exists():
        conflicts['engine_no'] = "already tagged to a device"
    if chassis_no and DeviceTag.objects.filter(chassis_no=chassis_no).exists():
        conflicts['chassis_no'] = "already tagged to a device"
 
    if conflicts:
        return Response(
            {
                "error": "This device or vehicle has already been registered elsewhere.",
                "conflicts": conflicts,
            },
            status=status.HTTP_400_BAD_REQUEST
        )
 
    if not msisdn1:
        return Response(
            {"error": "No primary MSISDN was returned by the eSIM provider. Please run step 2 again."},
            status=status.HTTP_400_BAD_REQUEST
        )
    if not device_esn:
        return Response(
            {"error": "No device serial number is stored for this entry."},
            status=status.HTTP_400_BAD_REQUEST
        )
 
    # ── Create DeviceStock — device and SIM ──────────────────────────
    device_stock = DeviceStock.objects.create(
        model=record.device_model,
        device_esn=device_esn,
        imei=record.imei,
        iccid=record.iccid,
        iccid2=None,
        telecom_provider1=(record.m2m_primary_tsp or '')[:25],
        telecom_provider2=(_blank_to_none(record.m2m_fallback_tsp) or None),
        msisdn1=msisdn1,
        msisdn2=msisdn2,
        imsi1=None,   # the provider API does not return IMSI
        imsi2=None,
        esim_validity=_as_end_of_day(record.m2m_expiry_date),
        remarks=f"Created by tagging flow from DeviceStockMaster #{record.id}",
        created=now,
        created_by=request.user,
        dealer=record.dealer,
        stock_status=TAGGING_FINAL_STOCK_STATUS,
        esim_status=TAGGING_FINAL_ESIM_STATUS,
    )
    device_stock.esim_provider.add(record.esim_provider)
 
    # ── Create DeviceTag — vehicle, linked to the stock row ──────────
    # vehicle_make / vehicle_model are 55 chars on DeviceTag but 255 on
    # DeviceStockMaster, so they are trimmed rather than risking a failure
    # at the very last step of a five-step flow.
    device_tag = DeviceTag.objects.create(
        device=device_stock,
        esim_provider=record.esim_provider,
        vehicle_owner=record.vehicle_owner,
        vehicle_reg_no=reg_no,
        engine_no=engine_no,
        chassis_no=chassis_no,
        vehicle_make=(record.vahan_maker_name or '')[:55],
        vehicle_model=(record.vahan_model_name or '')[:55],
        category=record.category,
        district=record.district,
        rc_file=record.rc_file,
        device_sell_amount=record.device_sell_amount,
        no_of_emg_buttons=record.no_of_emg_buttons,
        receipt_file_or='',   # not collected in this flow, 
        receipt_file_ul='',   # not collected in this flow, 
        status=TAGGING_FINAL_TAG_STATUS,
        tagged_by=request.user,
        tagged=now,
    )
 
    # ── Close out the staging record ─────────────────────────────────
    record.owner_otp_verified_at = now
    record.owner_otp_attempts = 0
    record.step5_completed_at = now
    record.current_step = 6          # 6 = Completed
    record.created_device_stock = device_stock
    record.created_device_tag = device_tag
    record.updated_by = request.user
    record.save(update_fields=[
        'owner_otp_verified_at', 'owner_otp_attempts', 'step5_completed_at',
        'current_step', 'created_device_stock', 'created_device_tag',
        'updated_by', 'updated_at'
    ])
 
    return Response({
        "status": "success",
        "message": "Owner OTP verified. Tagging completed successfully.",
        "data": {
            "id": record.id,
            "current_step": record.current_step,
            "owner_otp_verified_at": record.owner_otp_verified_at,
            "step5_completed_at": record.step5_completed_at,
            "device_stock": {
                "id": device_stock.id,
                "device_esn": device_stock.device_esn,
                "imei": device_stock.imei,
                "iccid": device_stock.iccid,
                "msisdn1": device_stock.msisdn1,
                "msisdn2": device_stock.msisdn2,
                "telecom_provider1": device_stock.telecom_provider1,
                "esim_validity": device_stock.esim_validity,
                "stock_status": device_stock.stock_status,
                "esim_status": device_stock.esim_status,
            },
            "device_tag": {
                "id": device_tag.id,
                "vehicle_reg_no": device_tag.vehicle_reg_no,
                "is_temp_reg_no": record.is_temp_reg_no,
                "engine_no": device_tag.engine_no,
                "chassis_no": device_tag.chassis_no,
                "vehicle_make": device_tag.vehicle_make,
                "vehicle_model": device_tag.vehicle_model,
                "category": device_tag.category.category,
                "district": device_tag.district.district if device_tag.district else None,
                "rc_file": device_tag.rc_file,
                "status": device_tag.status,
            },
        }
    }, status=status.HTTP_200_OK)









# =====================================================================
# TAGGING FLOW — SUPPORTING APIs
# =====================================================================
#   1. My entries with step status  (drives the resume feature)
#   2. My manufacturer 
#
# =====================================================================


# =====================================================================
# SECTION 1 
# =====================================================================

# Human-readable label for each step a record can be sitting at.
TAGGING_STEP_LABELS = {
    2: 'eSIM verification pending',
    3: 'Dealer OTP pending',
    4: 'GPS packet check pending',
    5: 'Owner OTP pending',
    6: 'Completed',
}

# Default and maximum page size for the entries list.
TAGGING_LIST_PAGE_SIZE = 25
TAGGING_LIST_MAX_PAGE_SIZE = 100


# =====================================================================
# SECTION 2 
# =====================================================================

def _tagging_step_progress(record):
    """
    Which steps are done and which are still pending for one record.

    Reported from the per-step completion timestamps rather than from
    current_step alone, so the response shows the actual audit trail.
    """
    completed_at = {
        1: record.step1_completed_at,
        2: record.step2_completed_at,
        3: record.step3_completed_at,
        4: record.step4_completed_at,
        5: record.step5_completed_at,
    }

    steps = []
    for number in range(1, 6):
        steps.append({
            'step': number,
            'completed': bool(completed_at[number]),
            'completed_at': completed_at[number],
        })

    return {
        'steps': steps,
        'completed_steps': [n for n in range(1, 6) if completed_at[n]],
        'pending_steps': [n for n in range(1, 6) if not completed_at[n]],
    }


# =====================================================================
# SECTION 3
# SUPPORTING API 1 — MY ENTRIES WITH STEP STATUS
# =====================================================================

@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def device_tagging_my_entries(request):
    """
    GET or POST /api/device-tagging/my-entries/

    Every non-deleted DeviceStockMaster entry created by the calling
    dealer, with which steps are complete and which are still pending.

    This is what makes the flow resumable: a dealer who abandoned tagging
    halfway can see exactly where each entry stopped and continue from
    there, instead of starting again.

    Optional filters (query string on GET, body on POST):
        current_step  int   only entries sitting at this step
        is_completed  bool  true = finished, false = still in progress
        imei          str   partial match
        iccid         str   partial match
        vehicle_reg_no str  partial match
        page          int   default 1
        page_size     int   default 25, max 100
    """
    dealer, error = _get_tagging_dealer(request)
    if error:
        return error

    params = request.data if request.method == 'POST' else request.query_params

    entries = DeviceStockMaster.objects.filter(
        created_by=request.user,
        is_deleted=False,
    ).select_related(
        'manufacturer', 'device_model', 'esim_provider',
        'district', 'category', 'vehicle_owner',
        'created_device_stock', 'created_device_tag',
    ).prefetch_related(
        'vehicle_owner__users',
    ).order_by('-created_at')

    # ── Filters ──────────────────────────────────────────────────────
    current_step = params.get('current_step')
    if current_step not in (None, ''):
        try:
            entries = entries.filter(current_step=int(current_step))
        except (TypeError, ValueError):
            return Response(
                {"error": "current_step must be a number between 2 and 6."},
                status=status.HTTP_400_BAD_REQUEST
            )

    is_completed = params.get('is_completed')
    if is_completed not in (None, ''):
        wants_completed = str(is_completed).strip().lower() in ('true', '1', 'yes')
        if wants_completed:
            entries = entries.filter(current_step=6)
        else:
            entries = entries.exclude(current_step=6)

    imei = str(params.get('imei') or '').strip()
    if imei:
        entries = entries.filter(imei__icontains=imei)

    iccid = str(params.get('iccid') or '').strip()
    if iccid:
        entries = entries.filter(iccid__icontains=iccid)

    reg_no = str(params.get('vehicle_reg_no') or '').strip()
    if reg_no:
        entries = entries.filter(vahan_reg_no__icontains=reg_no)

    # ── Counts per step, before pagination ───────────────────────────
    # Lets the UI show "3 waiting on owner OTP" without a second request.
    step_counts = {label: 0 for label in TAGGING_STEP_LABELS.values()}
    raw_counts = entries.values('current_step').annotate(total=Count('id'))
    for row in raw_counts:
        label = TAGGING_STEP_LABELS.get(row['current_step'])
        if label:
            step_counts[label] = row['total']

    total_count = entries.count()

    # ── Pagination ───────────────────────────────────────────────────
    try:
        page = max(1, int(params.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        page_size = int(params.get('page_size') or TAGGING_LIST_PAGE_SIZE)
    except (TypeError, ValueError):
        page_size = TAGGING_LIST_PAGE_SIZE
    page_size = max(1, min(page_size, TAGGING_LIST_MAX_PAGE_SIZE))

    start = (page - 1) * page_size
    page_entries = entries[start:start + page_size]

    # ── Build the response ───────────────────────────────────────────
    data = []
    for record in page_entries:
        progress = _tagging_step_progress(record)

        # Uses the prefetched list rather than a fresh query per record.
        owner_users = list(record.vehicle_owner.users.all())
        owner_user = next(
            (u for u in owner_users if u.status == 'active'), None
        ) or (owner_users[0] if owner_users else None)

        data.append({
            'id': record.id,
            'current_step': record.current_step,
            'current_step_label': TAGGING_STEP_LABELS.get(record.current_step),
            'is_completed': record.current_step == 6,
            'imei': record.imei,
            'iccid': record.iccid,
            'vehicle_reg_no': record.vahan_reg_no,
            'is_temp_reg_no': record.is_temp_reg_no,
            'chassis_no': record.vahan_chassis_no,
            'manufacturer': {
                'id': record.manufacturer_id,
                'company_name': record.manufacturer.company_name,
            },
            'device_model': {
                'id': record.device_model_id,
                'model_name': record.device_model.model_name,
            },
            'esim_provider': {
                'id': record.esim_provider_id,
                'company_name': record.esim_provider.company_name,
            },
            'district': {
                'id': record.district_id,
                'district': record.district.district,
                'district_code': record.district.district_code,
            },
            'category': {
                'id': record.category_id,
                'category': record.category.category,
            },
            'vehicle_owner': {
                'id': record.vehicle_owner_id,
                'company_name': record.vehicle_owner.company_name,
                'name': owner_user.name if owner_user else None,
                'mobile': owner_user.mobile if owner_user else None,
                'email': owner_user.email if owner_user else None,
                # Owner name as it appears on Vahan — may differ from the
                # name on the Skytron account.
                'vahan_owner_name': record.vahan_owner_name,
            },
            'packets_all_received': record.packets_all_received,
            'packets_checked_at': record.packets_checked_at,
            'steps': progress['steps'],
            'completed_steps': progress['completed_steps'],
            'pending_steps': progress['pending_steps'],
            'created_device_stock_id': record.created_device_stock_id,
            'created_device_tag_id': record.created_device_tag_id,
            'created_at': record.created_at,
            'updated_at': record.updated_at,
        })

    total_pages = (total_count + page_size - 1) // page_size if total_count else 0

    return Response({
        'status': 'success',
        'data': data,
        'summary': {
            'total_entries': total_count,
            'by_step': step_counts,
        },
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': total_pages,
            'has_next': page < total_pages,
            'has_previous': page > 1,
        },
    }, status=status.HTTP_200_OK)


# =====================================================================
# SECTION 4 
# SUPPORTING API 2 — MY MANUFACTURER / MODELS / PROVIDERS
# =====================================================================

@api_view(['GET'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def device_tagging_my_manufacturer(request):
    """
    GET /api/device-tagging/my-manufacturer/

    No input. Returns the calling dealer's manufacturer, that
    manufacturer's device models whose technical onboarding is complete,
    and each model's M2M / eSIM providers.

    Feeds the dropdowns on the step 1 form, so it only lists options that
    would actually pass step 1's validation.
    """
    dealer, error = _get_tagging_dealer(request)
    if error:
        return error

    manufacturer = dealer.manufacturer

    # DeviceModel has no FK to Manufacturer — the link is through
    # created_by. users.all(), not users.first(), so models created by a
    # second manufacturer user are not silently missed.
    models_qs = DeviceModel.objects.filter(
        created_by__in=manufacturer.users.all()
    ).prefetch_related('eSimProviders').order_by('model_name')

    # One query for every approved onboarding, rather than one per model.
    approved_model_ids = set(
        DeviceModelTechnicalOnboardingRequest.objects.filter(
            device_model__in=models_qs,
            status='StateAdminApproved',
        ).values_list('device_model_id', flat=True)
    )

    models_data = []
    for device_model in models_qs:
        if device_model.id not in approved_model_ids:
            continue

        providers = []
        for provider in device_model.eSimProviders.all():
            providers.append({
                'id': provider.id,
                'company_name': provider.company_name,
                # A provider that has not passed M2M onboarding will be
                # rejected at step 1, so the UI can grey it out.
                'm2m_api_verified': bool(provider.m2m_api_verified),
                'm2m_technical_onboarding_status': provider.m2m_technical_onboarding_status,
            })

        models_data.append({
            'id': device_model.id,
            'model_name': device_model.model_name,
            'vendor_id': device_model.vendor_id,
            'tac_no': device_model.tac_no,
            'hardware_version': device_model.hardware_version,
            'technical_onboarding_complete': True,
            'esim_providers': providers,
            # Empty list means no combination is required at step 1.
            'provider_combinations': device_model.provider_combinations or [],
        })

    districts = [
        {
            'id': d.id,
            'district': d.district,
            'district_code': d.district_code,
        }
        for d in dealer.districts.filter(status='active').order_by('district')
    ]

    return Response({
        'status': 'success',
        'data': {
            'dealer': {
                'id': dealer.id,
                'company_name': dealer.company_name,
            },
            'manufacturer': {
                'id': manufacturer.id,
                'company_name': manufacturer.company_name,
            },
            # Step 1 needs a district when the dealer covers more than one.
            'districts': districts,
            'district_required': len(districts) > 1,
            'device_models': models_data,
        },
    }, status=status.HTTP_200_OK)





# =====================================================================
# CERTIFICATE API
# =====================================================================

@api_view(['POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def device_tagging_certificate(request):
    """
    POST /api/device-tagging/certificate/

    Certificate details for one completed tagging, looked up by IMEI.

    Only records where tagging is fully complete (owner OTP verified,
    step 5 done) are returned — a certificate cannot be issued for a
    tagging still in progress.

    Body:
        { "imei": "861850060253620" }
    """
    errors = validate_inputs(request)
    if errors:
        return Response({'errors': errors}, status=status.HTTP_400_BAD_REQUEST)

    dealer, error = _get_tagging_dealer(request)
    if error:
        return error

    imei = str(request.data.get('imei') or '').strip()
    if not imei:
        return Response(
            {"errors": {"imei": "This field is required."}},
            status=status.HTTP_400_BAD_REQUEST
        )

    record = DeviceStockMaster.objects.filter(
        imei=imei,
        created_by=request.user,
        is_deleted=False,
        current_step=6,
    ).select_related(
        'dealer', 'district', 'created_device_tag'
    ).last()

    if not record:
        # Distinguish "not finished" from "not found" — the dealer needs
        # to know which.
        in_progress = DeviceStockMaster.objects.filter(
            imei=imei, created_by=request.user, is_deleted=False
        ).last()
        if in_progress:
            return Response(
                {
                    "error": "Tagging is not completed for this IMEI.",
                    "current_step": in_progress.current_step,
                },
                status=status.HTTP_400_BAD_REQUEST
            )
        return Response(
            {"error": "No completed tagging found for this IMEI."},
            status=status.HTTP_400_BAD_REQUEST
        )

    device_tag = record.created_device_tag
    if not device_tag:
        return Response(
            {"error": "No device tag was created for this entry."},
            status=status.HTTP_400_BAD_REQUEST
        )

    serializer = VahanSerializer(device_tag)

    return Response({
        "status": "success",
        "Skytrack_data": serializer.data,
        "certificate_data": _build_certificate_fields(record),
    },status=status.HTTP_200_OK)
    
    


# =====================================================================
# CERTIFICATE LIST API
# =====================================================================

@api_view(['GET', 'POST'])
@permission_classes([IsAuthenticated])
@throttle_classes([AnonRateThrottle, UserRateThrottle])
def device_tagging_certificate_list(request):
    """
    GET or POST /api/device-tagging/certificate-list/

    All completed taggings for the calling dealer, with the certificate
    fields for each.

    Optional filters (query string on GET, body on POST):
        imei            partial match
        vehicle_reg_no  partial match
        search          partial match on either of the above
        page            default 1
        page_size       default 25, max 100
    """
    dealer, error = _get_tagging_dealer(request)
    if error:
        return error

    params = request.data if request.method == 'POST' else request.query_params

    entries = DeviceStockMaster.objects.filter(
        created_by=request.user,
        is_deleted=False,
        current_step=6,
    ).select_related(
        'dealer', 'district', 'category', 'device_model',
        'created_device_stock', 'created_device_tag',
    ).order_by('-step5_completed_at')

    imei = str(params.get('imei') or '').strip()
    if imei:
        entries = entries.filter(imei__icontains=imei)

    reg_no = str(params.get('vehicle_reg_no') or '').strip()
    if reg_no:
        entries = entries.filter(vahan_reg_no__icontains=reg_no)

    # One box that searches either field, for a single search input.
    search = str(params.get('search') or '').strip()
    if search:
        entries = entries.filter(
            Q(imei__icontains=search) | Q(vahan_reg_no__icontains=search)
        )

    total_count = entries.count()

    try:
        page = max(1, int(params.get('page') or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        page_size = int(params.get('page_size') or TAGGING_LIST_PAGE_SIZE)
    except (TypeError, ValueError):
        page_size = TAGGING_LIST_PAGE_SIZE
    page_size = max(1, min(page_size, TAGGING_LIST_MAX_PAGE_SIZE))

    start = (page - 1) * page_size
    page_entries = entries[start:start + page_size]

    data = []
    for record in page_entries:
        certificate = _build_certificate_fields(record)
        data.append({
            "id": record.id,
            "imei": record.imei,
            "iccid": record.iccid,
            "vehicle_reg_no": record.vahan_reg_no,
            "is_temp_reg_no": record.is_temp_reg_no,
            "chassis_no": record.vahan_chassis_no,
            "engine_no": record.vahan_engine_no,
            "vehicle_make": record.vahan_maker_name,
            "vehicle_model": record.vahan_model_name,
            "category": record.category.category if record.category else '',
            "device_model": (
                record.device_model.model_name if record.device_model else ''
            ),
            "device_sell_amount": record.device_sell_amount,
            "tagged_at": record.step5_completed_at,
            "device_stock_id": record.created_device_stock_id,
            "device_tag_id": record.created_device_tag_id,
            **certificate,
        })

    total_pages = (total_count + page_size - 1) // page_size if total_count else 0

    return Response({
        "status": "success",
        "data": data,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total_count": total_count,
            "total_pages": total_pages,
            "has_next": page < total_pages,
            "has_previous": page > 1,
        },
    }, status=status.HTTP_200_OK)